1	// IMAP engine for the native webmail client.
2	//
3	// Plain server-side module (NOT "use server"): it holds the short-lived imapflow
4	// connection helpers, special-use → role mapping, and the mailbox-ownership
5	// resolver shared by the server actions (lib/actions-mail.ts) and the attachment
6	// download route (app/api/mail/attachment/route.ts). Every connection is opened
7	// per-request and always closed. It is never imported into a client bundle.
8	
9	import { ImapFlow } from "imapflow";
10	import type {
11	  FetchMessageObject,
12	  MailboxLockOptions,
13	  MessageAddressObject,
14	  MessageStructureObject,
15	} from "imapflow";
16	import { requireUser } from "@/lib/auth";
17	import { isStaff } from "@/lib/rbac";
18	import { hasAreaAccess } from "@/lib/staff-grants";
19	import { canAccessMailbox } from "@/lib/staff-mailbox-access";
20	import { db } from "@/lib/db";
21	import { decryptSecret } from "@/lib/crypto-box";
22	import { COMPANY_MAIL_DOMAIN } from "@/lib/company-mail-core";
23	import { checkRateLimit } from "@/lib/rate-limit";
24	import { mailcowConfigured, mcListMailboxes } from "@/lib/mailcow";
25	import { MAIL_IMAP_HOST, MAIL_IMAP_PORT, type MailAddress, type MailFolderRole } from "./types";
26	import type { User } from "@prisma/client";
27	
28	// mailparser ships no bundled type declarations and its untyped JS module can't
29	// be augmented via `declare module`. Instead we describe the slice we use with
30	// local interfaces and import `simpleParser` with a suppressed-error import,
31	// exposing a single typed `parseMessage` wrapper for the rest of the backend.
32	// @ts-ignore -- mailparser has no type declarations
33	import { simpleParser as _simpleParser } from "mailparser";
34	
35	export interface ParsedAttachment {
36	  type?: string;
37	  partId?: string;
38	  filename?: string;
39	  contentType?: string;
40	  contentDisposition?: string;
41	  size?: number;
42	  content?: Buffer;
43	  cid?: string;
44	  contentId?: string;
45	  related?: boolean;
46	}
47	export interface ParsedMessage {
48	  subject?: string;
49	  from?: { value?: { name?: string; address?: string }[]; text?: string };
50	  to?: unknown;
51	  cc?: unknown;
52	  bcc?: unknown;
53	  date?: Date;
54	  messageId?: string;
55	  inReplyTo?: string;
56	  references?: string | string[];
57	  html?: string | false;
58	  text?: string;
59	  textAsHtml?: string;
60	  attachments: ParsedAttachment[];
61	}
62	
63	const simpleParser = _simpleParser as (
64	  source: Buffer | string,
65	  options?: Record<string, unknown>,
66	) => Promise<ParsedMessage>;
67	
68	/** Parse a raw RFC822 message source into a typed structure (via mailparser). */
69	export async function parseMessage(source: Buffer | string): Promise<ParsedMessage> {
70	  return simpleParser(source);
71	}
72	
73	/** The TLS servername the mail server's certificate is issued for. */
74	export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";
75	
76	/**
77	 * TLS options for every webmail connection to the mail server (IMAP 993 and
78	 * SMTP submission 587). Shared so the two cannot drift apart.
79	 *
80	 * WHY VERIFICATION IS ON. We connect by internal IP (10.20.0.10) while the
81	 * server presents a public certificate for `mail.nxeon.cloud`, so a bare
82	 * connection fails on the name mismatch. The previous code resolved that by
83	 * setting `rejectUnauthorized: false` — which does not just tolerate the name
84	 * mismatch, it accepts ANY certificate from anything answering on that address.
85	 * The very first thing sent over that session is the customer's mailbox password
86	 * (IMAP LOGIN / SMTP AUTH), so anyone able to answer on the NAT bridge could
87	 * have harvested every mailbox credential on the platform, and nothing would
88	 * have looked wrong. `servername` alone is the correct fix: it sets SNI *and*
89	 * the name validation is performed against, so the real certificate verifies.
90	 *
91	 * MEASURED, not assumed (2026-07-27, from the app host):
92	 *   openssl s_client -connect 10.20.0.10:993 -servername mail.nxeon.cloud \
93	 *     -verify_return_error   ->  CN=mail.nxeon.cloud, "Verification: OK"
94	 *   …and the same on :587 with -starttls smtp.
95	 *
96	 * `MAIL_TLS_INSECURE=1` is a documented break-glass for an operator whose
97	 * certificate has genuinely expired mid-incident: it restores the old behaviour
98	 * from `.env` without a code change. It defaults OFF, so the safe state is the
99	 * one you get by doing nothing — the opposite of what it replaces.
100	 */
101	export function mailTlsOptions(): { servername: string; rejectUnauthorized: boolean } {
102	  return {
103	    servername: MAIL_TLS_SERVERNAME,
104	    rejectUnauthorized: process.env.MAIL_TLS_INSECURE !== "1",
105	  };
106	}
107	
108	/** Minimal credential shape needed to authenticate an IMAP/SMTP session. */
109	export type MailboxCredentials = { address: string; password: string };
110	
111	/** The sender identity the customer configured, applied to every outgoing message. */
112	export type MailboxIdentity = {
113	  displayName: string | null;
114	  replyTo: string | null;
115	  organization: string | null;
116	};
117	
118	/** The subscription context a mailbox hangs off, for verification-aware guards. */
119	export type ResolvedSubscription = {
120	  id: string;
121	  domainName: string;
122	  external: boolean;
123	  verified: boolean;
124	  status: string;
125	};
126	
127	/** A user mailbox row plus the decrypted credential, resolved + ownership-checked. */
128	export type ResolvedMailbox = {
129	  user: User;
130	  mailboxId: string;
131	  address: string;
132	  quotaMB: number | null;
133	  cred: MailboxCredentials;
134	  identity: MailboxIdentity;
135	  subscription: ResolvedSubscription;
136	};
137	
138	/**
139	 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
140	 *
141	 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
142	 * the mail server — or one whose row was lost — was invisible in the portal even
143	 * though real mail was landing in it ("its not detecting the mailbox that i
144	 * already have on this account"). This reconciles the two.
145	 *
146	 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
147	 * a way to acquire someone else's mailbox:
148	 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
149	 *   2. Only subscriptions with `verified === true` are eligible. Owning a
150	 *      subscription ROW is not proof of owning the DOMAIN — an unverified
151	 *      external subscription is just a claim, and adopting on a claim would
152	 *      re-open the cross-tenant takeover fixed on 2026-07-25 by a side door.
153	 *   3. `Mailbox.address` is globally `@unique`, and we skip any address that
154	 *      already has a row, so a mailbox another tenant legitimately holds is
155	 *      never re-pointed at this user.
156	 *   4. `passwordEnc` is left NULL. We never learn the existing password, so the
157	 *      customer is told to reset it — adoption grants visibility, not access.
158	 *
159	 * Never throws: a Mailcow outage must not turn the mail page into an error.
160	 * Returns the number of rows created.
161	 */
162	export async function discoverMailboxes(userId: string): Promise<number> {
163	  if (!mailcowConfigured()) return 0;
164	
165	  // Guard against hammering Mailcow: the mail page calls this on every load for
166	  // an account with no mailbox, which is exactly the account that reaches here.
167	  const gate = checkRateLimit(`mail:discover:${userId}`, { max: 1, windowMs: 30_000 });
168	  if (!gate.ok) return 0;
169	
170	  const subs = await db.emailSubscription.findMany({
171	    where: { userId, status: { not: "CANCELLED" }, verified: true },
172	    select: { id: true, domainName: true },
173	  });
174	  if (subs.length === 0) return 0;
175	
176	  let created = 0;
177	  for (const sub of subs) {
178	    const domain = sub.domainName.trim().toLowerCase();
179	    if (!domain) continue;
180	
181	    let remote: Awaited<ReturnType<typeof mcListMailboxes>>;
182	    try {
183	      remote = await mcListMailboxes(domain);
184	    } catch (e) {
185	      console.warn(`[mailcow] discovery for ${domain} failed:`, e);
186	      continue;
187	    }
188	    if (remote.length === 0) continue;
189	
190	    const existing = await db.mailbox.findMany({
191	      where: { address: { in: remote.map((m) => m.address) } },
192	      select: { address: true },
193	    });
194	    const known = new Set(existing.map((m) => m.address.toLowerCase()));
195	
196	    for (const m of remote) {
197	      if (known.has(m.address)) continue;
198	      try {
199	        await db.mailbox.create({
200	          data: {
201	            subscriptionId: sub.id,
202	            address: m.address,
203	            quotaMB: m.quotaBytes > 0 ? Math.round(m.quotaBytes / (1024 * 1024)) : null,
204	            status: m.active ? "ACTIVE" : "SUSPENDED",
205	            displayName: m.name && m.name !== m.address ? m.name : null,
206	          },
207	        });
208	        created++;
209	      } catch {
210	        // Unique-violation race (two tabs discovering at once) — the row exists
211	        // now either way, which is the outcome we wanted.
212	      }
213	    }
214	  }
215	
216	  if (created > 0) {
217	    await db.auditLog
218	      .create({ data: { userId, action: "mailbox.discover", detail: `adopted ${created} from mail server` } })
219	      .catch(() => {});
220	  }
221	  return created;
222	}
223	
224	/**
225	 * Why the caller can't open webmail, so the UI can say what is actually wrong
226	 * instead of one catch-all "No mailbox connected".
227	 */
228	export type MailAccessState =
229	  | { kind: "ok"; address: string }
230	  | { kind: "no-subscription" }
231	  | { kind: "unverified-domain"; domains: string[] }
232	  | { kind: "no-mailbox"; domains: string[] }
233	  | { kind: "no-password"; address: string }
234	  | { kind: "server-unreachable"; address: string };
235	
236	/**
237	 * Diagnose mail access for a user. Runs Mailcow discovery first so a mailbox
238	 * that only exists on the server is found before we declare there is none.
239	 */
240	export async function mailAccessState(userId: string): Promise<MailAccessState> {
241	  await discoverMailboxes(userId).catch(() => 0);
242	
243	  const subs = await db.emailSubscription.findMany({
244	    where: { userId, status: { not: "CANCELLED" } },
245	    select: { domainName: true, verified: true, external: true },
246	  });
247	  if (subs.length === 0) return { kind: "no-subscription" };
248	
249	  const boxes = await db.mailbox.findMany({
250	    where: { subscription: { userId } },
251	    orderBy: { createdAt: "asc" },
252	    select: { address: true, passwordEnc: true },
253	  });
254	
255	  if (boxes.length === 0) {
256	    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
257	    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
258	    // An unverified domain is the more actionable problem: no mailbox can even
259	    // be created on it yet, so lead with that.
260	    if (verified.length === 0) return { kind: "unverified-domain", domains: unverified };
261	    return { kind: "no-mailbox", domains: verified };
262	  }
263	
264	  const withPassword = boxes.find((b) => decryptSecret(b.passwordEnc));
265	  if (!withPassword) return { kind: "no-password", address: boxes[0].address };
266	
267	  // A mailbox and a credential exist, so the page's failure was the mail server
268	  // itself (IMAP down, auth rejected, TLS problem) — not missing setup.
269	  return { kind: "server-unreachable", address: withPassword.address };
270	}
271	
272	/**
273	 * Resolve the mailbox a request may act on. Requires an authenticated user,
274	 * loads only mailboxes belonging to that user's email subscriptions, and (when
275	 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
276	 * credential; throws a friendly error if the password was never captured.
277	 *
278	 * NEVER returns a mailbox the caller does not own.
279	 */
280	export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
281	  const user = await requireUser();
282	
283	  // --- Staff-only: read COMPANY mailboxes (admin@, support@, …) in-portal. ---
284	  // This is an ADDITIVE branch: it only runs for staff, so the customer
285	  // resolution below is completely unchanged. A company mailbox is synthesized
286	  // into the same ResolvedMailbox shape (no EmailSubscription backing it).
287	  // Also additive for a granted EMPLOYEE — this is the REAL data-layer
288	  // authority every mail action (listFolders/listMessages/sendMessage/etc. in
289	  // lib/actions-mail.ts) goes through, so the companyInbox grant must reach
290	  // HERE, not just the /admin/inbox or /staff/inbox page — see
291	  // lib/staff-grants.ts's doc comment on the lib/team-guard.ts lesson.
292	  if (isStaff(user.role) || (user.role === "EMPLOYEE" && (await hasAreaAccess(user, "companyInbox")))) {
293	    const wantedLc = mailboxAddress?.trim().toLowerCase();
294	    const synthesize = (c: {
295	      id: string;
296	      address: string;
297	      label: string | null;
298	      passwordEnc: string;
299	      quotaMB: number;
300	      status: string;
301	    }): ResolvedMailbox => {
302	      const password = decryptSecret(c.passwordEnc);
303	      if (!password) throw new Error("Reset this mailbox's password to enable webmail access.");
304	      return {
305	        user,
306	        mailboxId: `company:${c.id}`,
307	        address: c.address,
308	        quotaMB: c.quotaMB,
309	        cred: { address: c.address, password },
310	        identity: { displayName: c.label, replyTo: null, organization: null },
311	        subscription: {
312	          id: `company:${c.id}`,
313	          domainName: COMPANY_MAIL_DOMAIN,
314	          external: false,
315	          verified: true,
316	          status: c.status,
317	        },
318	      };
319	    };
320	    // Only resolve an EXPLICITLY requested company address (the admin inbox always
321	    // passes one). With no address, fall through to the customer path — so a
322	    // staffer's own /dashboard/mail never silently lands on a company mailbox.
323	    if (wantedLc) {
324	      const c = await db.companyMailbox.findUnique({ where: { address: wantedLc } });
325	      // canAccessMailbox is "all" for SUPPORT/BILLING/ADMIN (isStaff — unchanged),
326	      // and scoped to their own + specifically granted addresses for EMPLOYEE
327	      // (see lib/staff-mailbox-access.ts). This is the actual enforcement point:
328	      // treating a mailbox this employee can't access as "not found" is what
329	      // makes companyInbox mean "the inbox feature is reachable," not "read
330	      // every company mailbox" — confirmed live 2026-09-03 it meant the latter.
331	      if (c && (await canAccessMailbox(user, c.address))) return synthesize(c);
332	      // Not a company address, or not one this user may access — fall through
333	      // to the customer path below (never distinguishes the two to the caller).
334	    }
335	  }
336	
337	  const load = () =>
338	    db.mailbox.findMany({
339	      where: { subscription: { userId: user.id } },
340	      include: { subscription: true },
341	      orderBy: { createdAt: "asc" },
342	    });
343	
344	  let boxes = await load();
345	  const wanted = mailboxAddress?.trim().toLowerCase();
346	
347	  // A miss here used to be terminal, which is how a mailbox that exists on the
348	  // mail server but has no local row became "you do not have a mailbox yet".
349	  // Reconcile against Mailcow (verified domains only) before giving that answer.
350	  if (boxes.length === 0 || (wanted && !boxes.some((b) => b.address.toLowerCase() === wanted))) {
351	    if (await discoverMailboxes(user.id).catch(() => 0)) boxes = await load();
352	  }
353	
354	  if (boxes.length === 0) {
355	    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
356	  }
357	
358	  let box = boxes[0];
359	  if (wanted) {
360	    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
361	    if (!match) throw new Error("You do not have access to that mailbox.");
362	    box = match;
363	  }
364	
365	  const password = decryptSecret(box.passwordEnc);
366	  if (!password) {
367	    throw new Error("Please reset your mailbox password first to enable webmail access.");
368	  }
369	
370	  return {
371	    user,
372	    mailboxId: box.id,
373	    address: box.address,
374	    quotaMB: box.quotaMB ?? null,
375	    cred: { address: box.address, password },
376	    identity: {
377	      displayName: box.displayName,
378	      replyTo: box.replyTo,
379	      organization: box.organization,
380	    },
381	    subscription: {
382	      id: box.subscription.id,
383	      domainName: box.subscription.domainName,
384	      external: box.subscription.external,
385	      verified: box.subscription.verified,
386	      status: box.subscription.status,
387	    },
388	  };
389	}
390	
391	/** Build a per-request imapflow client for the given credential. */
392	export function createImapClient(cred: MailboxCredentials): ImapFlow {
393	  return new ImapFlow({
394	    host: MAIL_IMAP_HOST,
395	    port: MAIL_IMAP_PORT,
396	    secure: true,
397	    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
398	    // and validation servername so TLS verifies against the right name.
399	    servername: MAIL_TLS_SERVERNAME,
400	    tls: mailTlsOptions(),
401	    auth: { user: cred.address, pass: cred.password },
402	    logger: false,
403	    disableAutoIdle: true,
404	    // ImapFlow's default connectionTimeout is 90s — measured live against
405	    // this exact mail server (2026-08-29): a single struggling connection
406	    // attempt genuinely took the full 90s to fail. app/admin/inbox/page.tsx
407	    // tries EACH company mailbox in sequence on a bad first pick, so with 5
408	    // mailboxes a single slow one could hang the whole admin inbox page for
409	    // several minutes. This host also shows real CPU pressure-stall metrics
410	    // (contention from an overcommitted physical node, not a Mailcow config
411	    // bug), so occasional slow connects are expected — 10s is generous for a
412	    // LAN hop but fails far faster than 90s when the server genuinely can't
413	    // respond. socketTimeout stays closer to the library default since it
414	    // covers in-progress operations (fetching messages), which can
415	    // legitimately take longer than a bare connect.
416	    connectionTimeout: 10_000,
417	    greetingTimeout: 8_000,
418	    socketTimeout: 30_000,
419	  });
420	}
421	
422	/**
423	 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
424	 * logout, falling back to a hard close). Suitable for one operation per request.
425	 */
426	export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
427	  const client = createImapClient(cred);
428	  await client.connect();
429	  try {
430	    return await fn(client);
431	  } finally {
432	    try {
433	      await client.logout();
434	    } catch {
435	      try {
436	        client.close();
437	      } catch {
438	        /* already gone */
439	      }
440	    }
441	  }
442	}
443	
444	/**
445	 * Like `withImap` but also selects `path` under a mailbox lock (released before
446	 * the connection closes). Use for any op that fetches/searches/mutates messages.
447	 */
448	export async function withMailbox<T>(
449	  cred: MailboxCredentials,
450	  path: string,
451	  fn: (client: ImapFlow) => Promise<T>,
452	  opts?: { readOnly?: boolean },
453	): Promise<T> {
454	  return withImap(cred, async (client) => {
455	    const lockOpts: MailboxLockOptions = { readOnly: opts?.readOnly };
456	    const lock = await client.getMailboxLock(path, lockOpts);
457	    try {
458	      return await fn(client);
459	    } finally {
460	      lock.release();
461	    }
462	  });
463	}
464	
465	/** Map an IMAP special-use flag / folder name to our MailFolderRole. */
466	export function folderRole(path: string, specialUse?: string): MailFolderRole {
467	  const su = (specialUse || "").toLowerCase();
468	  if (su === "\\inbox" || path.toUpperCase() === "INBOX") return "inbox";
469	  switch (su) {
470	    case "\\sent":
471	      return "sent";
472	    case "\\drafts":
473	      return "drafts";
474	    case "\\trash":
475	      return "trash";
476	    case "\\junk":
477	      return "junk";
478	    case "\\archive":
479	    case "\\all":
480	      return "archive";
481	  }
482	  // Fall back to common folder names for servers that don't advertise SPECIAL-USE.
483	  const leaf = (path.split(/[/.]/).pop() || path).toLowerCase();
484	  if (leaf === "inbox") return "inbox";
485	  if (["sent", "sent items", "sent mail", "sent messages"].includes(leaf)) return "sent";
486	  if (["drafts", "draft"].includes(leaf)) return "drafts";
487	  if (["trash", "deleted", "deleted items", "deleted messages", "bin"].includes(leaf)) return "trash";
488	  if (["junk", "spam", "junk email", "junk e-mail"].includes(leaf)) return "junk";
489	  if (["archive", "archives", "all mail", "all"].includes(leaf)) return "archive";
490	  return "custom";
491	}
492	
493	/** Convert an imapflow envelope address to our MailAddress shape. */
494	export function toMailAddress(a: MessageAddressObject | undefined): MailAddress {
495	  return { name: a?.name || undefined, address: a?.address || "" };
496	}
497	
498	/** Convert an array of imapflow envelope addresses to MailAddress[]. */
499	export function toMailAddresses(list: MessageAddressObject[] | undefined): MailAddress[] {
500	  return (list || []).map(toMailAddress).filter((a) => a.address);
501	}
502	
503	/**
504	 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
505	 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
506	 * "1" for a simple single-part message (whose structure carries no part id).
507	 */
508	export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
509	  if (!structure) return { part: "1", isHtml: false };
510	  const leaves: MessageStructureObject[] = [];
511	  const walk = (node: MessageStructureObject) => {
512	    if (node.childNodes && node.childNodes.length) {
513	      node.childNodes.forEach(walk);
514	    } else {
515	      leaves.push(node);
516	    }
517	  };
518	  walk(structure);
519	
520	  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
521	  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
522	  if (plain) return { part: plain.part || "1", isHtml: false };
523	  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
524	  if (html) return { part: html.part || "1", isHtml: true };
525	  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
526	}
