248	/** Fetch one full message: parsed + SANITISED html, attachments listed, marked \Seen. */
249	export async function getMessage(folder: string, uid: number, mailboxAddress?: string): Promise<MessageFull> {
250	  const { cred } = await resolveMailbox(mailboxAddress);
251	
252	  return withMailbox(cred, folder, async (client) => {
253	    const msg = await client.fetchOne(
254	      String(uid),
255	      { uid: true, source: true, flags: true, envelope: true, internalDate: true },
256	      { uid: true },
257	    );
258	    if (!msg || !msg.source) throw new Error("Message not found.");
259	
260	    const parsed = await parseMessage(msg.source);
261	    const flags = readFlags(msg.flags);
262	    const env = msg.envelope;
263	
264	    const attachments = (parsed.attachments || [])
265	      .filter((a) => a.related !== true) // skip inline/embedded (cid) images
266	      .map((a, i) => ({
267	        id: `${uid}:${a.partId ?? String(i + 1)}`,
268	        filename: a.filename || `attachment-${i + 1}`,
269	        mime: a.contentType || "application/octet-stream",
270	        sizeBytes: a.size ?? 0,
271	      }));
272	
273	    const full: MessageFull = {
274	      uid,
275	      folder,
276	      from: toMailAddress(env?.from?.[0]),
277	      to: toMailAddresses(env?.to),
278	      cc: toMailAddresses(env?.cc),
279	      subject: env?.subject || parsed.subject || "(no subject)",
280	      preview: previewText(parsed.text || (typeof parsed.html === "string" ? parsed.html : "")),
281	      date: isoDate(msg),
282	      seen: true, // becomes read as a side effect of opening
283	      flagged: flags.flagged,
284	      answered: flags.answered,
285	      hasAttachments: attachments.length > 0,
286	      html: typeof parsed.html === "string" ? safeHtml(parsed.html) : null,
287	      text: parsed.text ?? null,
288	      attachments,
289	    };
290	
291	    // Mark read (mailbox opened read-write). Best effort — never fail the read.
292	    try {
293	      await client.messageFlagsAdd(String(uid), ["\\Seen"], { uid: true });
294	    } catch {
295	      /* ignore */
296	    }
297	
298	    return full;
299	  });
300	}
