326	/** Resolve the IMAP path of the mailbox's Sent folder (defaults to "Sent"). */
327	async function findSentPath(client: ImapFlow): Promise<string> {
328	  try {
329	    const list = await client.list();
330	    const sent = list.find((f) => folderRole(f.path, f.specialUse) === "sent");
331	    return sent?.path || "Sent";
332	  } catch {
333	    return "Sent";
334	  }
335	}
