337	// Attachment limits — enforced server-side; never trust the client's own caps.
338	const MAX_ATTACHMENTS = 10;
339	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB decoded
340	
341	// Base64 inflates by ~4/3, so 20 MB of files arrives as ~26.7 MB of payload.
342	// `next.config.ts` raises `experimental.serverActions.bodySizeLimit` to 30 MB to
343	// match (Next's 1 MB default silently truncated anything over ~700 KB while both
344	// this file and the composer advertised 20 MB). This ceiling is the server-side
345	// half of that pairing: it rejects an over-large upload with a message the
346	// customer can act on, instead of letting Buffer.from allocate first.
347	const MAX_ATTACHMENTS_TOTAL_BASE64 = Math.ceil(MAX_ATTACHMENTS_TOTAL_BYTES / 3) * 4;
348	
349	/** Human-friendly byte size for limit messages (mirrors the composer's format). */
350	function fmtLimit(bytes: number): string {
351	  return `${Math.round(bytes / (1024 * 1024))} MB`;
352	}
353	
354	/** Strip path separators, quotes and control chars from an attachment filename. */
355	function sanitizeAttachmentName(name?: string): string {
356	  if (!name) return "";
357	  const cleaned = Array.from(name)
358	    .filter((ch) => {
359	      const c = ch.codePointAt(0) ?? 0;
360	      if (c < 0x20 || c === 0x7f) return false; // control chars
361	      if (ch === '"' || ch === "\\" || ch === "/") return false;
362	      return true;
363	    })
364	    .join("");
365	  return cleaned.trim().slice(0, 200);
366	}
367	
368	type BuiltAttachment = { filename: string; content: Buffer; contentType: string; cid?: string };
369	
370	/**
371	 * Validate + decode client-supplied attachments. Caps count and total decoded
372	 * size, validates base64, sanitises filenames and defaults the content type.
373	 * Returns the decoded buffers or a friendly error string.
374	 */
375	function decodeAttachments(
376	  input: SendAttachment[] | undefined,
377	): { ok: true; attachments: BuiltAttachment[] } | { ok: false; error: string } {
378	  if (!input || input.length === 0) return { ok: true, attachments: [] };
379	  if (!Array.isArray(input)) return { ok: false, error: "Invalid attachments." };
380	  if (input.length > MAX_ATTACHMENTS) {
381	    return { ok: false, error: `Too many attachments — up to ${MAX_ATTACHMENTS} allowed.` };
382	  }
383	
384	  // Reject on the ENCODED length before decoding anything, so an oversize upload
385	  // fails with a clear message rather than being decoded into memory first.
386	  let encodedTotal = 0;
387	  for (const a of input) {
388	    if (a && typeof a.contentBase64 === "string") encodedTotal += a.contentBase64.length;
389	  }
390	  if (encodedTotal > MAX_ATTACHMENTS_TOTAL_BASE64) {
391	    return {
392	      ok: false,
393	      error: `Attachments are too large — the total must be under ${fmtLimit(MAX_ATTACHMENTS_TOTAL_BYTES)}. Remove a file or send it as a link.`,
394	    };
395	  }
396	
397	  const out: BuiltAttachment[] = [];
398	  let total = 0;
399	  for (let i = 0; i < input.length; i++) {
400	    const a = input[i];
401	    if (!a || typeof a.contentBase64 !== "string") {
402	      return { ok: false, error: "Invalid attachment data." };
403	    }
404	    // Tolerate a stray "data:*;base64," prefix, then validate the base64.
405	    const b64 = a.contentBase64.replace(/^data:[^;]*;base64,/, "").trim();
406	    if (!/^[A-Za-z0-9+/]*={0,2}$/.test(b64) || b64.length % 4 !== 0) {
407	      return { ok: false, error: "Attachment could not be read (invalid encoding)." };
408	    }
409	    const content = Buffer.from(b64, "base64");
410	    total += content.length;
411	    if (total > MAX_ATTACHMENTS_TOTAL_BYTES) {
412	      return {
413	        ok: false,
414	        error: `Attachments exceed the ${fmtLimit(MAX_ATTACHMENTS_TOTAL_BYTES)} total limit.`,
415	      };
416	    }
417	    const filename = sanitizeAttachmentName(a.filename) || `attachment-${i + 1}`;
418	    const contentType =
419	      typeof a.contentType === "string" && a.contentType.trim()
420	        ? a.contentType.trim().slice(0, 128)
421	        : "application/octet-stream";
422	    // Inline images carry a Content-ID the HTML body references as `cid:<cid>`.
423	    // Constrain it to a sane token so it can't inject header syntax.
424	    const cid =
425	      typeof a.cid === "string" && /^[A-Za-z0-9._@+-]{1,120}$/.test(a.cid) ? a.cid : undefined;
426	    out.push({ filename, content, contentType, cid });
427	  }
428	  return { ok: true, attachments: out };
429	}
