431	/**
432	 * Send a message from the user's own mailbox over SMTP submission, append a copy
433	 * to Sent, and (for replies) thread it + flag the original \Answered.
434	 */
435	export async function sendMessage(
436	  payload: SendPayload,
437	  mailboxAddress?: string,
438	): Promise<{ ok: boolean; error?: string }> {
439	  const { user, cred, identity } = await resolveMailbox(mailboxAddress);
440	  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
441	  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });
442	
443	  const to = parseRecipients(payload.to);
444	  const cc = parseRecipients(payload.cc);
445	  const bcc = parseRecipients(payload.bcc);
446	  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
447	  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
448	  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
449	  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
450	    return { ok: false, error: "Nothing to send — add a subject or a message." };
451	  }
452	
453	  const decoded = decodeAttachments(payload.attachments);
454	  if (!decoded.ok) return { ok: false, error: decoded.error };
455	  const attachments = decoded.attachments;
456	
457	  try {
458	    // Look up threading headers when this is a reply.
459	    let inReplyTo: string | undefined;
460	    let references: string | undefined;
461	    if (payload.inReplyToUid && payload.replyFolder) {
462	      try {
463	        await withMailbox(cred, payload.replyFolder, async (client) => {
464	          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
465	          if (orig && orig.envelope?.messageId) {
466	            inReplyTo = orig.envelope.messageId;
467	            references = orig.envelope.messageId;
468	          }
469	          // Mark the message we're replying to as answered (best effort).
470	          try {
471	            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
472	          } catch {
473	            /* ignore */
474	          }
475	        });
476	      } catch {
477	        /* original not found — send without threading headers */
478	      }
479	    }
480	
481	    // Apply the saved sender identity.
482	    //
483	    // These three columns were written by the Identity panel and read by NOTHING:
484	    // the panel promised "Shown as the sender name on messages you send" and every
485	    // message still went out bare `from: cred.address` with no Reply-To, so a
486	    // customer who set a reply-to address had replies quietly go to the wrong
487	    // mailbox. Each field falls back to the previous behaviour when unset.
488	    //
489	    // Note `from` only changes the HEADER. nodemailer derives `built.envelope`
490	    // from the address part, so SMTP MAIL FROM stays the authenticated mailbox
491	    // and SPF/DKIM alignment (fixed today) is untouched.
492	    const displayName = identity.displayName?.trim();
493	    const replyTo = identity.replyTo?.trim();
494	    const organization = identity.organization?.trim();
495	
496	    // SANITISE the composed HTML server-side before it ships. The composer
497	    // already runs `safeHtml`, but this action is the last gate a body passes
498	    // through and must never trust the client — so an XSS vector or a malformed
499	    // body can't reach a recipient even if the client is bypassed. `safeHtml`
500	    // preserves `cid:` image refs and inline formatting; it only strips scripts,
501	    // event handlers and dangerous URL schemes.
502	    const safeBodyHtml = payload.html ? safeHtml(payload.html) : undefined;
503	
504	    // Map decoded attachments to nodemailer's shape, marking inline images
505	    // (those with a cid) so clients render them in place via multipart/related.
506	    const mailAttachments = attachments.map((a) =>
507	      a.cid
508	        ? { filename: a.filename, content: a.content, contentType: a.contentType, cid: a.cid, contentDisposition: "inline" as const }
509	        : { filename: a.filename, content: a.content, contentType: a.contentType },
510	    );
511	
512	    // Compile the message once so the exact bytes are both sent and saved to Sent.
513	    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
514	    const built = await composer.sendMail({
515	      from: displayName ? { name: displayName, address: cred.address } : cred.address,
516	      replyTo: replyTo || undefined,
