626	//
627	// TRAINING — read this before assuming these "train the filter":
628	//
629	//   `markSpam`/`markNotSpam` reliably MOVE the message (to Junk / back to Inbox).
630	//   That move is ALSO the training signal — but only when the mail HOST is
631	//   configured for it. Mailcow ships a default Dovecot `imap_sieve` "antispam"
632	//   integration that runs `rspamc learn_spam` when a message is copied INTO the
633	//   Junk folder and `rspamc learn_ham` when one is moved OUT of it. When that
634	//   host config is present (the Mailcow default), these moves train Rspamd's
635	//   Bayes classifier as a side effect — no extra call from us.
636	//
637	//   The app CANNOT force or verify that learning itself: the Rspamd controller
638	//   (:11334) is not reachable from this host and there is no learn endpoint on
639	//   Mailcow's REST API. So this code guarantees the MOVE (immediate, visible
640	//   benefit); Bayes autolearn is a host-side property we neither toggle nor
641	//   claim. If an operator has disabled the imap_sieve antispam hooks, marking
642	//   still files mail correctly, it just won't teach the classifier — that is a
643	//   Mailcow host setting (see the admin Junk-threshold card notes), not a bug
644	//   here. Do not add a comment or toast that promises "trained" — we can't.
645	
646	/** Resolve the IMAP path of a role folder (junk/inbox/...) with a fallback. */
647	async function resolveFolderPath(client: ImapFlow, role: MailFolderRole, fallback: string): Promise<string> {
648	  try {
649	    const list = await client.list();
650	    const f = list.find((x) => folderRole(x.path, x.specialUse) === role);
651	    if (f) return f.path;
652	  } catch {
653	    /* fall back to the conventional name */
654	  }
655	  return fallback;
656	}
