660	 * training note above — the move is also what trains Bayes when the mail host's
661	 * imap_sieve antispam hooks are enabled (Mailcow default); we can't force that.
662	 * No-op (and no error) if the message is already in Junk.
663	 */
664	export async function markSpam(fromFolder: string, uid: number, mailboxAddress?: string): Promise<void> {
665	  const { user, cred } = await resolveMailbox(mailboxAddress);
666	  enforceRateLimit(`mail:spam:${user.id}`, { max: 120, windowMs: 60 * 1000 });
667	
668	  await withImap(cred, async (client) => {
669	    const junkPath = await resolveFolderPath(client, "junk", "Junk");
670	    // Already spam — nothing to do (and moving onto itself would error).
671	    if (folderRole(fromFolder) === "junk" || fromFolder === junkPath) return;
672	    const lock = await client.getMailboxLock(fromFolder);
673	    try {
674	      await client.messageMove(String(uid), junkPath, { uid: true });
675	    } finally {
676	      lock.release();
677	    }
678	  });
679	}
