274	/** Renders the email body. HTML is dropped into a sandboxed iframe with
275	 *  `allow-same-origin` but crucially NO `allow-scripts`, so sender scripts still
276	 *  never execute — allow-same-origin only lets the PARENT read the inner document
277	 *  to auto-size the frame to its full content height. Plaintext falls back to a
278	 *  pre block. */
279	function MessageBody({ html, text }: { html: string | null; text: string | null }) {
280	  const ref = useRef<HTMLIFrameElement>(null);
281	  const observerRef = useRef<ResizeObserver | null>(null);
282	  const [height, setHeight] = useState(MIN_BODY_HEIGHT);
283	
284	  const doc = html
285	    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
286	        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
287	        body{padding:16px;}
288	        img{max-width:100%;height:auto;}
289	        a{color:#5f2ee8;}
290	        table{max-width:100%;}
291	        pre{white-space:pre-wrap;}
292	        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
293	        /* Marketing mail is built on fixed-width tables — 600px is the de facto
294	           standard — and the reading pane is often narrower than that. The frame
295	           itself cannot scroll (scrolling="no", because it is auto-sized to its
296	           content instead), so anything wider than the pane was CLIPPED at the
297	           edge with no way to reach it: on a 600px invoice that hid the amount
298	           column and half the pay button. The table max-width rule above does
299	           not save it — a nested table's min-content width still overflows. This
300	           scroll container lives INSIDE the document, so it works despite
301	           scrolling="no" and keeps the whole email reachable. */
302	        .nx-mailbody{overflow-x:auto;}
303	      </style></head><body><div class="nx-mailbody">${html}</div></body></html>`
304	    : null;
305	
306	  // Autosize: with sandbox="allow-same-origin" (and still NO allow-scripts, so
307	  // sender scripts stay inert) the parent can read the inner document and grow the
308	  // frame to its full content height — the whole email renders in the page flow
309	  // (the reading pane scrolls, the frame itself never does), so tall mail is no
310	  // longer clipped. Reset to the min height when the body changes.
311	  useEffect(() => {
312	    setHeight(html ? MIN_BODY_HEIGHT : 0);
313	  }, [html]);
314	
315	  // Measure the rendered document and size the frame to it (plus a small buffer),
316	  // clamped so short mail isn't a giant box and runaway content can't explode.
317	  const measure = useCallback(() => {
318	    const cdoc = ref.current?.contentDocument;
319	    if (!cdoc) return;
320	    const h = Math.max(
321	      cdoc.documentElement?.scrollHeight ?? 0,
322	      cdoc.body?.scrollHeight ?? 0,
323	    );
324	    if (h > 0) {
325	      setHeight(Math.min(MAX_BODY_HEIGHT, Math.max(MIN_BODY_HEIGHT, Math.ceil(h) + BODY_HEIGHT_BUFFER)));
326	    }
327	  }, []);
328	
329	  // Tear down the body observer on unmount / body swap.
330	  useEffect(() => () => { observerRef.current?.disconnect(); observerRef.current = null; }, []);
331	
332	  // On each (re)load: measure once, then keep re-measuring as late layout settles
333	  // — image decode, web-font swaps, async reflows. A ResizeObserver on the inner
334	  // <body> catches most of it; a few delayed passes and per-image load handlers
335	  // cover the rest.
336	  const handleLoad = useCallback(() => {
337	    measure();
338	    const cdoc = ref.current?.contentDocument;
339	    [60, 200, 500, 1200].forEach((ms) => window.setTimeout(measure, ms));
340	    observerRef.current?.disconnect();
341	    observerRef.current = null;
342	    if (cdoc?.body && typeof ResizeObserver !== "undefined") {
343	      const ro = new ResizeObserver(() => measure());
344	      ro.observe(cdoc.body);
345	      observerRef.current = ro;
346	    }
347	    cdoc?.querySelectorAll("img").forEach((img) => {
348	      if (!img.complete) img.addEventListener("load", measure, { once: true });
349	    });
350	  }, [measure]);
351	
352	  // Render the body from a blob: URL rather than `srcDoc`. A `sandbox=""` srcdoc
