66	// Decode the handful of entity/whitespace tricks used to smuggle "javascript:"
67	// past a naive scheme check (e.g. "java&#115;cript:", "java\tscript:").
68	function decodeAttr(v: string): string {
69	  return v
70	    .replace(/&#x([0-9a-f]+);?/gi, (_, h) => safeFromCodePoint(parseInt(h, 16)))
71	    .replace(/&#(\d+);?/g, (_, d) => safeFromCodePoint(parseInt(d, 10)))
72	    .replace(/[\s�-]+/g, "");
73	}
74	
75	function safeFromCodePoint(code: number): string {
76	  if (!Number.isFinite(code) || code < 0 || code > 0x10ffff) return "";
77	  try {
78	    return String.fromCodePoint(code);
79	  } catch {
80	    return "";
81	  }
82	}
83	
84	const ENTITIES: Record<string, string> = {
85	  "&nbsp;": " ",
86	  "&amp;": "&",
87	  "&lt;": "<",
88	  "&gt;": ">",
89	  "&quot;": '"',
90	  "&#39;": "'",
91	  "&apos;": "'",
92	  "&mdash;": "—",
93	  "&ndash;": "–",
94	  "&hellip;": "…",
95	};
96	
97	function decodeEntities(text: string): string {
98	  return text
99	    .replace(/&(?:nbsp|amp|lt|gt|quot|#39|apos|mdash|ndash|hellip);/g, (m) => ENTITIES[m] ?? m)
100	    .replace(/&#x([0-9a-f]+);/gi, (_, h) => safeFromCodePoint(parseInt(h, 16)))
101	    .replace(/&#(\d+);/g, (_, d) => safeFromCodePoint(parseInt(d, 10)));
102	}
