104	/**
105	 * Produce a compact (~140-char) plaintext snippet from an HTML or plaintext
106	 * body, suitable for a message-list preview. Strips markup, collapses
107	 * whitespace, decodes common entities, and adds an ellipsis when truncated.
108	 */
109	export function previewText(source: string | null | undefined, max = 140): string {
110	  if (!source) return "";
111	  let text = String(source);
112	  // Remove script/style blocks with their content so we never leak CSS/JS text.
113	  text = text.replace(/<(script|style)\b[\s\S]*?<\/\1\s*>/gi, " ");
114	  // Turn block boundaries into spaces, then strip remaining tags.
115	  text = text.replace(/<(?:br|\/p|\/div|\/tr|\/li|\/h[1-6])\b[^>]*>/gi, " ");
116	  text = text.replace(/<[^>]+>/g, " ");
117	  text = decodeEntities(text);
118	  text = text.replace(/\s+/g, " ").trim();
119	  if (text.length <= max) return text;
120	  return text.slice(0, max).replace(/\s+\S*$/, "").trimEnd() + "…";
121	}
