// Sender brand logos for the mail client.
//
// "Do these senders have an official logo assigned to their email?" — yes, and
// the standard for it is BIMI (Brand Indicators for Message Identification).
// A domain publishes a TXT record at `default._bimi.<domain>` carrying
// `l=<https url to an SVG>`, and that SVG is the logo the brand has formally
// asserted for its mail. That is the only source here that is genuinely
// "official"; it is also rare, because publishing it in earnest goes with a
// Verified Mark Certificate.
//
// A second tier falls back to the domain's own favicon. That is NOT an
// assertion by the sender about their mail — it is just their website's icon —
// so it is reported separately (`source`) and never presented as verified.
//
// WHERE THE FETCHING HAPPENS. All of it is server-side, and the browser only
// ever talks to us. If the client fetched these directly, opening a mailbox
// would announce every one of your correspondents' domains to those domains
// (and to whatever third-party favicon service was used). It also means one
// fetch per domain for the whole instance rather than one per reader.
//
// This module makes OUTBOUND requests to addresses derived from untrusted mail,
// so it is written as an SSRF boundary: https only, public IPs only, hard
// timeout, hard size cap, image content-types only, redirects re-checked.

import { promises as dns } from "node:dns";
import net from "node:net";

export type BrandLogo = {
  /** "bimi" = the sender formally published this. "favicon" = best-effort. */
  source: "bimi" | "favicon";
  contentType: string;
  body: Buffer;
};

const MAX_BYTES = 256 * 1024;
const FETCH_TIMEOUT_MS = 5_000;
const MAX_REDIRECTS = 2;

// BIMI mandates SVG Tiny PS; favicons are usually ico/png. Anything else is
// refused rather than passed through to the browser.
const ALLOWED_TYPES = new Set([
  "image/svg+xml",
  "image/png",
  "image/x-icon",
  "image/vnd.microsoft.icon",
  "image/jpeg",
  "image/webp",
  "image/gif",
]);

type Entry = { at: number; value: BrandLogo | null };
const CACHE = new Map<string, Entry>();
const HIT_TTL_MS = 24 * 60 * 60 * 1000;
// Negative results expire sooner: a domain can start publishing BIMI, and we
// should not be blind to that for a whole day. Still long enough that a busy
// mailbox is not re-resolving the same dozen domains all afternoon.
const MISS_TTL_MS = 6 * 60 * 60 * 1000;
const MAX_ENTRIES = 500;

export function normaliseDomain(input: string): string | null {
