/**
 * The sender domain's logo, or null. Never throws.
 *
 * `allowFavicon` decides whether the non-authoritative second tier is used;
 * with it off, only a real BIMI record produces a logo.
 */
export async function getBrandLogo(
  rawDomain: string,
  opts: { allowFavicon?: boolean } = {},
): Promise<BrandLogo | null> {
  const domain = normaliseDomain(rawDomain);
