    // BIMI is specified as SVG; anything else claiming to be one is not it.
    if (got && got.contentType === "image/svg+xml") {
      const value: BrandLogo = { source: "bimi", contentType: got.contentType, body: got.body };
      cacheSet(domain, value);
      return value;
    }
  }

  if (opts.allowFavicon !== false) {
    const got = await fetchImage(`https://${domain}/favicon.ico`);
    if (got && got.body.length > 0) {
      const value: BrandLogo = { source: "favicon", contentType: got.contentType, body: got.body };
      cacheSet(domain, value);
      return value;
    }
  }

  cacheSet(domain, null);
