4	function hostList(envVar: string | undefined): string[] {
5	  return (envVar ?? "")
6	    .split(",")
7	    .map((s) => s.trim().toLowerCase())
8	    .filter(Boolean);
9	}
10	
11	// Every file actually committed under public/ -- logos, game art, flags,
12	// brand assets, blog images, docs, fonts. None of it is per-customer or
13	// sensitive; it's already served unauthenticated at the same path on the
14	// main site, so exposing it on the admin/staff hosts too doesn't defeat the
15	// isolation below (that's about app pages like /dashboard, not static
16	// files). Without this, every <img> under public/ 404s on the admin/staff
17	// hosts -- found live 2026-09-14 when the What's New announcement preview
18	// (game art, screenshots, the Nxeon logo) rendered as broken images in the
19	// admin panel while the identical page worked fine for customers.
20	const STATIC_ASSET_RE =
21	  /\.(?:png|jpe?g|gif|webp|svg|ico|mp4|webm|woff2?|css|json|txt|md|html)$/i;
22	
23	/**
24	 * Reachable on every host regardless of portal mode: Next internals, the API
25	 * surface every portal's own client code calls (chat SSE, uploads, etc.),
26	 * the auth utility pages every login form links to, and static files under
27	 * public/. Everything else is scoped to exactly one portal below.
28	 */
29	function isUniversallyAllowed(pathname: string): boolean {
30	  return (
31	    pathname.startsWith("/_next") ||
32	    pathname.startsWith("/api/") ||
33	    pathname === "/favicon.ico" ||
34	    pathname.startsWith("/.well-known/") ||
35	    pathname === "/forgot-password" ||
36	    pathname === "/reset-password" ||
37	    // Both portal layouts redirect a staff/admin account without 2FA here to
38	    // enroll (enforce_staff_2fa) -- account security settings aren't
39	    // customer-specific, and blocking this would stand between a legitimate
40	    // staff member and the one page that lets them satisfy the requirement.
41	    pathname === "/dashboard/settings" ||
42	    STATIC_ASSET_RE.test(pathname)
43	  );
44	}
45	
46	/**
47	 * Confines the admin/staff hostnames to exactly their own portal.
48	 *
49	 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
50	 * direction -- /admin and /staff 404 on any host that isn't their own
51	 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
52	 * admin/staff hostnames proxy to the exact same Next.js backend as the main
53	 * site, so /dashboard, /login, /register, and every marketing page were
54	 * equally reachable there too -- confirmed live 2026-09-02, a customer's full
55	 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
56	 * Not a data leak (they only ever saw their own account), but it defeats the
57	 * point of a separate, minimal, operations-only surface, and reduces
58	 * whatever "hard to guess" value the admin subdomain has by leaving it fully
59	 * browsable/indexable as a second copy of the public site.
60	 *
61	 * Together with the two layouts' existing checks this makes the mapping
62	 * exact: admin host <-> /admin only, staff host <-> /staff only, every other
63	 * host <-> everything except /admin and /staff.
64	 */
65	const NXM_EXACT = new Set<string>(NXM_LIVE_ROUTES.exact);
66	const NXM_PATTERNS = NXM_LIVE_ROUTES.patterns.map((p) => new RegExp(p));
67	
68	export function middleware(req: NextRequest) {
69	  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
70	  const { pathname } = req.nextUrl;
71	
72	  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
73	  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
74	  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
75	  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);
76	
77	  // An admin impersonating a customer (lib/auth.ts's setImpersonation) needs to
78	  // browse the FULL customer app -- /dashboard, /checkout, etc. -- from their own
79	  // admin host, since impersonation swaps identity without changing host. Only
80	  // ADMIN can ever hold this cookie (EMPLOYEE/staff can never impersonate -- see
81	  // setImpersonation's own role check), so this only ever loosens the admin
82	  // host. We only check the cookie's PRESENCE here, not its signature/validity
83	  // -- that's exactly as strong as this gate needs to be: a forged or expired
84	  // token still gets fully re-verified by impersonating()/currentUser() at the
85	  // page/action layer, so a bad cookie here just falls back to "no session",
86	  // never to unauthorized access.
87	  const impCookieName = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
88	  const isImpersonating = isAdminHost && req.cookies.has(impCookieName);
89	
90	  if ((isAdminHost || isStaffHost) && !isImpersonating) {
91	    const ownPrefix = isAdminHost ? "/admin" : "/staff";
92	    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";
93	
94	    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix)) {
95	      // The shared /login page (and any stray redirect to it -- logout()
96	      // always sends there, regardless of who's logging out) lands on this
97	      // host's own dedicated login instead of 404ing a signed-out visitor.
98	      if (pathname === "/login") {
99	        const url = req.nextUrl.clone();
100	        url.pathname = ownLogin;
101	        return NextResponse.redirect(url);
102	      }
103	      // The bare root -- where someone typing/bookmarking just the hostname
104	      // lands -- goes to the portal itself rather than 404ing. The admin
105	      // vhost happens to have its own nginx-level `location = / return 302
106	      // /admin` that already covered this there (confirmed live), but the
107	      // staff vhost has no equivalent, so its root 404'd under this same
108	      // isolation logic. Handling it here covers both hosts the same way
109	      // regardless of nginx config: an authenticated visit shows the portal,
110	      // an unauthenticated one gets bounced on to ownLogin by the layout's
111	      // own existing redirect -- no new auth logic needed either way.
112	      if (pathname === "/") {
113	        const url = req.nextUrl.clone();
114	        url.pathname = ownPrefix;
115	        return NextResponse.redirect(url);
116	      }
117	      return new NextResponse("Not found.", { status: 404 });
118	    }
119	  }
120	
121	  // Server Components have no built-in way to read the current pathname --
122	  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
123	  // their own /login sub-route (public, no Shell, no auth redirect) without
124	  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
125	  // downstream Server Component actually sees it.
126	  const requestHeaders = new Headers(req.headers);
127	  requestHeaders.set("x-pathname", pathname);
