// Fake Mailcow for the admin-mail sandbox: TLS IMAP (hoodiecrow, one isolated
// store per user), STARTTLS SMTP submission (smtp-server) that delivers locally
// to fixture users, and a tiny HTTP control API for tests. NEVER talks to the
// real mail server.
"use strict";
const fs = require("fs");
const http = require("http");
const path = require("path");
const hoodiecrow = require("hoodiecrow-imap");
const { SMTPServer } = require("smtp-server");
const MailComposer = require("/opt/nxeon/node_modules/nodemailer/lib/mail-composer");

const IMAP_PORT = Number(process.env.FX_IMAP_PORT || 39993);
const SMTP_PORT = Number(process.env.FX_SMTP_PORT || 39587);
const CTL_PORT = Number(process.env.FX_CTL_PORT || 39080);
const PASS = "fixture-pass";
const key = fs.readFileSync(path.join(__dirname, "key.pem"));
const cert = fs.readFileSync(path.join(__dirname, "cert.pem"));

const USERS = [
  "santino@nxeon.cloud",
  "contact@nxeon.cloud",
  "support@nxeon.cloud",
  "admin@nxeon.cloud",
  "owner@acme-biz.test", // customer Business Email mailbox
];

const PLUGINS = ["ID", "IDLE", "UNSELECT", "SPECIAL-USE", "NAMESPACE", "MOVE", "UIDPLUS", "ENABLE", "LITERALPLUS", "CONDSTORE", "SASL-IR", "AUTH-PLAIN"];

function build(opts) {
  return new Promise((resolve, reject) => {
    new MailComposer(opts).compile().build((err, msg) => (err ? reject(err) : resolve(msg.toString())));
  });
}

const PNG_1PX = Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==", "base64");

async function seedFor(user) {
  const local = user.split("@")[0];
  const now = Date.now();
  const H = 3600 * 1000;
  const inbox = [];
  const add = async (box, o, ageH, flags = []) => {
    const raw = await build({ messageId: `<${local}.${box.length}.${ageH}@fixture>`, date: new Date(now - ageH * H), ...o });
    box.push({ raw, flags, internaldate: new Date(now - ageH * H) });
  };
  // Distinct per-mailbox subjects so a cross-mailbox leak is unmistakable.
  await add(inbox, { from: "Alice Partner <alice@partner-co.test>", to: user, subject: `[${local}] Partnership follow-up`, text: `Hi ${local}, following up.`, html: `<p>Hi <b>${local}</b>, following up.</p><p><img src="https://nxeon.cloud/logo.png" alt="logo" width="120"></p>` }, 1);
  await add(inbox, { from: "Bob Builder <bob@builder.test>", to: user, subject: `[${local}] Invoice with attachment`, text: "See attached.", attachments: [{ filename: "invoice.txt", content: "INVOICE 42" }] }, 2);
  await add(inbox, { from: "Carol Inline <carol@inline.test>", to: user, subject: `[${local}] Inline image (cid)`, html: `<p>Inline:</p><img src="cid:logo@fixture" alt="inline">`, attachments: [{ filename: "logo.png", content: PNG_1PX, cid: "logo@fixture", contentType: "image/png" }] }, 3);
  // Spam patterns seen in the real company inboxes (presets target these).
  await add(inbox, { from: "Review Pro <sales@reviewboost.test>", to: user, subject: "Get Permanent 5-star Reviews With Old Account & Real Profiles", text: "We remove negative Trustpilot and Google reviews." }, 4);
  await add(inbox, { from: "noreply-dmarc-support@google.com", to: user, subject: "Report Domain: nxeon.cloud Submitter: google.com Report-ID: 123", text: "DMARC aggregate report" }, 5);
  await add(inbox, { from: "Google Search Console <sc-noreply@google.com>", to: user, subject: "New Coverage issue detected for site nxeon.cloud", text: "Search Console digest" }, 6);
  await add(inbox, { from: "Listings Team <hello@buildfinds.test>", to: user, subject: "Get your product listed on BuildFinds", text: "Quick question about your SaaS — we can feature your product." }, 7);
  await add(inbox, { from: "SEO Expert <rank@seo-guru.test>", to: user, subject: "Rank #1 on Google — guaranteed backlinks", text: "We offer high DA backlinks and guest posts." }, 8);
  for (let i = 0; i < 6; i++) {
    await add(inbox, { from: `Customer ${i} <c${i}@client.test>`, to: user, subject: `[${local}] Older thread ${i}`, text: `older body ${i}` }, 30 + i * 12, i % 2 ? ["\\Seen"] : []);
  }
  const sent = [];
  const sentCount = local === "santino" ? 120 : 3;
  for (let i = 0; i < sentCount; i++) {
    await add(sent, { from: user, to: `creator${i}@yt.test`, subject: `[${local}] Sent outreach #${i}`, text: `sent body ${i}` }, (sentCount - i) * 2, ["\\Seen"]);
  }
  const junk = [];
  await add(junk, { from: "Lottery <win@lotto.test>", to: user, subject: "You won!", text: "claim" }, 10);
  return {
    INBOX: { messages: inbox },
    "": {
      separator: "/",
      folders: {
        Sent: { "special-use": "\\Sent", messages: sent, subscribed: true },
        Drafts: { "special-use": "\\Drafts", messages: [], subscribed: true },
        Archive: { "special-use": "\\Archive", messages: [], subscribed: true },
        Junk: { "special-use": "\\Junk", messages: junk, subscribed: true },
        Trash: { "special-use": "\\Trash", messages: [], subscribed: true },
      },
    },
  };
}

const servers = {};
const stats = { logins: {}, commands: 0 };
let delayMs = Number(process.env.FX_DELAY_MS || 0);

async function main() {
  for (const u of USERS) {
    servers[u] = hoodiecrow({ plugins: PLUGINS, storage: await seedFor(u), users: { [u]: { password: PASS } } });
  }
  // The listening front: authenticates against every user, then re-binds the
  // connection to that user's own isolated store (hoodiecrow is single-store).
  const allUsers = Object.fromEntries(USERS.map((u) => [u, { password: PASS }]));
  const front = hoodiecrow({ plugins: PLUGINS, secureConnection: true, credentials: { key, cert }, users: allUsers, storage: { INBOX: {}, "": { separator: "/" } } });
  const origGet = front.getCommandHandler.bind(front);
  front.getCommandHandler = function (command) {
    const h = origGet(command);
    if (!h) return h;
    const upper = String(command).toUpperCase();
    return function (connection, parsed, data, callback) {
      stats.commands++;
      const run = () => {
        if (upper === "LOGIN" || upper === "AUTHENTICATE") {
          const user = parsed.attributes && parsed.attributes[0] && String(parsed.attributes[0].value);
          return h(connection, parsed, data, () => {
            if (connection.state === "Authenticated" && servers[user]) {
              stats.logins[user] = (stats.logins[user] || 0) + 1;
              connection.server.removeListener("notify", connection._notificationCallback);
              connection.server = servers[user];
              connection.server.on("notify", connection._notificationCallback);
            }
            callback();
          });
        }
        const target = connection.server === front ? h : connection.server.getCommandHandler(command);
        return target(connection, parsed, data, callback);
      };
      if (delayMs && upper.includes("FETCH")) setTimeout(run, delayMs);
      else run();
    };
  };
  front.listen(IMAP_PORT, "127.0.0.1", () => console.log(`[fixture] IMAPS :${IMAP_PORT}`));

  const smtp = new SMTPServer({
    key, cert,
    authOptional: false,
    onAuth(auth, _s, cb) {
      if (USERS.includes(auth.username) && auth.password === PASS) return cb(null, { user: auth.username });
      cb(new Error("Invalid credentials"));
    },
    onData(stream, session, cb) {
      const chunks = [];
      stream.on("data", (c) => chunks.push(c));
      stream.on("end", () => {
        const raw = Buffer.concat(chunks).toString();
        for (const rcpt of session.envelope.rcptTo) deliver(rcpt.address.toLowerCase(), raw);
        console.log(`[fixture] SMTP from ${session.envelope.mailFrom && session.envelope.mailFrom.address} to ${session.envelope.rcptTo.map((r) => r.address).join(",")}`);
        cb();
      });
    },
  });
  smtp.listen(SMTP_PORT, "127.0.0.1", () => console.log(`[fixture] SMTP :${SMTP_PORT}`));

  http.createServer(async (req, res) => {
    const url = new URL(req.url, "http://x");
    let body = "";
    req.on("data", (c) => (body += c));
    await new Promise((r) => req.on("end", r));
    try {
      if (url.pathname === "/deliver" && req.method === "POST") {
        const j = JSON.parse(body);
        const raw = j.raw || (await build({ from: j.from || "New Sender <new@sender.test>", to: j.to, subject: j.subject || "New mail", text: j.text || "hello", date: new Date() }));
        deliver(j.to, raw);
        return res.end(JSON.stringify({ ok: true }));
      }
      if (url.pathname === "/dump") {
        const s = servers[url.searchParams.get("user")];
        const box = s && s.getMailbox(url.searchParams.get("folder") || "INBOX");
        return res.end(JSON.stringify(box ? box.messages.map((m) => ({ uid: m.uid, flags: m.flags, subject: (/^Subject: (.*)$/m.exec(m.raw) || [])[1] })) : null));
      }
      if (url.pathname === "/folders") {
        const s = servers[url.searchParams.get("user")];
        return res.end(JSON.stringify(Object.keys(s.folderCache)));
      }
      if (url.pathname === "/delay") { delayMs = Number(url.searchParams.get("ms") || 0); return res.end(JSON.stringify({ delayMs })); }
      if (url.pathname === "/stats") return res.end(JSON.stringify(stats));
      res.statusCode = 404; res.end("nope");
    } catch (e) { res.statusCode = 500; res.end(String(e)); }
  }).listen(CTL_PORT, "127.0.0.1", () => console.log(`[fixture] control :${CTL_PORT}`));
}

function deliver(to, raw) {
  const s = servers[to];
  if (!s) return;
  const inbox = s.getMailbox("INBOX");
  s.appendMessage(inbox, [], new Date(), raw);
}

main().catch((e) => { console.error(e); process.exit(1); });

