// ---------------------------------------------------------------------------
// Webmail filters, sender lists and per-user mail preferences (2026-10-01).
// Additive only. No FK to User/Mailbox on purpose: a rule is keyed by the
// mailbox ADDRESS (company or customer mailbox), and every read/write is
// authorised through lib/mail/imap.ts's resolveMailbox — never by these rows.
// See lib/mail/filters/* and docs §"Webmail filters".
// ---------------------------------------------------------------------------

/** One filter rule for one mailbox. Compiled to the mailbox's managed Sieve postfilter. */
model MailFilterRule {
  id             String   @id @default(cuid())
  mailboxAddress String // lower-case full address
  name           String
  enabled        Boolean  @default(true)
  position       Int      @default(0)
  matchMode      String   @default("all") // "all" | "any"
  conditions     Json // FilterCondition[] (lib/mail/filters/types.ts)
  actions        Json // FilterAction[]
  stopProcessing Boolean  @default(true)
  presetKey      String? // set when created from a built-in preset
  appliedCount   Int      @default(0) // messages moved by "apply to existing mail" (server-side Sieve hits are not observable)
  createdById    String?
  createdAt      DateTime @default(now())
  updatedAt      DateTime @updatedAt

  @@index([mailboxAddress, position])
}

/** Block / allow ("never filter") list entry: a full address or "@domain". */
model MailFilterSender {
  id             String   @id @default(cuid())
  mailboxAddress String
  kind           String // "block" | "allow"
  pattern        String // "someone@x.com" or "@x.com"
  createdById    String?
  createdAt      DateTime @default(now())

  @@unique([mailboxAddress, kind, pattern])
  @@index([mailboxAddress])
}

/** Last push of a mailbox's compiled filter script to the mail server. */
model MailFilterSync {
  mailboxAddress String    @id
  syncedAt       DateTime?
  error          String?
  scriptHash     String?
  updatedAt      DateTime  @updatedAt
}

/** Per-user webmail preferences (remembered mailbox, new-mail notifications). */
model MailUserPref {
  userId        String   @id
  lastMailbox   String?
  notifyNewMail Boolean  @default(false)
  updatedAt     DateTime @updatedAt
}
EOF
