// Shared contract for webmail filter rules (admin company mailboxes first, the
// customer product can adopt the same engine later).
//
// Plain module — no "use server", no I/O — so the UI, the Sieve compiler, the
// TypeScript evaluator and the unit tests all import the SAME shapes and the
// SAME validation. Every value that ends up inside a Sieve script passes
// through `parseRule` first; the compiler additionally quotes everything.

import { z } from "zod";

export const CONDITION_FIELDS = ["from", "domain", "to", "subject", "body", "header"] as const;
export type ConditionField = (typeof CONDITION_FIELDS)[number];

export const CONDITION_OPS = ["contains", "notContains", "is", "startsWith", "endsWith", "exists"] as const;
export type ConditionOp = (typeof CONDITION_OPS)[number];

export const ACTION_TYPES = ["move", "markRead", "delete", "forward", "label", "skipInbox", "spam"] as const;
export type ActionType = (typeof ACTION_TYPES)[number];

export const FIELD_LABEL: Record<ConditionField, string> = {
  from: "Sender address",
  domain: "Sender domain",
  to: "Recipient (To/Cc)",
  subject: "Subject",
  body: "Body text",
  header: "Header",
};

export const OP_LABEL: Record<ConditionOp, string> = {
  contains: "contains",
  notContains: "does not contain",
  is: "is exactly",
  startsWith: "starts with",
  endsWith: "ends with",
  exists: "exists",
};

export const ACTION_LABEL: Record<ActionType, string> = {
  move: "Move to folder",
  markRead: "Mark as read",
  delete: "Delete (move to Trash)",
  forward: "Forward to",
  label: "Apply label",
  skipInbox: "Skip the inbox (archive)",
  spam: "Mark as spam",
};

/** RFC 5322 field-name subset we accept for custom header conditions. */
export const HEADER_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9-]{0,63}$/;
/** IMAP keyword for labels: atom chars only, so it is also a safe Sieve/IMAP token. */
export const LABEL_RE = /^[A-Za-z0-9][A-Za-z0-9 _.-]{0,39}$/;
const EMAIL_RE = /^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$/;
// eslint-disable-next-line no-control-regex
const CONTROL_RE = /[\u0000-\u001f\u007f]/;

/** Hard caps so a runaway rule set can't build an unbounded script. */
export const MAX_RULES_PER_MAILBOX = 100;
export const MAX_CONDITIONS = 10;
export const MAX_ACTIONS = 6;
export const MAX_FORWARD_TARGETS = 3;
export const MAX_SENDER_ENTRIES = 500;

const valueSchema = z
  .string()
  .max(200, "Keep match values under 200 characters.")
  .refine((v) => !CONTROL_RE.test(v), "Match values can't contain control characters.");

export const conditionSchema = z
  .object({
    field: z.enum(CONDITION_FIELDS),
    op: z.enum(CONDITION_OPS),
    value: valueSchema.default(""),
    header: z.string().optional(),
  })
  .superRefine((c, ctx) => {
    if (c.field === "header") {
      if (!c.header || !HEADER_NAME_RE.test(c.header)) {
        ctx.addIssue({ code: "custom", message: "Enter a valid header name (letters, digits and dashes)." });
      }
    } else if (c.op === "exists") {
      ctx.addIssue({ code: "custom", message: "“exists” only applies to header conditions." });
    }
    if (c.op !== "exists" && !c.value.trim()) {
      ctx.addIssue({ code: "custom", message: "Every condition needs a value to match." });
    }
  });
export type FilterCondition = z.infer<typeof conditionSchema>;

/** Folder paths: printable, no wildcards, no leading/trailing separators. */
export function isSafeFolderPath(p: string): boolean {
  if (!p || p.length > 120 || CONTROL_RE.test(p)) return false;
  if (/[*%"\\]/.test(p)) return false;
  if (/^[/.]|[/.]$/.test(p)) return false;
  return true;
}

export const actionSchema = z
  .object({
    type: z.enum(ACTION_TYPES),
    folder: z.string().optional(),
    to: z.string().optional(),
    label: z.string().optional(),
  })
  .superRefine((a, ctx) => {
    if (a.type === "move" && !(a.folder && isSafeFolderPath(a.folder))) {
