// Filter rules → ONE managed Sieve script per mailbox (Mailcow `postfilter`).
//
// Plain module, pure string building, no I/O. lib/mail/filters/sync.ts pushes
// the result to Mailcow. WHY SIEVE (and not a worker polling IMAP): Sieve runs
// inside Dovecot at delivery time, so rules apply instantly and keep working
// with every browser closed, with no stored-credential IMAP sessions, no IDLE
// fleet to babysit and no race against the user reading the message first. The
// TypeScript evaluator (./evaluate.ts) mirrors these semantics for the
// on-demand "apply to existing mail" sweep and for previews/tests.
//
// SLOT. Mailcow keeps ONE active filter per (mailbox, type). `prefilter` is
// owned by auto-reply/forwarding (lib/mail/sieve.ts → buildMailboxSieve), so
// rules + the block/allow lists share the single `postfilter` slot that the
// legacy "Block sender" button already used. With no rules, no allow-list and
// no domain blocks the output is BYTE-IDENTICAL to the legacy
// buildBlockSenderSieve script, so existing customer blocklists don't change.
//
// EXTENSIONS used: fileinto, imap4flags, body, copy — all Pigeonhole built-ins.
// Mailcow validates `require` on save, so an unsupported one surfaces as a sync
// error in the UI (MailFilterSync.error), never as a silent "saved".

import { createHash } from "node:crypto";
import { sq, buildBlockSenderSieve, MARK_BLOCKED } from "../sieve";
import {
  FILTERED_KEYWORD,
  labelKeyword,
  type FilterAction,
  type FilterCondition,
  type FilterRule,
  type SenderEntry,
} from "./types";

/** Real IMAP paths of the role folders the actions target. */
export type RoleFolders = { junk: string; trash: string; archive: string };

export const MARK_RULE = "# nxeon:rule";
export const MARK_ALLOW = "# nxeon:allowed";

/** Escape Sieve :matches wildcards so user text matches literally. */
function literal(v: string): string {
  return v.replace(/\\/g, "\\\\").replace(/\*/g, "\\*").replace(/\?/g, "\\?");
}

/** One condition → one Sieve test. */
export function compileCondition(c: FilterCondition, requires: Set<string>): string {
  const v = c.value;
  const negate = c.op === "notContains";
  const matchPart = (): string => {
    switch (c.op) {
      case "is":
        return `:is ${sq(v)}`;
      case "startsWith":
        return `:matches ${sq(literal(v) + "*")}`;
      case "endsWith":
        return `:matches ${sq("*" + literal(v))}`;
      default:
        return `:contains ${sq(v)}`;
    }
  };
  let test: string;
  switch (c.field) {
    case "from":
      test = `address :all ${matchPart()}`.replace(/^address :all (:\w+)/, `address :all $1 "from"`);
      break;
    case "domain":
      test = `address :domain ${matchPart()}`.replace(/^address :domain (:\w+)/, `address :domain $1 "from"`);
      break;
    case "to":
      test = `address :all ${matchPart()}`.replace(/^address :all (:\w+)/, `address :all $1 ["to", "cc"]`);
      break;
    case "subject":
      test = `header ${matchPart()}`.replace(/^header (:\w+)/, `header $1 "subject"`);
      break;
    case "body":
      requires.add("body");
      test = `body :text :contains ${sq(v)}`;
      break;
    case "header": {
      const name = sq(c.header ?? "");
      if (c.op === "exists") return `exists ${name}`;
      test = `header ${matchPart()}`.replace(/^header (:\w+)/, `header $1 ${name}`);
      break;
    }
  }
  return negate ? `not ${test}` : test;
}

function folderFor(a: FilterAction, roles: RoleFolders): string | null {
  switch (a.type) {
    case "move":
      return a.folder ?? null;
    case "delete":
      return roles.trash;
    case "skipInbox":
      return roles.archive;
    case "spam":
      return roles.junk;
    default:
      return null;
  }
}

function compileRule(rule: FilterRule, roles: RoleFolders, requires: Set<string>): string[] {
  const tests = rule.conditions.map((c) => compileCondition(c, requires));
  const test = tests.length === 1 ? tests[0] : `${rule.matchMode === "any" ? "anyof" : "allof"} (${tests.join(", ")})`;
  const body: string[] = [];
  for (const a of rule.actions) {
    if (a.type === "markRead") {
      requires.add("imap4flags");
      body.push(`  addflag ${sq("\\Seen")};`);
    } else if (a.type === "label" && a.label) {
      requires.add("imap4flags");
      body.push(`  addflag ${sq(labelKeyword(a.label))};`);
    } else if (a.type === "forward" && a.to) {
      // Loop guard: never re-forward an auto-reply (the classic two-mailbox
      // ping-pong). Pigeonhole adds its own duplicate-redirect and max-redirect
      // limits on top; the save path also rejects forwarding cycles between
      // mailboxes we host (lib/actions-mail-filters.ts).
      requires.add("copy");
      body.push(`  if not header :contains "auto-submitted" "auto-replied" { redirect :copy ${sq(a.to)}; }`);
    }
  }
  const terminal = rule.actions.map((a) => folderFor(a, roles)).find((f): f is string => Boolean(f));
  if (terminal) {
    requires.add("fileinto");
    requires.add("imap4flags");
    body.push(`  addflag ${sq(FILTERED_KEYWORD)};`);
    body.push(`  fileinto ${sq(terminal)};`);
  }
  if (rule.stopProcessing) body.push("  stop;");
  const safeName = rule.name.replace(/[\r\n]/g, " ").slice(0, 80);
  return [`${MARK_RULE} ${rule.id} ${safeName}`, `if ${test}`, "{", ...body, "}"];
}

/**
 * Compile a mailbox's filter state. Returns "" when there is nothing to enforce
 * (the sync path then DELETES the managed filter, so clearing everything really
 * clears it on the server).
 */
export function compileFilterScript(opts: {
  address: string;
  rules: FilterRule[];
  senders: SenderEntry[];
  roles: RoleFolders;
}): string {
  const rules = opts.rules.filter((r) => r.enabled).sort((a, b) => a.position - b.position);
  const blocked = [...new Set(opts.senders.filter((s) => s.kind === "block").map((s) => s.pattern.toLowerCase()))];
  const allowed = [...new Set(opts.senders.filter((s) => s.kind === "allow").map((s) => s.pattern.toLowerCase()))];
  const blockedAddrs = blocked.filter((p) => !p.startsWith("@"));
  const blockedDomains = blocked.filter((p) => p.startsWith("@")).map((p) => p.slice(1));

  // Legacy shape: exactly what the old "Block sender" button produced.
  if (rules.length === 0 && allowed.length === 0 && blockedDomains.length === 0) {
    return buildBlockSenderSieve(blockedAddrs, opts.roles.junk);
  }

  const requires = new Set<string>();
  const out: string[] = [];

  const senderTests = (list: string[]): string[] =>
    list.map((p) =>
      p.startsWith("@") ? `address :domain :is "from" ${sq(p.slice(1))}` : `address :all :is "from" ${sq(p)}`,
    );

  if (allowed.length) {
    // "Never filter": these senders skip every rule below (and the blocklist).
    out.push(MARK_ALLOW + " " + allowed.join(", "));
    out.push(`if anyof (${senderTests(allowed).join(", ")})`, "{", "  stop;", "}", "");
  }
  if (blocked.length) {
    requires.add("fileinto");
    requires.add("imap4flags");
    out.push(`if anyof (${senderTests([...blockedAddrs, ...blockedDomains.map((d) => "@" + d)]).join(", ")})`);
    out.push("{", `  addflag ${sq(FILTERED_KEYWORD)};`, `  fileinto ${sq(opts.roles.junk)};`, "  stop;", "}", "");
  }
  for (const r of rules) out.push(...compileRule(r, opts.roles, requires), "");

  const header = [
    "# Generated by Nxeon from your filters and blocked senders. Changes here are overwritten.",
    `# Mailbox: ${opts.address.replace(/[\r\n]/g, "")}`,
    `${MARK_BLOCKED} ${blocked.join(", ")}`,
  ];
  const req = requires.size ? [`require [${[...requires].sort().map((r) => sq(r)).join(", ")}];`, ""] : [];
  while (out.length && out[out.length - 1] === "") out.pop();
  return [...header, "", ...req, ...out].join("\r\n").concat("\r\n");
}

export function scriptHash(script: string): string {
  return createHash("sha256").update(script).digest("hex").slice(0, 32);
}

