// TypeScript mirror of the compiled Sieve semantics (./compile.ts).
//
// Used for (1) "apply this rule to existing mail" — an on-demand IMAP sweep,
// because Sieve only ever sees NEW deliveries — (2) the "N messages in your
// inbox would match" preview in the rule editor, and (3) unit tests, which
// assert the compiler and this evaluator agree on fixtures. Pure, no I/O.
//
// Matching follows Sieve's default comparator (i;ascii-casemap): ASCII
// case-insensitive. `address :all` tests EVERY address in the header.

import {
  FILTERED_KEYWORD,
  labelKeyword,
  type FilterCondition,
  type FilterRule,
  type SenderEntry,
} from "./types";
import type { RoleFolders } from "./compile";

export type EvalMessage = {
  from: string[]; // bare addresses
  to: string[]; // To + Cc addresses
  subject: string;
  /** lower-cased header name → decoded values */
  headers: Record<string, string[]>;
  bodyText: string;
};

export type EvalResult = {
  allowed: boolean; // matched the "never filter" list
  blocked: boolean; // matched the block list
  matched: { id: string; name: string }[];
  flags: string[]; // flags/keywords Sieve would add
  folder: string | null; // destination (null = stays in the inbox)
  forwards: string[];
};

const lc = (s: string) => s.toLowerCase();

function matchValue(op: FilterCondition["op"], hay: string, needle: string): boolean {
  const h = lc(hay);
  const n = lc(needle);
  switch (op) {
    case "is":
      return h === n;
    case "startsWith":
      return h.startsWith(n);
    case "endsWith":
      return h.endsWith(n);
    case "contains":
    case "notContains":
      return h.includes(n);
    default:
      return false;
  }
}

const domainOf = (addr: string) => lc(addr.split("@").pop() ?? "");

export function evalCondition(c: FilterCondition, m: EvalMessage): boolean {
  const any = (values: string[]) => values.some((v) => matchValue(c.op, v, c.value));
  let hit: boolean;
  switch (c.field) {
    case "from":
      hit = any(m.from);
      break;
    case "domain":
      hit = any(m.from.map(domainOf));
      break;
    case "to":
      hit = any(m.to);
      break;
    case "subject":
      hit = matchValue(c.op, m.subject, c.value);
      break;
    case "body":
      hit = lc(m.bodyText).includes(lc(c.value));
      break;
    case "header": {
      const values = m.headers[lc(c.header ?? "")] ?? [];
      if (c.op === "exists") return values.length > 0;
      hit = any(values);
      break;
    }
  }
  return c.op === "notContains" ? !hit : hit;
}

export function ruleMatches(rule: Pick<FilterRule, "conditions" | "matchMode">, m: EvalMessage): boolean {
  if (rule.conditions.length === 0) return false;
  return rule.matchMode === "any"
    ? rule.conditions.some((c) => evalCondition(c, m))
    : rule.conditions.every((c) => evalCondition(c, m));
}

function senderMatches(pattern: string, from: string[]): boolean {
  const p = lc(pattern);
  return p.startsWith("@") ? from.some((a) => domainOf(a) === p.slice(1)) : from.some((a) => lc(a) === p);
}

export function evaluateFilters(opts: {
  rules: FilterRule[];
  senders: SenderEntry[];
  roles: RoleFolders;
  msg: EvalMessage;
}): EvalResult {
  const res: EvalResult = { allowed: false, blocked: false, matched: [], flags: [], folder: null, forwards: [] };
  const { msg } = opts;
  if (opts.senders.some((s) => s.kind === "allow" && senderMatches(s.pattern, msg.from))) {
    res.allowed = true;
    return res;
  }
  if (opts.senders.some((s) => s.kind === "block" && senderMatches(s.pattern, msg.from))) {
    res.blocked = true;
    res.flags.push(FILTERED_KEYWORD);
    res.folder = opts.roles.junk;
    return res;
  }
  const rules = opts.rules.filter((r) => r.enabled).sort((a, b) => a.position - b.position);
  for (const r of rules) {
    if (!ruleMatches(r, msg)) continue;
    res.matched.push({ id: r.id, name: r.name });
    let terminal: string | null = null;
    for (const a of r.actions) {
      if (a.type === "markRead") res.flags.push("\\Seen");
      else if (a.type === "label" && a.label) res.flags.push(labelKeyword(a.label));
      else if (a.type === "forward" && a.to) {
        const auto = (msg.headers["auto-submitted"] ?? []).some((v) => lc(v).includes("auto-replied"));
        if (!auto) res.forwards.push(a.to);
      } else if (a.type === "move" && a.folder) terminal = a.folder;
      else if (a.type === "delete") terminal = opts.roles.trash;
      else if (a.type === "skipInbox") terminal = opts.roles.archive;
      else if (a.type === "spam") terminal = opts.roles.junk;
    }
    if (terminal) {
      res.flags.push(FILTERED_KEYWORD);
      res.folder = terminal;
    }
    if (r.stopProcessing) break;
  }
  res.flags = [...new Set(res.flags)];
  return res;
}

/** Structural slice of mailparser's output we need (kept import-free for tests). */
export type ParsedLike = {
  subject?: string;
  text?: string;
  html?: string | false;
  headerLines?: { key: string; line: string }[];
  headers?: Map<string, unknown>;
  from?: { value?: { address?: string }[] };
  to?: unknown;
  cc?: unknown;
};

function addrList(v: unknown): string[] {
  const out: string[] = [];
  const visit = (x: unknown) => {
    if (!x) return;
    if (Array.isArray(x)) return x.forEach(visit);
    const o = x as { value?: unknown[]; address?: string; group?: unknown[] };
    if (o.address) out.push(lc(o.address));
    if (o.group) o.group.forEach(visit);
    if (o.value) o.value.forEach(visit);
  };
  visit(v);
  return out;
}

/** Build an EvalMessage from a mailparser result. */
export function toEvalMessage(p: ParsedLike): EvalMessage {
  const headers: Record<string, string[]> = {};
  for (const h of p.headerLines ?? []) {
    const key = lc(h.key);
    const value = h.line.slice(h.line.indexOf(":") + 1).trim();
    (headers[key] ??= []).push(value);
  }
  const htmlText = typeof p.html === "string" ? p.html.replace(/<[^>]+>/g, " ") : "";
  return {
    from: addrList(p.from),
    to: [...addrList(p.to), ...addrList(p.cc)],
    subject: p.subject ?? "",
    headers,
    bodyText: (p.text || htmlText).slice(0, 200_000),
  };
}

