// Built-in filter presets, written against what actually lands in the Nxeon
// company inboxes (sampled read-only on 2026-10-01: contact@ is mostly
// Trustpilot/Google "review removal" sellers, support@ gets DMARC aggregate
// reports + "get your product listed" pitches, santino@ gets outreach bounces).
//
// Presets are OPT-IN templates: enabling one creates an ordinary rule the owner
// can edit or delete. The rule editor previews how many current inbox messages
// a preset would catch before it is saved, so a false positive is visible
// up front rather than discovered in the Spam folder.

import type { FilterRuleInput } from "./types";

export type FilterPreset = {
  key: string;
  title: string;
  description: string;
  rule: FilterRuleInput;
};

