import { test } from "node:test";
import assert from "node:assert/strict";
import { compileFilterScript, compileCondition } from "../lib/mail/filters/compile.ts";
import { evaluateFilters, toEvalMessage, type EvalMessage } from "../lib/mail/filters/evaluate.ts";
import { parseRule, normaliseSenderPattern, type FilterRule, FILTERED_KEYWORD } from "../lib/mail/filters/types.ts";
import { FILTER_PRESETS } from "../lib/mail/filters/presets.ts";
import { buildBlockSenderSieve, parseBlockedSenders } from "../lib/mail/sieve.ts";

/* Webmail filter engine: validation, Sieve compilation, and the TypeScript
 * evaluator that mirrors it (used by "apply to existing mail" + previews). */

const roles = { junk: "Junk", trash: "Trash", archive: "Archive" };

function rule(id: string, position: number, input: unknown): FilterRule {
  const r = parseRule(input);
  if (!r.ok) throw new Error(r.error);
  return { ...r.rule, id, position };
}

function msg(over: Partial<EvalMessage>): EvalMessage {
  return { from: ["someone@example.com"], to: ["support@nxeon.cloud"], subject: "", headers: {}, bodyText: "", ...over };
}

// Fixtures modelled on what the real company inboxes receive.
const FIXTURES = {
  dmarc: msg({ from: ["noreply-dmarc-support@google.com"], subject: "Report Domain: trynxeon.com Submitter: google.com Report-ID: 1" }),
  gsc: msg({ from: ["sc-noreply@google.com"], subject: "New Coverage issue detected for site nxeon.cloud" }),
  review: msg({ from: ["sales@reviewboost.test"], subject: "Get Permanent 5-star Reviews With Old Account", bodyText: "we remove negative reviews fast" }),
  coldSaas: msg({ from: ["hello@buildfinds.test"], subject: "Get your product listed on BuildFinds" }),
  seo: msg({ from: ["rank@seo-guru.test"], subject: "Guaranteed backlinks for nxeon.cloud" }),
  bounce: msg({ from: ["MAILER-DAEMON@mail.nxeon.cloud"], subject: "Undelivered Mail Returned to Sender" }),
  real: msg({ from: ["creator@gmail.com"], subject: "Re: Zeroster × Nxeon — Creator Partner Invite", bodyText: "Sounds good, let's talk." }),
};

test("parseRule validates and normalises", () => {
  assert.equal(parseRule({ name: "", conditions: [], actions: [] }).ok, false);
  const bad = parseRule({ name: "x", conditions: [{ field: "header", op: "contains", value: "a", header: "Bad Header!" }], actions: [{ type: "markRead" }] });
  assert.equal(bad.ok, false);
  const fwd = parseRule({ name: "x", conditions: [{ field: "subject", op: "contains", value: "a" }], actions: [{ type: "forward", to: "not-an-email" }] });
  assert.equal(fwd.ok, false);
  const two = parseRule({ name: "x", conditions: [{ field: "subject", op: "contains", value: "a" }], actions: [{ type: "spam" }, { type: "delete" }] });
  assert.equal(two.ok, false, "only one terminal action per rule");
  const ok = parseRule({ name: " Move ", stopProcessing: false, conditions: [{ field: "subject", op: "contains", value: "  hi " }], actions: [{ type: "move", folder: "Promos" }] });
  assert.ok(ok.ok);
  if (ok.ok) {
    assert.equal(ok.rule.name, "Move");
    assert.equal(ok.rule.conditions[0].value, "hi");
    assert.equal(ok.rule.stopProcessing, true, "a filing rule always stops (no duplicate copies)");
  }
  const glob = parseRule({ name: "x", conditions: [{ field: "subject", op: "contains", value: "a" }], actions: [{ type: "move", folder: "*" }] });
  assert.equal(glob.ok, false, "wildcards are not folder names");
});

test("sender patterns normalise to address or @domain", () => {
  assert.equal(normaliseSenderPattern("Spam Co <SALES@Spam.test>"), "sales@spam.test");
  assert.equal(normaliseSenderPattern("spam.test"), "@spam.test");
  assert.equal(normaliseSenderPattern("@spam.test"), "@spam.test");
  assert.equal(normaliseSenderPattern("*.spam.test"), "@spam.test");
  assert.equal(normaliseSenderPattern("not a domain"), null);
  assert.equal(normaliseSenderPattern("a\nb@x.com"), null);
});

test("with only address blocks the script is byte-identical to the legacy block filter", () => {
  const senders = [
    { kind: "block" as const, pattern: "a@spam.test" },
    { kind: "block" as const, pattern: "b@spam.test" },
  ];
  const script = compileFilterScript({ address: "owner@acme.test", rules: [], senders, roles });
  assert.equal(script, buildBlockSenderSieve(["a@spam.test", "b@spam.test"], "Junk"));
  assert.deepEqual(parseBlockedSenders(script), ["a@spam.test", "b@spam.test"]);
  assert.equal(compileFilterScript({ address: "x@y.z", rules: [], senders: [], roles }), "", "nothing to enforce → empty (filter deleted)");
});

test("full script: requires, allow-list first, quoting, wildcard escaping, forward guard", () => {
  const rules = [
    rule("r1", 0, { name: "Promos", conditions: [{ field: "subject", op: "startsWith", value: 'Deal * "now"' }], actions: [{ type: "move", folder: "Promos" }, { type: "markRead" }] }),
    rule("r2", 1, { name: "Fwd", stopProcessing: false, conditions: [{ field: "body", op: "contains", value: "invoice" }], actions: [{ type: "forward", to: "Books@Acme.test" }, { type: "label", label: "Finance team" }] }),
  ];
  const senders = [
    { kind: "allow" as const, pattern: "@trusted.test" },
    { kind: "block" as const, pattern: "@spam.test" },
  ];
  const s = compileFilterScript({ address: "santino@nxeon.cloud", rules, senders, roles });
  assert.match(s, /^require \["body", "copy", "fileinto", "imap4flags"\];/m);
  assert.ok(s.indexOf('address :domain :is "from" "trusted.test"') < s.indexOf('address :domain :is "from" "spam.test"'), "allow-list runs before the blocklist");
  assert.match(s, /header :matches "subject" "Deal \\\\\* \\"now\\"\*"/, "user * is escaped, quotes escaped, trailing * is the wildcard");
  assert.match(s, /addflag "\\\\Seen";/);
  assert.match(s, /addflag "\$Label_Finance_team";/);
  assert.match(s, /if not header :contains "auto-submitted" "auto-replied" \{ redirect :copy "books@acme.test"; \}/);
  assert.match(s, new RegExp(`addflag "\\${FILTERED_KEYWORD}";\\r\\n  fileinto "Promos";\\r\\n  stop;`));
  assert.ok(!/\n(?<!\r)\n/.test(s.replace(/\r\n/g, "")), "CRLF line endings only");
  assert.ok(s.split("\r\n").every((l) => !/[\u0000-\u0008]/.test(l)));
});

test("disabled rules are not compiled", () => {
  const r = rule("r1", 0, { name: "Off", enabled: false, conditions: [{ field: "subject", op: "contains", value: "x" }], actions: [{ type: "spam" }] });
  const s = compileFilterScript({ address: "a@b.c", rules: [r], senders: [{ kind: "allow", pattern: "@ok.test" }], roles });
  assert.ok(!s.includes("# nxeon:rule r1"));
});

test("compileCondition covers every field/op", () => {
  const req = new Set<string>();
  assert.equal(compileCondition({ field: "from", op: "is", value: "a@b.c" }, req), 'address :all :is "from" "a@b.c"');
  assert.equal(compileCondition({ field: "domain", op: "endsWith", value: ".ru" }, req), 'address :domain :matches "from" "*.ru"');
  assert.equal(compileCondition({ field: "to", op: "contains", value: "sales" }, req), 'address :all :contains ["to", "cc"] "sales"');
  assert.equal(compileCondition({ field: "header", op: "exists", value: "", header: "List-Unsubscribe" }, req), 'exists "List-Unsubscribe"');
  assert.equal(compileCondition({ field: "subject", op: "notContains", value: "Re:" }, req), 'not header :contains "subject" "Re:"');
  assert.equal(compileCondition({ field: "body", op: "contains", value: "x" }, req), 'body :text :contains "x"');
  assert.ok(req.has("body"));
});

test("every preset parses, compiles, and catches its own fixture but not real mail", () => {
  const expect: Record<string, keyof typeof FIXTURES> = {
    "dmarc-reports": "dmarc",
    "search-console": "gsc",
    "review-sellers": "review",
    "cold-saas": "coldSaas",
    "seo-spam": "seo",
    bounces: "bounce",
  };
  FILTER_PRESETS.forEach((p, i) => {
    const r = rule(p.key, i, p.rule);
    const script = compileFilterScript({ address: "support@nxeon.cloud", rules: [r], senders: [], roles });
    assert.ok(script.includes(`# nxeon:rule ${p.key}`), p.key);
    const hit = evaluateFilters({ rules: [r], senders: [], roles, msg: FIXTURES[expect[p.key]] });
    assert.equal(hit.matched.length, 1, `${p.key} should match its fixture`);
    const miss = evaluateFilters({ rules: [r], senders: [], roles, msg: FIXTURES.real });
    assert.equal(miss.matched.length, 0, `${p.key} must not match a real creator reply`);
  });
});

test("evaluator: allow beats block beats rules; flags accumulate; stop ends processing", () => {
  const rules = [
    rule("label", 0, { name: "Label", stopProcessing: false, conditions: [{ field: "domain", op: "is", value: "client.test" }], actions: [{ type: "label", label: "VIP" }, { type: "markRead" }] }),
    rule("arch", 1, { name: "Archive", conditions: [{ field: "subject", op: "contains", value: "newsletter" }], actions: [{ type: "skipInbox" }] }),
    rule("never", 2, { name: "Never reached", conditions: [{ field: "subject", op: "contains", value: "newsletter" }], actions: [{ type: "spam" }] }),
  ];
  const m = msg({ from: ["boss@client.test"], subject: "Monthly Newsletter" });
  const r = evaluateFilters({ rules, senders: [], roles, msg: m });
  assert.deepEqual(r.matched.map((x) => x.id), ["label", "arch"]);
  assert.equal(r.folder, "Archive");
  assert.deepEqual(r.flags.sort(), ["$Label_VIP", FILTERED_KEYWORD, "\\Seen"].sort());

  const blocked = evaluateFilters({ rules, senders: [{ kind: "block", pattern: "@client.test" }], roles, msg: m });
  assert.equal(blocked.blocked, true);
  assert.equal(blocked.folder, "Junk");
  const allowed = evaluateFilters({ rules, senders: [{ kind: "block", pattern: "@client.test" }, { kind: "allow", pattern: "boss@client.test" }], roles, msg: m });
  assert.equal(allowed.allowed, true);
  assert.equal(allowed.folder, null);
});

test("evaluator: forward skips auto-replies (loop guard mirrors the Sieve guard)", () => {
  const rules = [rule("f", 0, { name: "Fwd", conditions: [{ field: "subject", op: "contains", value: "order" }], actions: [{ type: "forward", to: "ops@acme.test" }] })];
  assert.deepEqual(evaluateFilters({ rules, senders: [], roles, msg: msg({ subject: "New order" }) }).forwards, ["ops@acme.test"]);
  const auto = msg({ subject: "Re: New order", headers: { "auto-submitted": ["auto-replied"] } });
  assert.deepEqual(evaluateFilters({ rules, senders: [], roles, msg: auto }).forwards, []);
});

test("toEvalMessage reads mailparser-shaped output", () => {
  const m = toEvalMessage({
    subject: "Hello",
    text: "Body here",
    from: { value: [{ address: "A@B.test" }] },
    to: { value: [{ address: "x@y.test" }] },
    cc: [{ value: [{ address: "c@d.test" }] }],
    headerLines: [{ key: "List-Id", line: "List-Id: <news.example>" }],
  });
  assert.deepEqual(m.from, ["a@b.test"]);
  assert.deepEqual(m.to, ["x@y.test", "c@d.test"]);
  assert.deepEqual(m.headers["list-id"], ["<news.example>"]);
  assert.equal(m.bodyText, "Body here");
});

