    assert.ok(script.includes(`# nxeon:rule ${p.key}`), p.key);
    const hit = evaluateFilters({ rules: [r], senders: [], roles, msg: FIXTURES[expect[p.key]] });
    assert.equal(hit.matched.length, 1, `${p.key} should match its fixture`);
    const miss = evaluateFilters({ rules: [r], senders: [], roles, msg: FIXTURES.real });
