test("evaluator: allow beats block beats rules; flags accumulate; stop ends processing", () => {
  const rules = [
    rule("label", 0, { name: "Label", stopProcessing: false, conditions: [{ field: "domain", op: "is", value: "client.test" }], actions: [{ type: "label", label: "VIP" }, { type: "markRead" }] }),
    rule("arch", 1, { name: "Archive", conditions: [{ field: "subject", op: "contains", value: "newsletter" }], actions: [{ type: "skipInbox" }] }),
    rule("never", 2, { name: "Never reached", conditions: [{ field: "subject", op: "contains", value: "newsletter" }], actions: [{ type: "spam" }] }),
  ];
  const m = msg({ from: ["boss@client.test"], subject: "Monthly Newsletter" });
  const r = evaluateFilters({ rules, senders: [], roles, msg: m });
  assert.deepEqual(r.matched.map((x) => x.id), ["label", "arch"]);
  assert.equal(r.folder, "Archive");
