  return withImap(cred, async (client) => {
    const list = await client.list();
    const find = (role: string, fallback: string) =>
      list.find((f) => folderRole(f.path, f.specialUse) === role)?.path ?? fallback;
    return {
      junk: find("junk", "Junk"),
      trash: find("trash", "Trash"),
      archive: find("archive", "Archive"),
      delimiter: list.find((f) => f.delimiter)?.delimiter || "/",
      paths: list.map((f) => f.path),
    };
  });
}

/** Rules store folders with "/" — map to the server's real hierarchy delimiter. */
export function toServerPath(folder: string, delimiter: string): string {
  return delimiter === "/" ? folder : folder.split("/").join(delimiter);
}

/**
 * Make sure every folder a rule files into exists (Sieve `fileinto` into a
 * missing folder falls back to the inbox, which would look like the rule
 * silently not working).
 */
export async function ensureRuleFolders(cred: MailboxCredentials, rules: FilterRule[]): Promise<void> {
  const wanted = [...new Set(rules.flatMap((r) => r.actions.filter((a) => a.type === "move" && a.folder).map((a) => a.folder!)))];
  if (wanted.length === 0) return;
  await withImap(cred, async (client) => {
    const list = await client.list();
    const delimiter = list.find((f) => f.delimiter)?.delimiter || "/";
    const have = new Set(list.map((f) => f.path.toLowerCase()));
    for (const w of wanted) {
      const path = toServerPath(w, delimiter);
      if (have.has(path.toLowerCase())) continue;
      try {
        await client.mailboxCreate(path);
        await client.mailboxSubscribe(path).catch(() => {});
      } catch {
        /* exists already (race) or refused — the sync status will still be honest */
      }
    }
  });
}

/**
 * One-time import of a legacy "Block sender" list (kept only inside the old
 * script's marker line) into MailFilterSender, so moving to the combined script
 * never drops a block the customer already had.
 */
async function importLegacyBlocks(address: string, liveScript: string | undefined, createdById?: string): Promise<void> {
  if (!liveScript) return;
  const legacy = parseBlockedSenders(liveScript);
  for (const raw of legacy) {
    const pattern = normaliseSenderPattern(raw);
    if (!pattern) continue;
    await db.mailFilterSender
      .upsert({
        where: { mailboxAddress_kind_pattern: { mailboxAddress: address, kind: "block", pattern } },
        update: {},
        create: { mailboxAddress: address, kind: "block", pattern, createdById },
      })
      .catch(() => {});
  }
}

async function record(address: string, ok: boolean, error: string | null, hash: string | null): Promise<void> {
  await db.mailFilterSync
    .upsert({
      where: { mailboxAddress: address },
      update: { syncedAt: ok ? new Date() : undefined, error, scriptHash: hash },
      create: { mailboxAddress: address, syncedAt: ok ? new Date() : null, error, scriptHash: hash },
    })
    .catch(() => {});
}

/**
 * Compile + push. Never throws: returns the resulting status (also persisted).
 * `actorId` is only used to attribute imported legacy blocks.
 */
export async function syncMailboxFilters(
  cred: MailboxCredentials,
  opts: { actorId?: string } = {},
): Promise<SyncStatus> {
  const address = cred.address.trim().toLowerCase();
  if (!mailcowConfigured()) {
    const error = "The mail server API isn't configured on this instance, so rules can't be enforced on delivery. “Apply to existing mail” still works.";
    await record(address, false, error, null);
    return { state: "unconfigured", syncedAt: null, error };
  }
  try {
    const existing = await mcListFilters(address);
    const ours = existing.filter((f) => isNxeonPostfilter(f.scriptDesc) && f.filterType === NXEON_BLOCK_TYPE);
    const foreignActive = existing.find(
      (f) => f.filterType === NXEON_BLOCK_TYPE && f.active && !isNxeonPostfilter(f.scriptDesc),
    );
    if (foreignActive) {
      const error = `This mailbox already has a hand-made Sieve postfilter on the mail server (“${foreignActive.scriptDesc.slice(0, 60)}”). Nxeon won't deactivate it — remove or merge it in Mailcow, then retry.`;
      await record(address, false, error, null);
      return { state: "error", syncedAt: null, error };
    }
    await importLegacyBlocks(address, ours[0]?.scriptData, opts.actorId);

    const state = await loadFilterState(address);
    const roles = await resolveRoleFolders(cred);
    const rules = state.rules.map((r) => ({
      ...r,
      actions: r.actions.map((a) => (a.type === "move" && a.folder ? { ...a, folder: toServerPath(a.folder, roles.delimiter) } : a)),
    }));
    await ensureRuleFolders(cred, state.rules.filter((r) => r.enabled));
    const script = compileFilterScript({ address, rules, senders: state.senders, roles });
    const hash = script ? scriptHash(script) : null;

    const [keep, ...dupes] = ours;
    for (const d of dupes) await mcDeleteFilter(d.id);
    if (!script) {
      if (keep) await mcDeleteFilter(keep.id);
      await record(address, true, null, null);
      return { state: "empty", syncedAt: new Date().toISOString(), error: null };
    }
    // Byte-identical legacy output keeps the legacy description so a customer
    // who only ever blocked senders sees no change at all on the server.
    const desc = script.startsWith("# Generated by Nxeon from your blocked senders") ? NXEON_BLOCK_DESC : NXEON_FILTERS_DESC;
    if (keep) {
      await mcEditFilter(keep.id, { scriptDesc: desc, scriptData: script, filterType: NXEON_BLOCK_TYPE, active: true });
    } else {
      await mcAddFilter({ address, scriptDesc: desc, scriptData: script, filterType: NXEON_BLOCK_TYPE, active: true });
    }
    await record(address, true, null, hash);
    return { state: "synced", syncedAt: new Date().toISOString(), error: null };
  } catch (e) {
    const error = `The mail server rejected the filter update: ${String((e as Error)?.message ?? e).replace(/\s+/g, " ").slice(0, 220)}`;
    await record(address, false, error, null);
    return { state: "error", syncedAt: null, error };
  }
}

/** Last recorded sync status, for display. */
export async function getSyncStatus(address: string): Promise<SyncStatus> {
  const row = await db.mailFilterSync.findUnique({ where: { mailboxAddress: address.trim().toLowerCase() } });
  if (!row) return { state: mailcowConfigured() ? "empty" : "unconfigured", syncedAt: null, error: null };
  if (row.error) return { state: mailcowConfigured() ? "error" : "unconfigured", syncedAt: row.syncedAt?.toISOString() ?? null, error: row.error };
  return { state: row.scriptHash ? "synced" : "empty", syncedAt: row.syncedAt?.toISOString() ?? null, error: null };
}

