export type ListResult = {
  messages: MessageSummary[];
  total: number;
  page: number;
  pageSize: number;
};

/** A file to attach, carried from the composer to the SMTP send (transient — never stored). */
export type SendAttachment = {
  filename: string;
  contentType: string; // MIME type; server defaults to application/octet-stream
  contentBase64: string; // raw base64 (no "data:*;base64," prefix)
  /**
   * When set, this attachment is an INLINE image referenced from the HTML body
   * as `src="cid:<cid>"`. The send path gives it this Content-ID and marks it
   * `inline` so mail clients render it in-place (multipart/related) instead of
   * listing it as a download. Absent = an ordinary attached file.
   */
  cid?: string;
};

/**
 * Build the download URL for one attachment part of one message.
 *
 * `mailbox` is NOT optional decoration. `app/api/mail/attachment/route.ts` calls
 * `resolveMailbox(mailbox)`, and `resolveMailbox(undefined)` resolves the
 * account's DEFAULT (oldest) mailbox — not the one being read. The reading pane
 * used to build this href by hand and omit the parameter, so on an account with
 * two mailboxes every attachment opened from the second one was fetched with
 * `<uid>` interpreted against the FIRST mailbox's IMAP session. IMAP UIDs are
 * per-folder counters that start at 1 in every mailbox, so that lookup usually
 * SUCCEEDS and returns a different message's file — the wrong document, handed
 * over with no error anywhere. Centralised here so it cannot be forgotten again.
 */
export function mailAttachmentUrl(opts: {
  folder: string;
  uid: number;
  /** Either the bare IMAP part id or the `"<uid>:<partId>"` attachment id. */
  part: string;
  /** The mailbox the message was read from. */
  mailbox?: string;
}): string {
  const qs = new URLSearchParams({
    folder: opts.folder,
    uid: String(opts.uid),
    part: opts.part,
  });
  if (opts.mailbox) qs.set("mailbox", opts.mailbox);
  return `/api/mail/attachment?${qs.toString()}`;
}

export type SendPayload = {
  to: string; // comma-separated
  cc?: string;
  bcc?: string;
  subject: string;
  text?: string;
  html?: string;
  inReplyToUid?: number; // for replies (sets In-Reply-To / References)
  replyFolder?: string; // folder of the message being replied to
  attachments?: SendAttachment[]; // transient file attachments (not persisted)
};

