// Per-mailbox unread counts (INBOX `STATUS UNSEEN MESSAGES UIDNEXT`).
//
// Plain server-side module. One cheap STATUS per mailbox — not a full LIST with
// per-folder status like listFolders — and a short in-process TTL cache so the
// switcher badges, the admin email bubble and the document-title counter can
// all poll without each opening its own IMAP session. The cache key is the
// mailbox ADDRESS; callers must authorise before asking (see the rpc route and
// app/api/admin/inbox-unread), this module never decides access.

import { withImap, type MailboxCredentials } from "./imap";
import type { MailboxUnread } from "./types";

const TTL_MS = 20_000;
const cache = new Map<string, { at: number; value: MailboxUnread }>();
const inflight = new Map<string, Promise<MailboxUnread>>();

/** Forget a mailbox's cached count (call after marking messages read/unread). */
export function invalidateUnread(address: string): void {
  cache.delete(address.trim().toLowerCase());
}

export async function inboxUnread(cred: MailboxCredentials, opts: { fresh?: boolean } = {}): Promise<MailboxUnread> {
  const key = cred.address.trim().toLowerCase();
  const hit = cache.get(key);
  if (!opts.fresh && hit && Date.now() - hit.at < TTL_MS) return hit.value;
  const pending = inflight.get(key);
  if (pending) return pending;
  const p = withImap(cred, async (client) => {
    const st = await client.status("INBOX", { unseen: true, messages: true, uidNext: true });
    return {
      address: key,
      unread: st.unseen ?? 0,
      messages: st.messages ?? 0,
      uidNext: typeof st.uidNext === "number" ? st.uidNext : null,
    } satisfies MailboxUnread;
  })
    .then((value) => {
      cache.set(key, { at: Date.now(), value });
      return value;
    })
    .catch((e: unknown) => {
      // Serve the last good value if we have one; otherwise report the failure.
      if (hit) return { ...hit.value, error: "stale" };
      return { address: key, unread: 0, messages: 0, uidNext: null, error: String((e as Error)?.message ?? e).slice(0, 120) };
    })
    .finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p;
}

