/** Structural slice of a mailparser attachment needed to inline cid: images. */
type InlinePart = { cid?: string; contentId?: string; contentType?: string; content?: Buffer; related?: boolean; size?: number };

const MAX_INLINE_PART = 1_500_000; // bytes per inline image
const MAX_INLINE_TOTAL = 6_000_000; // bytes per message

/**
 * Replace `src="cid:…"` references in ALREADY-SANITISED html with data: URIs
 * built from the message's own image parts. Only image/* parts are inlined and
 * sizes are capped; anything else is left as-is (the reading pane then shows
 * the email's alt text, exactly like before). Never throws.
 */
export function inlineCidImages(html: string, parts: InlinePart[]): string {
  if (!html || !/cid:/i.test(html)) return html;
  const byCid = new Map<string, string>();
  let total = 0;
  for (const p of parts) {
    const id = (p.cid || p.contentId || "").replace(/^<|>$/g, "").trim().toLowerCase();
    const type = (p.contentType || "").toLowerCase();
    if (!id || !p.content || !type.startsWith("image/") || !/^image\/[a-z0-9.+-]+$/.test(type)) continue;
    if (p.content.length > MAX_INLINE_PART || total + p.content.length > MAX_INLINE_TOTAL) continue;
    total += p.content.length;
    byCid.set(id, `data:${type};base64,${p.content.toString("base64")}`);
  }
  if (byCid.size === 0) return html;
  return html.replace(/(\ssrc\s*=\s*)(["']?)cid:([^"'\s>]+)\2/gi, (m, pre: string, q: string, raw: string) => {
    let id = raw;
    try {
      id = decodeURIComponent(raw);
    } catch {
      /* keep raw */
    }
    const uri = byCid.get(id.replace(/^<|>$/g, "").toLowerCase());
    return uri ? `${pre}"${uri}"` : m;
  });
}
EOF
