    for (const r of rules) {
      const actions = (r.actions as { type: string; folder?: string }[]) ?? [];
      if (!actions.some((a) => a.type === "move" && a.folder && (a.folder === path || a.folder.split("/").join(".") === path))) continue;
      touched = true;
      await db.mailFilterRule.update({
        where: { id: r.id },
        data: { actions: actions.map((a) => (a.type === "move" && (a.folder === path || a.folder?.split("/").join(".") === path) ? { ...a, folder: res.path } : a)) },
      });
    }
    if (touched) await syncMailboxFilters(cred, { actorId: user.id });
  }
  return res;
}

/**
 * Delete a custom folder. A folder that still holds mail is only deleted with
 * `force` (the UI confirms with the message count first) — Dovecot deletes the
 * messages with the folder, so this must never happen by accident.
 */
export async function deleteFolder(
  path: string,
  mailboxAddress?: string,
  opts?: { force?: boolean },
): Promise<{ ok: boolean; messages?: number; error?: string }> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:folders:${user.id}`, { max: 30, windowMs: 60 * 1000 });
  const mbox = cred.address.toLowerCase();
  const usedBy = (await db.mailFilterRule.findMany({ where: { mailboxAddress: mbox } })).filter((r) =>
    ((r.actions as { type: string; folder?: string }[]) ?? []).some((a) => a.type === "move" && a.folder === path),
  );
  if (usedBy.length) {
    return { ok: false, error: `“${usedBy[0].name}” files mail into this folder — change or delete that rule first.` };
  }
  return withImap(cred, async (client) => {
    await assertCustomFolder(client, path);
    const st = await client.status(path, { messages: true });
    const messages = st.messages ?? 0;
    if (messages > 0 && !opts?.force) return { ok: false, messages, error: `This folder still holds ${messages} message${messages === 1 ? "" : "s"}.` };
    await client.mailboxDelete(path);
    await db.auditLog
      .create({ data: { userId: user.id, action: "mailbox.deleteFolder", detail: `${mbox} ${path} (${messages} messages)` } })
      .catch(() => {});
    return { ok: true, messages };
  });
}

// ---------------------------------------------------------------------------
// Unread counts per mailbox
// ---------------------------------------------------------------------------

/**
 * INBOX unread counts for the given mailboxes (each resolved — and therefore
 * access-checked — through resolveMailbox; one the caller can't open is
 * reported with an error instead of a number, never silently counted).
 */
export async function listMailboxUnread(addresses: string[]): Promise<MailboxUnread[]> {
  const list = [...new Set((Array.isArray(addresses) ? addresses : []).map((a) => String(a).trim().toLowerCase()).filter(Boolean))].slice(0, 12);
  return Promise.all(
    list.map(async (address) => {
      try {
        const { cred } = await resolveMailbox(address);
        return await inboxUnread(cred);
      } catch (e) {
        return { address, unread: 0, messages: 0, uidNext: null, error: String((e as Error)?.message ?? e).slice(0, 120) };
      }
    }),
  );
}
