"use server";

// Server actions for webmail filters, block/allow lists, the spam review queue
// and per-user mail preferences.
//
// AUTHORISATION: every mailbox-scoped action goes through resolveMailbox(), the
// same gate every other webmail action uses — a customer can only reach their
// own mailboxes, staff only the company mailboxes lib/staff-mailbox-access.ts
// allows. Nothing here trusts the address it is handed. Mutations are rate
// limited, audited, idempotent where it makes sense, and re-push the compiled
// Sieve script (lib/mail/filters/sync.ts) so the result is enforced on the mail
// server — or the UI is told exactly why it isn't.

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { resolveMailbox, folderRole, parseMessage, withImap, withMailbox, readFlags, readKeywords, isoDate, toMailAddress, toMailAddresses } from "@/lib/mail/imap";
import type { ImapFlow } from "imapflow";
import type { MessageSummary } from "@/lib/mail/types";
import {
  FILTERED_KEYWORD,
  MAX_FORWARD_TARGETS,
  MAX_RULES_PER_MAILBOX,
  MAX_SENDER_ENTRIES,
  normaliseSenderPattern,
  parseRule,
  type FilterRule,
  type FilterRuleInput,
  type SenderListKind,
} from "@/lib/mail/filters/types";
import { evaluateFilters, ruleMatches, toEvalMessage, type EvalMessage } from "@/lib/mail/filters/evaluate";
import { FILTER_PRESETS, presetByKey } from "@/lib/mail/filters/presets";
import {
  getSyncStatus,
  loadFilterState,
  resolveRoleFolders,
  syncMailboxFilters,
  toServerPath,
  ensureRuleFolders,
  type SyncStatus,
} from "@/lib/mail/filters/sync";

type Result<T = object> = ({ ok: true } & T) | { ok: false; error: string };

function gate(key: string, max = 60): string | null {
  const r = checkRateLimit(key, { max, windowMs: 60_000 });
  return r.ok ? null : `Too many requests — please wait ${r.retryAfterSec}s and try again.`;
}

const errMsg = (e: unknown) => String((e as Error)?.message ?? e).replace(/\s+/g, " ").slice(0, 240);

async function audit(userId: string, action: string, detail: string) {
  await db.auditLog.create({ data: { userId, action, detail: detail.slice(0, 500) } }).catch(() => {});
}

export type SenderRow = { id: string; kind: SenderListKind; pattern: string; createdAt: string };
export type RuleRow = FilterRule & { appliedCount: number; updatedAt: string };
export type FilterState = {
  address: string;
  rules: RuleRow[];
  senders: SenderRow[];
  sync: SyncStatus;
  presets: { key: string; title: string; description: string; enabled: boolean }[];
  /** Folders a rule can file into (custom folders + Archive), "/"-separated. */
  folders: string[];
};

// ---------------------------------------------------------------------------
// Read
// ---------------------------------------------------------------------------

export async function getFilterState(mailboxAddress: string): Promise<Result<{ state: FilterState }>> {
  try {
    const { cred, address } = await resolveMailbox(mailboxAddress);
    const a = address.toLowerCase();
    const [rows, senders, sync] = await Promise.all([
      db.mailFilterRule.findMany({ where: { mailboxAddress: a }, orderBy: [{ position: "asc" }, { createdAt: "asc" }] }),
      db.mailFilterSender.findMany({ where: { mailboxAddress: a }, orderBy: { createdAt: "desc" } }),
      getSyncStatus(a),
    ]);
    const state = await loadFilterState(a);
    let folders: string[] = [];
    try {
      folders = await withImap(cred, async (client) => {
        const list = await client.list();
        const delimiter = list.find((f) => f.delimiter)?.delimiter || "/";
        return list
          .filter((f) => !f.flags?.has("\\Noselect"))
          .filter((f) => ["custom", "archive"].includes(folderRole(f.path, f.specialUse)))
          .map((f) => (delimiter === "/" ? f.path : f.path.split(delimiter).join("/")))
          .sort((x, y) => x.localeCompare(y));
      });
    } catch {
      /* folder list is a convenience for the picker — the page still works */
    }
    const presetKeys = new Set(rows.map((r) => r.presetKey).filter(Boolean));
    return {
      ok: true,
      state: {
        address: a,
        rules: state.rules.map((r) => {
          const row = rows.find((x) => x.id === r.id)!;
          return { ...r, appliedCount: row.appliedCount, updatedAt: row.updatedAt.toISOString() };
        }),
        senders: senders.map((s) => ({ id: s.id, kind: s.kind === "allow" ? "allow" : "block", pattern: s.pattern, createdAt: s.createdAt.toISOString() })),
        sync,
        presets: FILTER_PRESETS.map((p) => ({ key: p.key, title: p.title, description: p.description, enabled: presetKeys.has(p.key) })),
        folders,
      },
    };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

// ---------------------------------------------------------------------------
// Forwarding loop protection
// ---------------------------------------------------------------------------

/** Mailboxes `address` forwards to: enabled rule forwards + the settings-panel forward. */
async function forwardEdges(address: string): Promise<string[]> {
  const a = address.toLowerCase();
  const [rules, mb, cm] = await Promise.all([
    db.mailFilterRule.findMany({ where: { mailboxAddress: a, enabled: true }, select: { actions: true } }),
    db.mailbox.findUnique({ where: { address: a }, select: { forwardingAddress: true } }),
    db.companyMailbox.findUnique({ where: { address: a }, select: { forwardingAddress: true } }),
  ]);
  const out = new Set<string>();
  for (const r of rules) for (const act of (r.actions as { type: string; to?: string }[]) ?? []) if (act.type === "forward" && act.to) out.add(act.to.toLowerCase());
  for (const f of [mb?.forwardingAddress, cm?.forwardingAddress]) if (f) out.add(f.trim().toLowerCase());
  return [...out];
}

/** Would forwarding `source` → `target` close a cycle among mailboxes we host? */
async function forwardCreatesLoop(source: string, target: string): Promise<boolean> {
  const src = source.toLowerCase();
  const seen = new Set<string>();
  let frontier = [target.toLowerCase()];
  for (let depth = 0; depth < 6 && frontier.length; depth++) {
    const next: string[] = [];
    for (const node of frontier) {
      if (node === src) return true;
      if (seen.has(node)) continue;
      seen.add(node);
      next.push(...(await forwardEdges(node)));
    }
    frontier = next;
  }
  return false;
}

async function validateForwards(address: string, rule: FilterRuleInput, excludeRuleId?: string): Promise<string | null> {
  const targets = rule.actions.filter((x) => x.type === "forward" && x.to).map((x) => x.to!);
  if (targets.length === 0) return null;
  for (const t of targets) {
    if (t === address.toLowerCase()) return "A mailbox can't forward to itself.";
    if (await forwardCreatesLoop(address, t)) return `Forwarding to ${t} would create a loop — that mailbox already forwards back here.`;
  }
  const others = await db.mailFilterRule.findMany({ where: { mailboxAddress: address.toLowerCase(), id: excludeRuleId ? { not: excludeRuleId } : undefined } });
  const existing = new Set(
    others.flatMap((r) => ((r.actions as { type: string; to?: string }[]) ?? []).filter((x) => x.type === "forward" && x.to).map((x) => x.to!)),
  );
  targets.forEach((t) => existing.add(t));
  if (existing.size > MAX_FORWARD_TARGETS) return `Up to ${MAX_FORWARD_TARGETS} forwarding addresses per mailbox.`;
  return null;
}

// ---------------------------------------------------------------------------
// Rules CRUD
// ---------------------------------------------------------------------------

export async function saveFilterRule(
  mailboxAddress: string,
  ruleId: string | null,
  input: FilterRuleInput,
): Promise<Result<{ id: string; sync: SyncStatus }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const limited = gate(`mail:filters:${user.id}`);
    if (limited) return { ok: false, error: limited };
    const parsed = parseRule(input);
    if (!parsed.ok) return parsed;
    const rule = parsed.rule;
    const a = address.toLowerCase();
    const loop = await validateForwards(a, rule, ruleId ?? undefined);
    if (loop) return { ok: false, error: loop };

    let id = ruleId;
    if (id) {
      const row = await db.mailFilterRule.findFirst({ where: { id, mailboxAddress: a } });
      if (!row) return { ok: false, error: "That rule no longer exists." };
      await db.mailFilterRule.update({
        where: { id },
        data: { name: rule.name, enabled: rule.enabled, matchMode: rule.matchMode, conditions: rule.conditions, actions: rule.actions, stopProcessing: rule.stopProcessing },
      });
    } else {
      const count = await db.mailFilterRule.count({ where: { mailboxAddress: a } });
      if (count >= MAX_RULES_PER_MAILBOX) return { ok: false, error: `Up to ${MAX_RULES_PER_MAILBOX} rules per mailbox.` };
      const last = await db.mailFilterRule.findFirst({ where: { mailboxAddress: a }, orderBy: { position: "desc" } });
      const row = await db.mailFilterRule.create({
        data: {
          mailboxAddress: a,
          name: rule.name,
          enabled: rule.enabled,
          matchMode: rule.matchMode,
          conditions: rule.conditions,
          actions: rule.actions,
          stopProcessing: rule.stopProcessing,
          presetKey: rule.presetKey ?? null,
          position: (last?.position ?? -1) + 1,
          createdById: user.id,
        },
      });
      id = row.id;
    }
    const sync = await syncMailboxFilters(cred, { actorId: user.id });
    await audit(user.id, ruleId ? "mail.filter.update" : "mail.filter.create", `${a}: ${rule.name} (${id}) sync=${sync.state}`);
    return { ok: true, id: id!, sync };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

export async function deleteFilterRule(mailboxAddress: string, ruleId: string): Promise<Result<{ sync: SyncStatus }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const a = address.toLowerCase();
    const row = await db.mailFilterRule.findFirst({ where: { id: ruleId, mailboxAddress: a } });
    if (row) await db.mailFilterRule.delete({ where: { id: row.id } });
    const sync = await syncMailboxFilters(cred, { actorId: user.id });
    if (row) await audit(user.id, "mail.filter.delete", `${a}: ${row.name} (${row.id})`);
    return { ok: true, sync };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

export async function setFilterRuleEnabled(mailboxAddress: string, ruleId: string, enabled: boolean): Promise<Result<{ sync: SyncStatus }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const a = address.toLowerCase();
    const row = await db.mailFilterRule.findFirst({ where: { id: ruleId, mailboxAddress: a } });
    if (!row) return { ok: false, error: "That rule no longer exists." };
    await db.mailFilterRule.update({ where: { id: row.id }, data: { enabled: Boolean(enabled) } });
    const sync = await syncMailboxFilters(cred, { actorId: user.id });
    await audit(user.id, "mail.filter.toggle", `${a}: ${row.name} → ${enabled ? "on" : "off"}`);
    return { ok: true, sync };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

export async function reorderFilterRules(mailboxAddress: string, orderedIds: string[]): Promise<Result<{ sync: SyncStatus }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const a = address.toLowerCase();
    const rows = await db.mailFilterRule.findMany({ where: { mailboxAddress: a }, select: { id: true } });
    const known = new Set(rows.map((r) => r.id));
    const ids = (Array.isArray(orderedIds) ? orderedIds : []).filter((id) => known.has(id));
    await db.$transaction(ids.map((id, i) => db.mailFilterRule.update({ where: { id }, data: { position: i } })));
    const sync = await syncMailboxFilters(cred, { actorId: user.id });
    return { ok: true, sync };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

export async function enableFilterPreset(mailboxAddress: string, key: string): Promise<Result<{ id: string; sync: SyncStatus }>> {
  const preset = presetByKey(key);
  if (!preset) return { ok: false, error: "Unknown preset." };
  const existing = await db.mailFilterRule.findFirst({ where: { mailboxAddress: mailboxAddress.trim().toLowerCase(), presetKey: key } });
  if (existing) return saveFilterRule(mailboxAddress, existing.id, { ...preset.rule, enabled: true });
  return saveFilterRule(mailboxAddress, null, preset.rule);
}

/** Re-push the compiled script (e.g. after a mail-server hiccup). */
export async function retryFilterSync(mailboxAddress: string): Promise<Result<{ sync: SyncStatus }>> {
  try {
    const { user, cred } = await resolveMailbox(mailboxAddress);
    const limited = gate(`mail:filters:sync:${user.id}`, 10);
    if (limited) return { ok: false, error: limited };
    return { ok: true, sync: await syncMailboxFilters(cred, { actorId: user.id }) };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

// ---------------------------------------------------------------------------
// Block / allow lists
// ---------------------------------------------------------------------------

export async function addSenderEntry(mailboxAddress: string, kind: SenderListKind, input: string): Promise<Result<{ pattern: string; sync: SyncStatus }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const limited = gate(`mail:filters:${user.id}`);
    if (limited) return { ok: false, error: limited };
    if (kind !== "block" && kind !== "allow") return { ok: false, error: "Unknown list." };
    const pattern = normaliseSenderPattern(input);
    if (!pattern) return { ok: false, error: "Enter an email address or a domain (example.com)." };
    const a = address.toLowerCase();
    if (kind === "block" && (pattern === a || pattern === `@${a.split("@")[1]}`)) return { ok: false, error: "You can't block your own address or domain." };
    const count = await db.mailFilterSender.count({ where: { mailboxAddress: a } });
    if (count >= MAX_SENDER_ENTRIES) return { ok: false, error: `Up to ${MAX_SENDER_ENTRIES} block/allow entries per mailbox.` };
    // An address can't be both blocked and allowed — the newer choice wins.
    await db.mailFilterSender.deleteMany({ where: { mailboxAddress: a, pattern, kind: kind === "block" ? "allow" : "block" } });
    await db.mailFilterSender.upsert({
      where: { mailboxAddress_kind_pattern: { mailboxAddress: a, kind, pattern } },
      update: {},
      create: { mailboxAddress: a, kind, pattern, createdById: user.id },
    });
    const sync = await syncMailboxFilters(cred, { actorId: user.id });
    await audit(user.id, kind === "block" ? "mailbox.blockSender" : "mail.filter.allowSender", `${a} ${kind} ${pattern} sync=${sync.state}`);
    return { ok: true, pattern, sync };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

export async function removeSenderEntry(mailboxAddress: string, id: string): Promise<Result<{ sync: SyncStatus }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const a = address.toLowerCase();
    const row = await db.mailFilterSender.findFirst({ where: { id, mailboxAddress: a } });
    if (row) await db.mailFilterSender.delete({ where: { id: row.id } });
    const sync = await syncMailboxFilters(cred, { actorId: user.id });
    if (row) await audit(user.id, "mail.filter.removeSender", `${a} ${row.kind} ${row.pattern}`);
    return { ok: true, sync };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

// ---------------------------------------------------------------------------
// Evaluate against existing mail (preview + "apply now")
// ---------------------------------------------------------------------------

type Scanned = { uid: number; summary: MessageSummary; msg: EvalMessage };

/** Fetch the newest `limit` messages of a folder with enough content to evaluate rules. */
async function scanFolder(client: ImapFlow, folder: string, limit: number): Promise<Scanned[]> {
  const found = await client.search({ all: true }, { uid: true });
  const uids = (Array.isArray(found) ? found : []).sort((x, y) => y - x).slice(0, limit);
  if (uids.length === 0) return [];
  const out: Scanned[] = [];
  for await (const m of client.fetch(
    uids,
    { uid: true, envelope: true, flags: true, internalDate: true, source: { start: 0, maxLength: 96 * 1024 } },
    { uid: true },
  )) {
    if (!m.source) continue;
    const parsed = await parseMessage(m.source).catch(() => null);
    if (!parsed) continue;
    const flags = readFlags(m.flags);
    out.push({
      uid: m.uid,
      summary: {
        uid: m.uid,
        folder,
        from: toMailAddress(m.envelope?.from?.[0]),
        to: toMailAddresses(m.envelope?.to),
        subject: m.envelope?.subject || parsed.subject || "(no subject)",
        preview: "",
        date: isoDate(m),
        seen: flags.seen,
        flagged: flags.flagged,
        answered: flags.answered,
        hasAttachments: false,
        keywords: readKeywords(m.flags),
      },
      msg: toEvalMessage(parsed as never),
    });
  }
  return out.sort((x, y) => y.uid - x.uid);
}

/** How many of the newest inbox messages would this (unsaved) rule match? */
export async function previewFilterRule(
  mailboxAddress: string,
  input: FilterRuleInput,
): Promise<Result<{ scanned: number; count: number; samples: MessageSummary[] }>> {
  try {
    const { user, cred } = await resolveMailbox(mailboxAddress);
    const limited = gate(`mail:filters:preview:${user.id}`, 20);
    if (limited) return { ok: false, error: limited };
    const parsed = parseRule(input);
    if (!parsed.ok) return parsed;
    const scanned = await withMailbox(cred, "INBOX", (client) => scanFolder(client, "INBOX", 300), { readOnly: true });
    const hits = scanned.filter((s) => ruleMatches(parsed.rule, s.msg));
    return { ok: true, scanned: scanned.length, count: hits.length, samples: hits.slice(0, 15).map((h) => h.summary) };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

/**
 * Run ONE saved rule over the newest inbox messages right now (Sieve only sees
 * new deliveries). Moves/flags exactly as the server would; FORWARDING IS NOT
 * replayed here — re-sending old mail to a third party is never what "apply to
 * existing mail" should do.
 */
export async function applyFilterRuleNow(
  mailboxAddress: string,
  ruleId: string,
): Promise<Result<{ scanned: number; matched: number; moved: number; flagged: number; skippedForwards: number }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const limited = gate(`mail:filters:apply:${user.id}`, 10);
    if (limited) return { ok: false, error: limited };
    const a = address.toLowerCase();
    const state = await loadFilterState(a);
    const rule = state.rules.find((r) => r.id === ruleId);
    if (!rule) return { ok: false, error: "That rule no longer exists." };
    await ensureRuleFolders(cred, [rule]);
    const roles = await resolveRoleFolders(cred);
    const one: FilterRule = {
      ...rule,
      enabled: true,
      actions: rule.actions.map((x) => (x.type === "move" && x.folder ? { ...x, folder: toServerPath(x.folder, roles.delimiter) } : x)),
    };
    const res = await withMailbox(cred, "INBOX", async (client) => {
      const scanned = await scanFolder(client, "INBOX", 500);
      let matched = 0;
      let moved = 0;
      let flagged = 0;
      let skippedForwards = 0;
      // Group by outcome so each distinct (flags, folder) is one STORE + one MOVE.
      const groups = new Map<string, { flags: string[]; folder: string | null; uids: number[] }>();
      for (const s of scanned) {
        const r = evaluateFilters({ rules: [one], senders: [], roles, msg: s.msg });
        if (r.matched.length === 0) continue;
        matched++;
        skippedForwards += r.forwards.length;
        const key = JSON.stringify([r.flags, r.folder]);
        const g = groups.get(key) ?? { flags: r.flags, folder: r.folder, uids: [] };
        g.uids.push(s.uid);
        groups.set(key, g);
      }
      for (const g of groups.values()) {
        const set = g.uids.join(",");
        if (g.flags.length) {
          await client.messageFlagsAdd(set, g.flags, { uid: true });
          flagged += g.uids.length;
        }
        if (g.folder && g.folder !== "INBOX") {
          await client.messageMove(set, g.folder, { uid: true });
          moved += g.uids.length;
        }
      }
      return { scanned: scanned.length, matched, moved, flagged, skippedForwards };
    });
    if (res.moved) await db.mailFilterRule.update({ where: { id: rule.id }, data: { appliedCount: { increment: res.moved } } }).catch(() => {});
    await audit(user.id, "mail.filter.applyNow", `${a}: ${rule.name} matched=${res.matched} moved=${res.moved}`);
    return { ok: true, ...res };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

// ---------------------------------------------------------------------------
// Spam / filter review queue
// ---------------------------------------------------------------------------

export type ReviewItem = MessageSummary & { reason: "filtered" | "spam" };

/**
 * What was filtered away recently: messages our rules/blocklist tagged with
 * `$NxFiltered` (any folder), plus everything in Junk from the last 30 days
 * (Rspamd's verdicts land there without our tag).
 */
export async function listFilteredMail(mailboxAddress: string): Promise<Result<{ items: ReviewItem[]; folders: string[] }>> {
  try {
    const { cred } = await resolveMailbox(mailboxAddress);
    const since = new Date(Date.now() - 30 * 24 * 3600 * 1000);
    const items = await withImap(cred, async (client) => {
      const list = await client.list();
      const targets = list.filter((f) => !f.flags?.has("\\Noselect") && folderRole(f.path, f.specialUse) !== "inbox" && folderRole(f.path, f.specialUse) !== "sent" && folderRole(f.path, f.specialUse) !== "drafts");
      const out: ReviewItem[] = [];
      for (const f of targets) {
        const isJunk = folderRole(f.path, f.specialUse) === "junk";
        const lock = await client.getMailboxLock(f.path, { readOnly: true });
        try {
          const found = await client.search(isJunk ? { since } : { keyword: FILTERED_KEYWORD, since }, { uid: true });
          const uids = (Array.isArray(found) ? found : []).sort((x, y) => y - x).slice(0, 60);
          if (!uids.length) continue;
          for await (const m of client.fetch(uids, { uid: true, envelope: true, flags: true, internalDate: true }, { uid: true })) {
            const flags = readFlags(m.flags);
            const kw = readKeywords(m.flags);
            out.push({
              uid: m.uid,
              folder: f.path,
              from: toMailAddress(m.envelope?.from?.[0]),
              to: toMailAddresses(m.envelope?.to),
              subject: m.envelope?.subject || "(no subject)",
              preview: "",
              date: isoDate(m),
              seen: flags.seen,
              flagged: flags.flagged,
              answered: flags.answered,
              hasAttachments: false,
              keywords: kw,
              reason: kw.includes(FILTERED_KEYWORD) ? "filtered" : "spam",
            });
          }
        } finally {
          lock.release();
        }
      }
      return out.sort((x, y) => (x.date < y.date ? 1 : -1)).slice(0, 200);
    });
    return { ok: true, items, folders: [...new Set(items.map((i) => i.folder))] };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

/** Move a filtered message back to the inbox; optionally never filter that sender again. */
export async function restoreFilteredMail(
  mailboxAddress: string,
  folder: string,
  uid: number,
  opts?: { neverFilter?: boolean; sender?: string },
): Promise<Result<{ sync?: SyncStatus }>> {
  try {
    const { user, cred, address } = await resolveMailbox(mailboxAddress);
    const limited = gate(`mail:filters:${user.id}`);
    if (limited) return { ok: false, error: limited };
    await withImap(cred, async (client) => {
      const list = await client.list();
      const inbox = list.find((f) => folderRole(f.path, f.specialUse) === "inbox")?.path ?? "INBOX";
      if (folder === inbox) return;
      const lock = await client.getMailboxLock(folder);
      try {
        await client.messageFlagsRemove(String(uid), [FILTERED_KEYWORD], { uid: true }).catch(() => {});
        await client.messageMove(String(uid), inbox, { uid: true });
      } finally {
        lock.release();
      }
    });
    let sync: SyncStatus | undefined;
    if (opts?.neverFilter && opts.sender) {
      const r = await addSenderEntry(address, "allow", opts.sender);
      if (r.ok) sync = r.sync;
    }
    await audit(user.id, "mail.filter.restore", `${address.toLowerCase()} ${folder}#${uid}${opts?.neverFilter ? ` +allow ${opts.sender}` : ""}`);
    return { ok: true, sync };
  } catch (e) {
    return { ok: false, error: errMsg(e) };
  }
}

// ---------------------------------------------------------------------------
// Per-user mail preferences
// ---------------------------------------------------------------------------

export type MailPrefs = { lastMailbox: string | null; notifyNewMail: boolean };

export async function getMailPrefs(): Promise<MailPrefs> {
  const user = await requireUser();
  const row = await db.mailUserPref.findUnique({ where: { userId: user.id } }).catch(() => null);
  return { lastMailbox: row?.lastMailbox ?? null, notifyNewMail: row?.notifyNewMail ?? false };
}

/**
 * Remember the mailbox this user last opened. Only stored after resolveMailbox
 * proves the user may open it, so the remembered value can never point a later
 * page render at a mailbox they were not allowed into.
 */
export async function rememberMailbox(mailboxAddress: string): Promise<{ ok: boolean }> {
  try {
    const { user, address } = await resolveMailbox(mailboxAddress);
    const a = address.toLowerCase();
    await db.mailUserPref.upsert({ where: { userId: user.id }, update: { lastMailbox: a }, create: { userId: user.id, lastMailbox: a } });
    return { ok: true };
  } catch {
    return { ok: false };
  }
}

export async function setNotifyNewMail(enabled: boolean): Promise<{ ok: boolean }> {
  const user = await requireUser();
  await db.mailUserPref.upsert({
    where: { userId: user.id },
    update: { notifyNewMail: Boolean(enabled) },
    create: { userId: user.id, notifyNewMail: Boolean(enabled) },
  });
  return { ok: true };
}

