import { NextRequest, NextResponse } from "next/server";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import {
  listFolders,
  listMessages,
  getMessage,
  getMailboxes,
  sendMessage,
  setFlag,
  moveMessage,
  deleteMessage,
  markSpam,
  markNotSpam,
  blockSender,
  bulkSetFlag,
  bulkMove,
  bulkDelete,
  createFolder,
  renameFolder,
  deleteFolder,
  listMailboxUnread,
} from "@/lib/actions-mail";
import { listCompanyMailboxInfos } from "@/lib/actions-company-mail";
import { rememberMailbox, getMailPrefs, setNotifyNewMail } from "@/lib/actions-mail-filters";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/mail/rpc  { op, args } → { ok: true, data } | { ok: false, error, code }
 *
 * WHY THIS EXISTS — the webmail used to call these as Server Actions, and two
 * properties of Server Actions were behind the "can't open emails / wrong
 * mailbox / Sent looks stale" reports in the admin inbox (a tab the owner keeps
 * open all day):
 *
 *  1. Action IDs change on every build. After any deploy, an open tab's calls
 *     fail with "Failed to find Server Action" (hundreds of these in the prod
 *     journal) — so Refresh, polling, switching mailbox and opening a message
 *     ALL silently stopped working until a hard reload, leaving yesterday's
 *     list on screen. This URL never changes between builds.
 *  2. The client runs Server Actions one at a time. Opening a message queued
 *     behind a slow list load / poll / the contact panel's sender search, which
 *     reads as "opening hangs". Plain fetches run in parallel.
 *
 * SECURITY: identical surface to the Server Actions it fronts — every op
 * authenticates and authorises itself (resolveMailbox / requireUser /
 * requireAnyGrant), rate limits included. On top of that, POST + JSON only and
 * a same-origin check, so a cross-site page can't drive it with the session
 * cookie (which is SameSite=Lax anyway).
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyFn = (...args: any[]) => Promise<unknown>;

const OPS: Record<string, AnyFn> = {
  listFolders,
  listMessages,
  getMessage,
  getMailboxes,
  sendMessage,
  setFlag,
  moveMessage,
  deleteMessage,
  markSpam,
  markNotSpam,
  blockSender,
  bulkSetFlag,
  bulkMove,
  bulkDelete,
  createFolder,
  renameFolder,
  deleteFolder,
  listMailboxUnread,
  listCompanyMailboxInfos,
  rememberMailbox,
  getMailPrefs,
  setNotifyNewMail,
};

const BUILD = process.env.BUILD_TIME ?? "dev";

function json(body: unknown, status = 200) {
  return NextResponse.json(body, { status, headers: { ...NO_STORE_HEADERS, "x-nxeon-build": BUILD } });
}

function sameOrigin(req: NextRequest): boolean {
  const origin = req.headers.get("origin");
  if (!origin) return true; // same-origin fetch from older browsers; cookie is SameSite=Lax regardless
  try {
    const host = (req.headers.get("x-forwarded-host") ?? req.headers.get("host") ?? "").toLowerCase();
    return new URL(origin).host.toLowerCase() === host;
  } catch {
    return false;
  }
}

export async function POST(req: NextRequest) {
  if (!sameOrigin(req)) return json({ ok: false, error: "Cross-origin request refused.", code: "forbidden" }, 403);
  if (!(req.headers.get("content-type") ?? "").toLowerCase().startsWith("application/json")) {
    return json({ ok: false, error: "Expected JSON.", code: "bad_request" }, 415);
  }
  let body: { op?: unknown; args?: unknown };
  try {
    body = await req.json();
  } catch {
    return json({ ok: false, error: "Malformed request.", code: "bad_request" }, 400);
  }
  const op = typeof body.op === "string" ? body.op : "";
  const fn = Object.prototype.hasOwnProperty.call(OPS, op) ? OPS[op] : undefined;
  const args = Array.isArray(body.args) ? body.args : [];
  if (!fn || args.length > 6) return json({ ok: false, error: "Unknown mail operation.", code: "bad_request" }, 400);

  try {
    const data = await fn(...args);
    return json({ ok: true, data: data ?? null });
  } catch (e) {
    const err = e as Error & { digest?: string };
    const msg = String(err?.message ?? e);
    if (msg === "UNAUTHORIZED" || err?.digest?.startsWith("NEXT_REDIRECT")) {
      return json({ ok: false, error: "Your session has expired — sign in again.", code: "auth" }, 401);
    }
    if (msg === "FORBIDDEN") return json({ ok: false, error: "You don't have access to that mailbox.", code: "forbidden" }, 403);
    // Messages thrown by the mail actions are written for users (rate limits,
    // "message not found", IMAP errors trimmed); never a stack.
    return json({ ok: false, error: msg.replace(/\s+/g, " ").slice(0, 300), code: "mail" }, 200);
  }
}

