"use client";

// Browser-side transport for the webmail. Same function names and signatures
// as the Server Actions in lib/actions-mail.ts, but each call is a plain
// `fetch` to /api/mail/rpc — see that route for why (stable across deploys,
// runs in parallel instead of queueing behind other actions).
//
// Types only are imported from the server modules (erased at build time), so
// nothing server-side is bundled into the client.

import type * as Mail from "@/lib/actions-mail";
import type * as Company from "@/lib/actions-company-mail";
import type * as Filters from "@/lib/actions-mail-filters";

export class MailApiError extends Error {
  code: string;
  constructor(message: string, code = "mail") {
    super(message);
    this.code = code;
  }
}

/** The build this bundle came from (inlined by next.config `env`). */
export const CLIENT_BUILD = process.env.BUILD_TIME ?? "dev";

/** Fired on window when the server reports a different build than this tab's. */
export const MAIL_STALE_BUILD_EVENT = "nxeon:mail-stale-build";

let staleNotified = false;

