  { keys: ["/"], label: "Focus search" },
  { keys: ["Esc"], label: "Close message / composer" },
  { keys: ["?"], label: "Show this help" },
];

export function ShortcutHelp({ onClose }: { onClose: () => void }) {
  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center bg-navy-950/70 p-4 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-label="Keyboard shortcuts"
      onClick={onClose}
    >
      <div
        className="glass w-full max-w-md overflow-hidden shadow-2xl animate-fade-up"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
          <h3 className="text-sm font-semibold text-white">Keyboard shortcuts</h3>
          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
            <Icon.close size={16} />
          </button>

const PROMO_RE = /(newsletter|deal|sale|% off|unsubscribe|promo|offer|coupon|discount|marketing|no-?reply|noreply|billing|receipt|invoice|order)/i;
const SOCIAL_DOMAINS = /(facebook|instagram|twitter|x\.com|linkedin|github|reddit|discord|slack|notifications?|youtube|tiktok|pinterest|medium)/i;

export function categoryOf(from: MailAddress, subject: string): MailTab {
  const hay = `${from.address} ${from.name ?? ""} ${subject}`;
  if (SOCIAL_DOMAINS.test(from.address) || SOCIAL_DOMAINS.test(from.name ?? "")) return "social";
  if (PROMO_RE.test(hay)) return "promotions";
  return "primary";
}

