"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import type {
  MailFolder,
  MailboxInfo,
  MailboxUnread,
  ListResult,
  MessageSummary,
  MessageFull,
  SendPayload,
} from "@/lib/mail/types";
// Data goes through /api/mail/rpc (see mail-api.ts): stable across deploys and
// not serialised behind other Server Actions. Settings stay a Server Action.
import {
  listFolders,
  listMessages,
  getMessage,
  getMailboxes,
  sendMessage,
  setFlag,
  moveMessage,
  deleteMessage,
  markSpam,
  markNotSpam,
  blockSender,
  bulkSetFlag,
  bulkMove,
  bulkDelete,
  createFolder,
  renameFolder,
  deleteFolder,
  listMailboxUnread,
  rememberMailbox,
  setNotifyNewMail,
  MAIL_STALE_BUILD_EVENT,
} from "./mail-api";
import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
import { FolderRail, MiniRail, type RailItem } from "./FolderRail";
import { MessageList, type BulkAction } from "./MessageList";
import { ReadingPane } from "./ReadingPane";
import { ContactPanel } from "./ContactPanel";
import { useCompose, MAIL_SENT_EVENT } from "./ComposeProvider";
import { MailSettings } from "./MailSettings";
import { ShortcutHelp } from "./ShortcutHelp";
import { FolderDialog, type FolderDialogState } from "./FolderDialog";
import { Icon, displayName, categoryOf, type MailTab } from "./util";

const STARRED = "__starred__";
const SNOOZED = "__snoozed__";

// Remembers the last mailbox the user picked so it stays the default across
// reloads and re-logins. The company inbox ALSO stores it server-side
// (MailUserPref, via rememberMailbox) so it survives a new browser/device; this
// key is the fallback. We only ever restore an address that is still in the
// user's own mailbox list.
const SELECTED_MAILBOX_KEY = "nxeon.mail.selectedMailbox";
const NOTIFY_KEY = "nxeon.mail.notify";

const LIST_POLL_MS = 45_000;
const UNREAD_POLL_MS = 30_000;

/** Per-mailbox signature config used when composing. */
type SigConfig = {
  enabled: boolean;
  onReply: boolean;
  placement: "above" | "below";
  plain: string; // plain-text fallback / derived text part
  html: string; // sanitized rich-signature HTML
};

type Toast = { text: string; tone: "info" | "error"; action?: { label: string; run: () => void } };

const ROLE_META: Record<string, { label: string; icon: RailItem["icon"]; order: number }> = {
  inbox: { label: "Inbox", icon: "inbox", order: 0 },
  sent: { label: "Sent", icon: "sent", order: 3 },
  drafts: { label: "Drafts", icon: "draft", order: 4 },
  junk: { label: "Spam", icon: "spam", order: 5 },
  trash: { label: "Trash", icon: "trash", order: 6 },
  archive: { label: "Archive", icon: "archive", order: 7 },
};

const errText = (e: unknown, fallback: string) => {
  const m = e instanceof Error ? e.message : "";
  return m && m.length < 240 ? m : fallback;
};

export function MailClient({
  initialFolders,
  initialMailboxes,
  initialList,
  initialFolderPath,
  initialSignature = "",
  initialActiveAddress,
  loadMailboxes = getMailboxes,
  variant = "customer",
  filtersHref,
  initialUnread,
  initialNotify = false,
  titleBase,
}: {
  initialFolders: MailFolder[];
  initialMailboxes: MailboxInfo[];
  initialList: ListResult;
  initialFolderPath: string;
  initialSignature?: string;
  /**
   * How the switcher (re)loads the mailbox list. Defaults to the customer's own
   * mailboxes (`getMailboxes`); the admin company-inbox passes a company-scoped
   * loader so the two lists never bleed into each other.
   */
  loadMailboxes?: () => Promise<MailboxInfo[]>;
  /**
   * Mailbox the server already loaded folders and messages for. It MUST match
   * what the server rendered: seeding this from anything else would show one
   * mailbox's messages under another mailbox's name until the first refetch.
   */
  initialActiveAddress?: string;
  /** "company" = the admin/staff company inbox: per-mailbox unread badges, document title, notifications, folder management, server-side remembered mailbox. */
  variant?: "customer" | "company";
  /** Where "Filters" in the rail (and "Filter messages like this") lead. Omitted = Filters stays hidden. */
  filtersHref?: string;
  initialUnread?: MailboxUnread[];
  initialNotify?: boolean;
  /** Document title suffix, e.g. "Inbox — Nxeon admin". Only used by the company variant. */
  titleBase?: string;
}) {
  const router = useRouter();
  const isCompany = variant === "company";
  const [folders, setFolders] = useState<MailFolder[]>(initialFolders);
  const [mailboxes, setMailboxes] = useState<MailboxInfo[]>(initialMailboxes);
  const [activeAddress, setActiveAddress] = useState<string | undefined>(
    initialActiveAddress ?? initialMailboxes[0]?.address,
  );
  const [selected, setSelected] = useState<string>(initialFolderPath);
  const [list, setList] = useState<ListResult>(initialList);
  const [page, setPage] = useState(1);
  const [tab, setTab] = useState<MailTab>("primary");
  const [search, setSearch] = useState("");
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [updatedAt, setUpdatedAt] = useState<number>(() => Date.now());

  const [switching, setSwitching] = useState<string | null>(null);

  const [selectedUid, setSelectedUid] = useState<number | null>(null);
  const [cursorUid, setCursorUid] = useState<number | null>(null);
  const [message, setMessage] = useState<MessageFull | null>(null);
  const [msgLoading, setMsgLoading] = useState(false);
  const [msgError, setMsgError] = useState<{ summary: MessageSummary; error: string } | null>(null);
  const [checked, setChecked] = useState<Set<number>>(() => new Set());

  const [unread, setUnread] = useState<Record<string, MailboxUnread>>(() =>
    Object.fromEntries((initialUnread ?? []).map((u) => [u.address.toLowerCase(), u])),
  );
  const [notify, setNotify] = useState<boolean>(initialNotify);
  const [staleBuild, setStaleBuild] = useState(false);
  const [folderDialog, setFolderDialog] = useState<FolderDialogState | null>(null);

  // The composer lives at the shell level (ComposeProvider) so it stays mounted —
  // and its in-progress draft survives — across navigation to other dashboard
  // pages, and so `position: fixed` resolves to the real viewport. We drive it
  // purely through this context instead of rendering <Composer> inline.
  const compose = useCompose();
  const [sig, setSig] = useState<SigConfig>({
    enabled: true,
    onReply: true,
    placement: "below",
    plain: initialSignature,
    html: "",
  });
  const [showSettings, setShowSettings] = useState(false);
  const [mobilePane, setMobilePane] = useState<"list" | "read">("list");
  const [railOpen, setRailOpen] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [toast, setToastState] = useState<Toast | null>(null);
  const [showHelp, setShowHelp] = useState(false);

  const setToast = useCallback((text: string | null, tone: Toast["tone"] = "info", action?: Toast["action"]) => {
    setToastState(text ? { text, tone, action } : null);
  }, []);

  /* ---- Request bookkeeping ---------------------------------------------
   * Every list/message/switch request takes a ticket. A response is applied
   * ONLY if its ticket is still the latest one AND the view it was asked for
   * is still the view on screen. This is what keeps a slow response for
   * santino@ from landing on screen after you switched to contact@ (and a
   * message from one mailbox from opening under another's name).
   */
  const listTicket = useRef(0);
  const msgTicket = useRef(0);
  const switchTicket = useRef(0);
  const view = useRef({ address: activeAddress, key: initialFolderPath, page: 1, q: "" });
  /** The mailbox the CURRENT list belongs to — message actions always use this. */
  const listAddress = useRef<string | undefined>(activeAddress);

  // Collapsible panels — desktop only, persisted so the layout choice sticks.
  const [railCollapsed, setRailCollapsed] = useState(false);
  const [contactCollapsed, setContactCollapsed] = useState(false);
  useEffect(() => {
    try {
      if (localStorage.getItem("nxeon.mail.railCollapsed") === "1") setRailCollapsed(true);
      if (localStorage.getItem("nxeon.mail.contactCollapsed") === "1") setContactCollapsed(true);
    } catch {}
  }, []);
  const toggleRail = useCallback(() => {
    setRailCollapsed((v) => {
      const next = !v;
      try { localStorage.setItem("nxeon.mail.railCollapsed", next ? "1" : "0"); } catch {}
      return next;
    });
  }, []);
  const toggleContact = useCallback(() => {
    setContactCollapsed((v) => {
      const next = !v;
      try { localStorage.setItem("nxeon.mail.contactCollapsed", next ? "1" : "0"); } catch {}
      return next;
    });
  }, []);

  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const mailbox = mailboxes.find((m) => m.address === activeAddress) ?? mailboxes[0] ?? null;

  /* ---- Signature config (loaded per active mailbox) --------------------- */
  const loadSig = useCallback((addr?: string) => {
    getMailboxSettings(addr)
      .then((s) =>
        setSig({
          enabled: s.signatureEnabled,
          onReply: s.signatureOnReply,
          placement: s.signaturePlacement,
          plain: s.signature,
          html: s.signatureHtml,
        }),
      )
      .catch(() => {});
  }, []);

  useEffect(() => {
    loadSig(activeAddress);
  }, [activeAddress, loadSig]);

  /** Signature fields to spread into a compose draft, honouring the toggles. */
  const sigFields = useCallback(
    (isReply: boolean) => {
      if (!sig.enabled) return {};
      if (isReply && !sig.onReply) return {};
      return {
        signature: sig.plain || undefined,
        signatureHtml: sig.html || undefined,
        signaturePlacement: sig.placement,
      };
    },
    [sig],
  );

  const inboxPath = folders.find((f) => f.role === "inbox")?.path ?? "INBOX";
  const archivePath = folders.find((f) => f.role === "archive")?.path;
  const trashPath = folders.find((f) => f.role === "trash")?.path;
  const junkPath = folders.find((f) => f.role === "junk")?.path;

  /* ---- Rail model ------------------------------------------------------- */
  const byRole = (role: string) => folders.find((f) => f.role === role);
  const primaryItems: RailItem[] = [];
  const inbox = byRole("inbox");
  primaryItems.push({ key: inbox?.path ?? "INBOX", label: "Inbox", icon: "inbox", unread: inbox?.unread });
  primaryItems.push({ key: STARRED, label: "Starred", icon: "star", virtual: true });
  primaryItems.push({ key: SNOOZED, label: "Snoozed", icon: "clock", virtual: true });
  for (const role of ["sent", "drafts", "junk", "trash", "archive"] as const) {
    const f = byRole(role);
    const meta = ROLE_META[role];
    if (f) primaryItems.push({ key: f.path, label: meta.label, icon: meta.icon, unread: f.unread });
    else primaryItems.push({ key: `__missing_${role}`, label: meta.label, icon: meta.icon });
  }
  const customItems: RailItem[] = folders
    .filter((f) => f.role === "custom")
    .map((f) => ({ key: f.path, label: f.name, icon: "folder" as const, unread: f.unread }));

  const labelFor = useCallback(
    (key: string): string => {
      if (key === STARRED) return "Starred";
      if (key === SNOOZED) return "Snoozed";
      const f = folders.find((x) => x.path === key);
      if (f) return ROLE_META[f.role]?.label ?? f.name;
      return "Mailbox";
    },
    [folders],
  );

  const resolvePath = useCallback(
    (key: string, inbox = inboxPath): string | null => {
      if (key === SNOOZED) return null;
      if (key === STARRED) return inbox;
      if (key.startsWith("__missing_")) return null;
      return key;
    },
    [inboxPath],
  );

  const shape = (key: string, res: ListResult, addr?: string): ListResult => {
    const messages = res.messages.map((m) => ({ ...m, mailbox: addr }));
    if (key === STARRED) {
      const flagged = messages.filter((m) => m.flagged);
      return { messages: flagged, total: flagged.length, page: 1, pageSize: res.pageSize };
    }
    return { ...res, messages };
  };

  /* ---- Loading ---------------------------------------------------------- */
  const loadList = useCallback(
    async (key: string, pageNum: number, q: string, addr = activeAddress, opts: { quiet?: boolean } = {}) => {
      const path = resolvePath(key);
      const ticket = ++listTicket.current;
      view.current = { address: addr, key, page: pageNum, q };
      if (path === null) {
        setList({ messages: [], total: 0, page: 1, pageSize: initialList.pageSize });
        setListError(null);
        setListLoading(false);
        return;
      }
      if (!opts.quiet) setListLoading(true);
      setListError(null);
      try {
        const res = await listMessages(path, key === STARRED ? 1 : pageNum, q || undefined, addr);
        if (ticket !== listTicket.current) return;
        listAddress.current = addr;
        setList(shape(key, res, addr));
        setUpdatedAt(Date.now());
      } catch (e) {
        if (ticket !== listTicket.current) return;
        setListError(errText(e, "Couldn't load messages."));
      } finally {
        if (ticket === listTicket.current) setListLoading(false);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [activeAddress, resolvePath, initialList.pageSize],
  );

  const clearReading = () => {
    msgTicket.current++;
    setSelectedUid(null);
    setCursorUid(null);
    setMessage(null);
    setMsgError(null);
    setMsgLoading(false);
    setMobilePane("list");
  };

  const selectFolder = (key: string) => {
    setSelected(key);
    setPage(1);
    setRailOpen(false);
    setChecked(new Set());
    clearReading();
    void loadList(key, 1, search);
  };

  /* ---- Unread counts (company inbox) ------------------------------------ */
  const prevUidNext = useRef<Record<string, number | null>>(
    Object.fromEntries((initialUnread ?? []).map((u) => [u.address.toLowerCase(), u.uidNext])),
  );
  const notifyRef = useRef(notify);
  notifyRef.current = notify;

  const pollUnread = useCallback(async () => {
    if (!isCompany || mailboxes.length === 0) return;
    try {
      const rows = await listMailboxUnread(mailboxes.map((m) => m.address));
      const next: Record<string, MailboxUnread> = {};
      const arrivals: { address: string; count: number }[] = [];
      for (const r of rows) {
        const key = r.address.toLowerCase();
        next[key] = r;
        const prev = prevUidNext.current[key];
        if (prev != null && r.uidNext != null && r.uidNext > prev) arrivals.push({ address: key, count: r.uidNext - prev });
        if (r.uidNext != null) prevUidNext.current[key] = r.uidNext;
      }
      setUnread(next);
      if (arrivals.length) {
        // New mail in the mailbox on screen: refresh the list quietly when the
        // user is looking at page 1 of the inbox with no search.
        const v = view.current;
        if (arrivals.some((a) => a.address === v.address?.toLowerCase()) && v.key === inboxPath && v.page === 1 && !v.q) {
          void loadList(v.key, 1, "", v.address, { quiet: true });
          void listFolders(v.address).then((f) => {
            if (view.current.address === v.address) setFolders(f);
          }).catch(() => {});
        }
        if (notifyRef.current && typeof Notification !== "undefined" && Notification.permission === "granted") {
          for (const a of arrivals) {
            try {
              const n = new Notification(`New mail in ${a.address}`, {
                body: a.count === 1 ? "1 new message" : `${a.count} new messages`,
                icon: "/icon-192.png",
                tag: `nxeon-mail-${a.address}`,
              });
              n.onclick = () => {
                window.focus();
                void switchMailboxRef.current(a.address);
              };
            } catch {
              /* notifications unsupported in this context */
            }
          }
        }
      }
    } catch {
      /* transient — next tick tries again */
    }
  }, [isCompany, mailboxes, inboxPath, loadList]);

  useEffect(() => {
    if (!isCompany) return;
    void pollUnread();
    const id = setInterval(() => {
      if (!document.hidden || notifyRef.current) void pollUnread();
    }, UNREAD_POLL_MS);
    return () => clearInterval(id);
  }, [isCompany, pollUnread]);

  // Document title: "(3) Inbox · santino@nxeon.cloud — …" — the total across
  // every mailbox, so a backgrounded tab still shows there is something to read.
  const totalUnread = Object.values(unread).reduce((s, u) => s + (u.unread || 0), 0);
  useEffect(() => {
    if (!isCompany) return;
    const base = `${labelFor(selected)} · ${activeAddress ?? ""}${titleBase ? ` — ${titleBase}` : ""}`;
    document.title = totalUnread > 0 ? `(${totalUnread > 999 ? "999+" : totalUnread}) ${base}` : base;
  }, [isCompany, totalUnread, selected, activeAddress, titleBase, labelFor]);

  const toggleNotify = async () => {
    const next = !notify;
    if (next && typeof Notification !== "undefined" && Notification.permission !== "granted") {
      const perm = await Notification.requestPermission().catch(() => "denied" as NotificationPermission);
      if (perm !== "granted") {
        setToast("Your browser blocked notifications for this site — allow them in the address bar, then try again.", "error");
        return;
      }
    }
    setNotify(next);
    try { localStorage.setItem(NOTIFY_KEY, next ? "1" : "0"); } catch {}
    void setNotifyNewMail(next).catch(() => {});
    setToast(next ? "Desktop notifications on for new mail." : "Desktop notifications off.");
  };

  /* ---- Mailbox switching ------------------------------------------------ *
   * Atomic: nothing about the visible mailbox changes until the NEW mailbox's
   * folders and first page have both loaded. The old code set the active
   * address first and loaded after, so any failure (a stale tab after a deploy,
   * an IMAP timeout) left contact@'s name over santino@'s messages — and every
   * click then asked contact@ for one of santino@'s UIDs ("Message not found").
   */
  const switchMailbox = async (address: string) => {
    if (address === activeAddress && !switching) return;
    const ticket = ++switchTicket.current;
    setSwitching(address);
    setRailOpen(false);
    try {
      const f = await listFolders(address);
      const newInbox = f.find((x) => x.role === "inbox")?.path ?? f[0]?.path ?? "INBOX";
      const res = await listMessages(newInbox, 1, undefined, address);
      if (ticket !== switchTicket.current) return;
      // Commit everything at once and invalidate anything still in flight for
      // the previous mailbox.
      listTicket.current++;
      msgTicket.current++;
      view.current = { address, key: newInbox, page: 1, q: "" };
      listAddress.current = address;
      setActiveAddress(address);
      setFolders(f);
      setSelected(newInbox);
      setPage(1);
      setSearch("");
      setChecked(new Set());
      setList(shape(newInbox, res, address));
      setListError(null);
      setUpdatedAt(Date.now());
      setSelectedUid(null);
      setCursorUid(null);
      setMessage(null);
      setMsgError(null);
      setMsgLoading(false);
      setMobilePane("list");
      try { localStorage.setItem(SELECTED_MAILBOX_KEY, address); } catch {}
      if (isCompany) void rememberMailbox(address).catch(() => {});
      void loadMailboxes()
        .then((mb) => setMailboxes(Array.isArray(mb) ? mb : mb ? [mb] : []))
        .catch(() => {});
    } catch (e) {
      if (ticket !== switchTicket.current) return;
      setToast(`Couldn't open ${address}: ${errText(e, "the mail server didn't answer")}`, "error", {
        label: "Retry",
        run: () => void switchMailboxRef.current(address),
      });
    } finally {
      if (ticket === switchTicket.current) setSwitching(null);
    }
  };
  const switchMailboxRef = useRef(switchMailbox);
  switchMailboxRef.current = switchMailbox;

  // Restore the last-used mailbox on mount (localStorage fallback; the company
  // inbox's server render already honoured the server-side preference). A
  // server deep-link (`?mailbox=`) always wins and is remembered as the new
  // default; otherwise, if the stored address still belongs to this user,
  // switch to it — never select a mailbox the user no longer has.
  const restoredRef = useRef(false);
  useEffect(() => {
    if (restoredRef.current) return;
    restoredRef.current = true;
    try {
      if (isCompany && localStorage.getItem(NOTIFY_KEY) === "1" && !initialNotify) setNotify(true);
    } catch {}
    if (initialActiveAddress) {
      try { localStorage.setItem(SELECTED_MAILBOX_KEY, initialActiveAddress); } catch {}
      return;
    }
    let stored: string | null = null;
    try { stored = localStorage.getItem(SELECTED_MAILBOX_KEY); } catch {}
    if (stored && stored !== activeAddress && mailboxes.some((m) => m.address === stored)) {
      void switchMailbox(stored);
    }
    // Mount-only: intentionally not re-run when these change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ---- Opening a message ------------------------------------------------ */
  const openMessage = (m: MessageSummary) => {
    const ticket = ++msgTicket.current;
    const addr = m.mailbox ?? listAddress.current ?? activeAddress;
    setSelectedUid(m.uid);
    setCursorUid(m.uid);
    setMobilePane("read");
    setMsgLoading(true);
    setMsgError(null);
    // Optimistically mark as read — getMessage sets \Seen server-side itself.
    if (!m.seen) {
      setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid && x.folder === m.folder ? { ...x, seen: true } : x)) }));
      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
      if (addr) {
        setUnread((cur) => {
          const k = addr.toLowerCase();
          const u = cur[k];
          return u && m.folder === inboxPath ? { ...cur, [k]: { ...u, unread: Math.max(0, u.unread - 1) } } : cur;
        });
      }
    }
    (async () => {
      try {
        const full = await getMessage(m.folder, m.uid, addr);
        if (ticket !== msgTicket.current) return;
        setMessage({ ...full, mailbox: addr });
      } catch (e) {
        if (ticket !== msgTicket.current) return;
        setMessage(null);
        setMsgError({ summary: m, error: errText(e, "Couldn't open this message.") });
      } finally {
        if (ticket === msgTicket.current) setMsgLoading(false);
      }
    })();
  };

  /* ---- Mutations -------------------------------------------------------- */
  const opAddr = () => listAddress.current ?? activeAddress;

  const toggleStar = (m: MessageSummary | MessageFull) => {
    const next = !m.flagged;
    setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, flagged: next } : x)) }));
    setMessage((cur) => (cur && cur.uid === m.uid ? { ...cur, flagged: next } : cur));
    if (selected === STARRED && !next) {
      // Un-starring inside the Starred view removes the row.
      setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
    }
    void setFlag(m.folder, m.uid, "flagged", next, opAddr()).catch((e) => setToast(errText(e, "Couldn't update star."), "error"));
  };

  const markUnread = (m: MessageSummary | MessageFull) => {
    setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, seen: false } : x)) }));
    setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: f.unread + 1 } : f)));
    clearReading();
    void setFlag(m.folder, m.uid, "seen", false, opAddr())
      .then(() => setToast("Marked as unread."))
      .catch((e) => setToast(errText(e, "Couldn't mark as unread."), "error"));
  };

  const removeFromList = (m: MessageSummary | MessageFull) => {
    setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
    // Keep folder unread counts honest when an unread message leaves the folder.
    if (!m.seen) {
      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
    }
    clearReading();
  };

  const reloadCurrent = () => void loadList(selected, page, search);

  const doArchive = () => {
    if (!message) return;
    const m = message;
    if (!archivePath || m.folder === archivePath) {
      setToast("No archive folder available.");
      return;
    }
    // The optimistic remove must be UNDONE if the server rejects — re-fetching
    // the current folder restores the true state.
    removeFromList(m);
    setToast("Message archived.");
    void moveMessage(m.folder, m.uid, archivePath, opAddr()).catch((e) => {
      setToast(`Couldn't archive that message — it's still in ${labelFor(m.folder)}. ${errText(e, "")}`.trim(), "error");
      reloadCurrent();
    });
  };

  const doDelete = () => {
    if (!message) return;
    const m = message;
    removeFromList(m);
    // If already in trash, hard-delete; otherwise move to trash when possible.
    if (trashPath && m.folder !== trashPath) {
      setToast("Moved to Trash.");
      void moveMessage(m.folder, m.uid, trashPath, opAddr()).catch((e) => {
        setToast(`Couldn't delete that message. ${errText(e, "")}`.trim(), "error");
        reloadCurrent();
      });
    } else {
      setToast("Message deleted.");
      void deleteMessage(m.folder, m.uid, opAddr()).catch((e) => {
        setToast(`Couldn't delete that message — it's back in the list. ${errText(e, "")}`.trim(), "error");
        reloadCurrent();
      });
    }
  };

  const doMove = (toFolder: string) => {
    if (!message) return;
    const m = message;
    removeFromList(m);
    setToast(`Moved to ${labelFor(toFolder)}.`);
    void moveMessage(m.folder, m.uid, toFolder, opAddr()).catch((e) => {
      setToast(`Couldn't move that message — it's still where it was. ${errText(e, "")}`.trim(), "error");
      reloadCurrent();
    });
  };

  // "Mark as spam" — optimistically drop the row and move it to Junk server-side.
  // The move is also what trains the spam filter when the mail host's antispam
  // hooks are enabled (see lib/actions-mail.ts) — nothing extra to do here.
  const doMarkSpam = () => {
    if (!message) return;
    const m = message;
    if (junkPath && m.folder === junkPath) return; // already spam
    removeFromList(m);
    setToast("Marked as spam.");
    void markSpam(m.folder, m.uid, opAddr()).catch((e) => {
      setToast(`Couldn't mark that as spam. ${errText(e, "")}`.trim(), "error");
      reloadCurrent();
    });
  };

  // "Not spam" (shown inside the Junk folder) — move back to the Inbox.
  const doMarkNotSpam = () => {
    if (!message) return;
    const m = message;
    removeFromList(m);
    setToast("Moved to Inbox.");
    void markNotSpam(m.folder, m.uid, opAddr()).catch((e) => {
      setToast(`Couldn't move that out of Spam. ${errText(e, "")}`.trim(), "error");
      reloadCurrent();
    });
  };

  // "Block sender" / "Block domain" — file FUTURE mail to Spam via the managed
  // Sieve filter. Does not remove the current message (Mark as spam does).
  const doBlock = (domain: boolean) => {
    if (!message) return;
    const sender = message.from.address;
    if (!sender) {
      setToast("This message has no sender address to block.");
      return;
    }
    const what = domain ? `@${sender.split("@")[1]}` : sender;
    setToast(`Blocking ${what}…`);
    void blockSender(sender, opAddr(), { domain })
      .then((res) => {
        if (res && res.ok === false) {
          setToast(res.error || "Couldn't block that sender.", "error");
          return;
        }
        setToast(`Blocked ${what}. Future mail from them goes to Spam.`);
      })
      .catch((e) => setToast(errText(e, "Couldn't block that sender. Try again in a moment."), "error"));
  };

  const createFilterFrom = () => {
    if (!message || !filtersHref) return;
    const qs = new URLSearchParams({ mailbox: opAddr() ?? "", new: "1", from: message.from.address, subject: message.subject });
    router.push(`${filtersHref}?${qs.toString()}`);
  };

  /* ---- Bulk actions ------------------------------------------------------ */
  const checkedMessages = list.messages.filter((m) => checked.has(m.uid));
  const toggleChecked = (uid: number) =>
    setChecked((cur) => {
      const next = new Set(cur);
      if (next.has(uid)) next.delete(uid);
      else next.add(uid);
      return next;
    });

  const runBulk = (action: BulkAction, toFolder?: string) => {
    const items = checkedMessages;
    if (items.length === 0) return;
    // Every visible message in a list comes from one folder (Starred = inbox).
    const folder = items[0].folder;
    const uids = items.map((m) => m.uid);
    const addr = opAddr();
    const n = items.length;
    const plural = `${n} message${n === 1 ? "" : "s"}`;
    const fail = (e: unknown) => {
      setToast(`That didn't work: ${errText(e, "the mail server refused")}. The list was reloaded.`, "error");
      reloadCurrent();
    };
    const removeAll = () => {
      const gone = new Set(uids);
      const unreadGone = items.filter((m) => !m.seen).length;
      setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => !gone.has(x.uid)), total: Math.max(0, cur.total - n) }));
      if (unreadGone) setFolders((cur) => cur.map((f) => (f.path === folder ? { ...f, unread: Math.max(0, f.unread - unreadGone) } : f)));
      if (selectedUid && gone.has(selectedUid)) clearReading();
    };
    setChecked(new Set());
    switch (action) {
      case "read":
      case "unread": {
        const seen = action === "read";
        const delta = items.filter((m) => m.seen !== seen).length;
        setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (uids.includes(x.uid) ? { ...x, seen } : x)) }));
        setFolders((cur) => cur.map((f) => (f.path === folder ? { ...f, unread: Math.max(0, f.unread + (seen ? -delta : delta)) } : f)));
        void bulkSetFlag(folder, uids, "seen", seen, addr).then(() => setToast(`Marked ${plural} as ${action}.`)).catch(fail);
        break;
      }
      case "star":
      case "unstar": {
        const flagged = action === "star";
        setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (uids.includes(x.uid) ? { ...x, flagged } : x)) }));
        void bulkSetFlag(folder, uids, "flagged", flagged, addr).catch(fail);
        break;
      }
      case "archive":
        if (!archivePath || folder === archivePath) return setToast("No archive folder available.");
        removeAll();
        void bulkMove(folder, uids, archivePath, addr).then(() => setToast(`Archived ${plural}.`)).catch(fail);
        break;
      case "spam":
        if (!junkPath || folder === junkPath) return;
        removeAll();
        void bulkMove(folder, uids, junkPath, addr).then(() => setToast(`Moved ${plural} to Spam.`)).catch(fail);
        break;
      case "notSpam":
        removeAll();
        void bulkMove(folder, uids, inboxPath, addr).then(() => setToast(`Moved ${plural} to the Inbox.`)).catch(fail);
        break;
      case "delete":
        removeAll();
        void bulkDelete(folder, uids, addr).then(() => setToast(trashPath && folder !== trashPath ? `Moved ${plural} to Trash.` : `Deleted ${plural}.`)).catch(fail);
        break;
      case "move":
        if (!toFolder || toFolder === folder) return;
        removeAll();
        void bulkMove(folder, uids, toFolder, addr).then(() => setToast(`Moved ${plural} to ${labelFor(toFolder)}.`)).catch(fail);
        break;
    }
  };

  /* ---- Folder management (company inbox) -------------------------------- */
  const refreshFolders = async () => {
    const addr = activeAddress;
    const f = await listFolders(addr);
    if (view.current.address === addr) setFolders(f);
    return f;
  };
  const submitFolderDialog = async (value: string) => {
    const d = folderDialog;
    if (!d) return;
    const addr = activeAddress;
    try {
      if (d.mode === "create") {
        const r = await createFolder(value, addr);
        await refreshFolders();
        setToast(`Folder “${value}” created.`);
        setFolderDialog(null);
        selectFolder(r.path);
      } else if (d.mode === "rename" && d.path) {
        const r = await renameFolder(d.path, value, addr);
        await refreshFolders();
        if (selected === d.path) setSelected(r.path);
        setToast("Folder renamed.");
        setFolderDialog(null);
      } else if (d.mode === "delete" && d.path) {
        const r = await deleteFolder(d.path, addr, { force: Boolean(d.messages) });
        if (!r.ok) {
          if (r.messages && !d.messages) {
            setFolderDialog({ ...d, messages: r.messages, error: undefined });
            return;
          }
          setFolderDialog({ ...d, error: r.error || "Couldn't delete that folder." });
          return;
        }
        await refreshFolders();
        if (selected === d.path) selectFolder(inboxPath);
        setToast("Folder deleted.");
        setFolderDialog(null);
      }
    } catch (e) {
      setFolderDialog({ ...d, error: errText(e, "That didn't work.") });
    }
  };

  /* ---- Compose / reply -------------------------------------------------- */
  const stripRe = (s: string) => s.replace(/^\s*(re|fwd?):\s*/i, "").trim();
  const quoteOf = (m: MessageFull) =>
    m.html ??
    (m.text ? `<pre style="white-space:pre-wrap">${m.text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</pre>` : "");

  // The signature is appended by the Composer (HTML part + plain-text part), so
  // new messages start with an empty body — the sig is no longer inlined into
  // the editable text.
  const openCompose = (to = "") =>
    compose.open({ mode: "new", to, cc: "", subject: "", body: "", sendMailboxAddress: activeAddress, ...sigFields(false) });

  const openReply = (all: boolean) => {
    if (!message) return;
    const m = message;
    const selfAddr = mailbox?.address?.toLowerCase();
    const ccList = all
      ? [...m.to, ...m.cc].map((a) => a.address).filter((a) => a.toLowerCase() !== selfAddr && a.toLowerCase() !== m.from.address.toLowerCase())
      : [];
    compose.open({
      mode: all ? "replyAll" : "reply",
      to: m.from.address,
      cc: [...new Set(ccList)].join(", "),
      subject: `Re: ${stripRe(m.subject) || "(no subject)"}`,
      body: `\n\n`,
      quotedHtml: `<p>On ${new Date(m.date).toLocaleString()}, ${displayName(m.from)} wrote:</p>${quoteOf(m)}`,
      sendMailboxAddress: m.mailbox ?? activeAddress,
      ...sigFields(true),
      inReplyToUid: m.uid,
      replyFolder: m.folder,
    });
  };

  const openForward = () => {
    if (!message) return;
    const m = message;
    compose.open({
      mode: "forward",
      to: "",
      cc: "",
      subject: `Fwd: ${stripRe(m.subject) || "(no subject)"}`,
      body: `\n\n`,
      quotedHtml: `<p>---------- Forwarded message ----------<br>From: ${displayName(m.from)} &lt;${m.from.address}&gt;<br>Date: ${new Date(m.date).toLocaleString()}<br>Subject: ${m.subject}</p>${quoteOf(m)}`,
      sendMailboxAddress: m.mailbox ?? activeAddress,
      ...sigFields(true),
    });
  };

  const handleSend = async (payload: SendPayload) => {
    const res = await sendMessage(payload, message?.mailbox ?? activeAddress);
    if (res && res.ok === false) throw new Error(res.error || "The mail server rejected the message.");
    setToast("Message sent.");
    // If we're viewing Sent, refresh it.
    const sentPath = folders.find((f) => f.role === "sent")?.path;
    if (resolvePath(selected) === sentPath) reloadCurrent();
  };

  const quickReply = async (text: string) => {
    if (!message) return;
    const m = message;
    try {
      await handleSend({
        to: m.from.address,
        subject: `Re: ${stripRe(m.subject) || "(no subject)"}`,
        text,
        html: `<div style="white-space:pre-wrap">${text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</div>`,
        inReplyToUid: m.uid,
        replyFolder: m.folder,
      });
      setMessage((cur) => (cur ? { ...cur, answered: true } : cur));
    } catch (e) {
      setToast(e instanceof Error ? e.message : "Reply failed.", "error");
      throw e;
    }
  };

  /* ---- Search debounce -------------------------------------------------- */
  const onSearch = (s: string) => {
    setSearch(s);
    if (searchTimer.current) clearTimeout(searchTimer.current);
    searchTimer.current = setTimeout(() => {
      setPage(1);
      setChecked(new Set());
      void loadList(selected, 1, s);
    }, 350);
  };

  const onPage = (p: number) => {
    setPage(p);
    setChecked(new Set());
    void loadList(selected, p, search);
  };

  const onTab = (t: MailTab) => setTab(t);

  // Refresh really re-asks the mail server for everything on screen — folders
  // (with their counts), the current page, the switcher list and the unread
  // badges — and says when it last succeeded, so a stale view can't hide.
  const refresh = async () => {
    setRefreshing(true);
    const addr = activeAddress;
    try {
      const [f, mb] = await Promise.all([listFolders(addr), loadMailboxes().catch(() => null)]);
      if (view.current.address === addr) setFolders(f);
      if (mb) setMailboxes(Array.isArray(mb) ? mb : mb ? [mb] : []);
      await loadList(selected, page, search, addr);
      void pollUnread();
    } catch (e) {
      setToast(`Refresh failed: ${errText(e, "the mail server didn't answer")}`, "error", { label: "Retry", run: () => void refreshRef.current() });
    } finally {
      setRefreshing(false);
    }
  };
  const refreshRef = useRef(refresh);
  refreshRef.current = refresh;

  /* ---- Toast auto-dismiss ---------------------------------------------- */
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToastState(null), toast.tone === "error" ? 7000 : 2600);
    return () => clearTimeout(t);
  }, [toast]);

  /* ---- Stale build (the app was redeployed under this tab) -------------- */
  useEffect(() => {
    const on = () => setStaleBuild(true);
    window.addEventListener(MAIL_STALE_BUILD_EVENT, on);
    return () => window.removeEventListener(MAIL_STALE_BUILD_EVENT, on);
  }, []);

  /* ---- Keyboard shortcuts ---------------------------------------------- */
  // Messages currently visible in the list (after the category-tab filter),
  // used to move the j/k selection cursor.
  const visibleMessages =
    tab === "all" ? list.messages : list.messages.filter((m) => categoryOf(m.from, m.subject) === tab);

  const scrollRowIntoView = (uid: number) => {
    requestAnimationFrame(() => {
      document.querySelector(`[data-mail-uid="${uid}"]`)?.scrollIntoView({ block: "nearest" });
    });
  };

  const moveCursor = (dir: 1 | -1) => {
    if (visibleMessages.length === 0) return;
    const curId = cursorUid ?? selectedUid;
    let idx = visibleMessages.findIndex((m) => m.uid === curId);
    if (idx === -1) idx = dir === 1 ? -1 : 0;
    const next = Math.max(0, Math.min(visibleMessages.length - 1, idx + dir));
    const target = visibleMessages[next];
    if (target) {
      setCursorUid(target.uid);
      scrollRowIntoView(target.uid);
    }
  };

  const openCursor = () => {
    const id = cursorUid ?? selectedUid;
    const m = visibleMessages.find((x) => x.uid === id);
    if (m) openMessage(m);
  };

  // A single always-current handler behind a stable ref so the window listener
  // is bound once yet never reads stale state.
  const keyHandlerRef = useRef<(e: KeyboardEvent) => void>(() => {});
  keyHandlerRef.current = (e: KeyboardEvent) => {
    if (showHelp) {
      if (e.key === "Escape" || e.key === "?") {
        e.preventDefault();
        setShowHelp(false);
      }
      return;
    }
    // The Composer owns its own keys while it's open; dialogs own theirs.
    if (compose.isOpen || folderDialog || showSettings) return;

    const el = document.activeElement as HTMLElement | null;
    const typing =
      !!el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable);
    if (typing) {
      if (e.key === "Escape") el?.blur();
      return;
    }
    if (e.metaKey || e.ctrlKey || e.altKey) return;

    const hasBulk = checked.size > 0;
    switch (e.key) {
      case "j": e.preventDefault(); moveCursor(1); break;
      case "k": e.preventDefault(); moveCursor(-1); break;
      case "x": {
        const id = cursorUid ?? selectedUid;
        if (id != null) { e.preventDefault(); toggleChecked(id); }
        break;
      }
      case "Enter":
        // Let a focused button/link handle its own Enter instead of opening.
        if (el && (el.tagName === "BUTTON" || el.tagName === "A")) break;
        e.preventDefault();
        openCursor();
        break;
      case "o": e.preventDefault(); openCursor(); break;
      case "u": if (message || msgError) { e.preventDefault(); clearReading(); } break;
      case "I": e.preventDefault(); if (hasBulk) runBulk("read"); break;
      case "U":
        e.preventDefault();
        if (hasBulk) runBulk("unread");
        else if (message) markUnread(message);
        break;
      case "r": if (message) { e.preventDefault(); openReply(false); } break;
      case "a": if (message) { e.preventDefault(); openReply(true); } break;
      case "f": if (message) { e.preventDefault(); openForward(); } break;
      case "e":
        e.preventDefault();
        if (hasBulk) runBulk("archive");
        else if (message) doArchive();
        break;
      case "#":
        e.preventDefault();
        if (hasBulk) runBulk("delete");
        else if (message) doDelete();
        break;
      case "!":
        // Report spam (Gmail's key). Inside Junk it means "not spam".
        e.preventDefault();
        if (hasBulk) runBulk(junkPath && selected === junkPath ? "notSpam" : "spam");
        else if (message) {
          if (junkPath && message.folder === junkPath) doMarkNotSpam();
          else doMarkSpam();
        }
        break;
      case "s": if (message) { e.preventDefault(); toggleStar(message); } break;
      case "c": e.preventDefault(); openCompose(); break;
      case "/": e.preventDefault(); document.getElementById("mail-search-input")?.focus(); break;
      case "?": e.preventDefault(); setShowHelp(true); break;
      case "Escape":
        e.preventDefault();
        if (hasBulk) setChecked(new Set());
        else clearReading();
        break;
      default: break;
    }
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => keyHandlerRef.current(e);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // The ComposeProvider owns sending now (so a message can be sent from any page),
  // and fires MAIL_SENT_EVENT afterwards. When the current view is Sent, refresh
  // it so the just-sent copy appears.
  const onSentRef = useRef<() => void>(() => {});
  onSentRef.current = () => {
    const sentPath = folders.find((f) => f.role === "sent")?.path;
    if (resolvePath(selected) === sentPath) reloadCurrent();
  };
  useEffect(() => {
    const onSent = () => onSentRef.current();
    window.addEventListener(MAIL_SENT_EVENT, onSent);
    return () => window.removeEventListener(MAIL_SENT_EVENT, onSent);
  }, []);

  /* ---- Auto-refresh (light polling) ------------------------------------- */
  // Poll the current folder quietly and swap in the fresh page — without
  // touching the open message or the compose draft. PAUSED while the tab is
  // hidden. The response is applied only if no other list request started in
  // the meantime AND the view (mailbox/folder/page/search) is unchanged — the
  // old guard compared the captured values with themselves and never fired.
  const pollRef = useRef<() => void>(() => {});
  pollRef.current = () => {
    if (typeof document !== "undefined" && document.hidden) return;
    if (listLoading || refreshing || switching) return;
    const v = { ...view.current };
    const path = resolvePath(v.key);
    if (path === null) return;
    const ticket = listTicket.current;
    listMessages(path, v.key === STARRED ? 1 : v.page, v.q || undefined, v.address)
      .then((res) => {
        const now = view.current;
        if (ticket !== listTicket.current) return;
        if (now.address !== v.address || now.key !== v.key || now.page !== v.page || now.q !== v.q) return;
        setList(shape(v.key, res, v.address));
        setUpdatedAt(Date.now());
        setListError(null);
      })
      .catch(() => {
        /* transient IMAP hiccup — the next tick tries again, no toast */
      });
  };
  useEffect(() => {
    const id = setInterval(() => pollRef.current(), LIST_POLL_MS);
    // Refresh immediately when the tab regains focus (it was paused while hidden).
    const onVis = () => {
      if (!document.hidden) pollRef.current();
    };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      clearInterval(id);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  const unreadByAddress = Object.fromEntries(Object.values(unread).map((u) => [u.address, u.unread]));
  const railProps = {
    primary: primaryItems.filter((i) => !i.key.startsWith("__missing_")),
    custom: customItems,
    selected,
    mailbox,
    mailboxes,
    activeAddress,
    switchingTo: switching,
    unreadByAddress: isCompany ? unreadByAddress : undefined,
    onSwitchMailbox: (a: string) => void switchMailbox(a),
    onSelect: selectFolder,
    onRefresh: () => void refresh(),
    refreshing,
    filtersHref: filtersHref ? `${filtersHref}?mailbox=${encodeURIComponent(activeAddress ?? "")}` : undefined,
    onNewFolder: isCompany ? () => setFolderDialog({ mode: "create" }) : undefined,
    onRenameFolder: isCompany ? (path: string) => setFolderDialog({ mode: "rename", path, name: folders.find((f) => f.path === path)?.name }) : undefined,
    onDeleteFolder: isCompany ? (path: string) => setFolderDialog({ mode: "delete", path, name: folders.find((f) => f.path === path)?.name }) : undefined,
    notify: isCompany ? notify : undefined,
    onToggleNotify: isCompany ? () => void toggleNotify() : undefined,
  };

  /* ---- Render ----------------------------------------------------------- */
  return (
    // `min-h-0`, not a min-height floor: the shell sizes this route to exactly
    // the viewport that is left. No `border-t` either — this sits flush under
    // the header, whose border-b is the only line that belongs there.
    <div className="relative flex h-full min-h-0 overflow-hidden bg-navy-900/60 backdrop-blur-md" data-mail-client={variant} data-active-mailbox={activeAddress}>
      {/* Folder rail — static on md+, slide-over on mobile. Collapses to a slim
          icons-only strip to give the list + reading pane more room. */}
      <aside className={`hidden min-h-0 flex-none self-start overflow-hidden border-r border-white/[0.06] bg-navy-950/30 transition-[width] duration-300 ease-[cubic-bezier(.22,1,.36,1)] motion-reduce:transition-none md:sticky md:top-0 md:flex md:h-full ${railCollapsed ? "w-14" : "w-56 lg:w-60"}`}>
        {railCollapsed ? (
          <div className="w-14 flex min-h-0 flex-1">
            <MiniRail
              items={primaryItems.filter((i) => !i.key.startsWith("__missing_"))}
              selected={selected}
              onSelect={selectFolder}
              onCompose={() => openCompose()}
              onExpand={toggleRail}
            />
          </div>
        ) : (
          <div className="flex min-h-0 w-56 flex-1 lg:w-60">
            <FolderRail
              {...railProps}
              onCompose={() => openCompose()}
              onOpenSettings={() => setShowSettings(true)}
              onCollapse={toggleRail}
            />
          </div>
        )}
      </aside>

      {/* Mobile rail drawer */}
      {railOpen && (
        <div className="absolute inset-0 z-40 md:hidden">
          <div className="absolute inset-0 bg-navy-950/70 backdrop-blur-sm" onClick={() => setRailOpen(false)} />
          <div className="absolute inset-y-0 left-0 w-64 border-r border-white/[0.06] bg-navy-900 shadow-2xl animate-fade-up">
            <FolderRail
              {...railProps}
              onSelect={(k) => { setRailOpen(false); selectFolder(k); }}
              onCompose={() => { setRailOpen(false); openCompose(); }}
              onOpenSettings={() => { setRailOpen(false); setShowSettings(true); }}
            />
          </div>
        </div>
      )}

      {/* Message list */}
      <section className={`min-h-0 w-full flex-none border-r border-white/[0.06] md:w-80 lg:w-[22rem] ${mobilePane === "read" ? "hidden md:flex md:flex-col" : "flex flex-col"}`}>
        {staleBuild && (
          <div className="flex items-center gap-2 border-b border-amber-400/20 bg-amber-500/10 px-4 py-2 text-xs text-amber-200">
            <Icon.refresh size={13} className="flex-none" />
            <span className="flex-1">Nxeon was updated while this tab was open.</span>
            <button onClick={() => window.location.reload()} className="font-semibold text-amber-100 underline-offset-2 hover:underline">
              Reload
            </button>
          </div>
        )}
        <MessageList
          title={labelFor(selected)}
          mailboxLabel={isCompany ? activeAddress : undefined}
          unread={folders.find((f) => f.path === resolvePath(selected))?.unread ?? 0}
          messages={list.messages}
          total={list.total}
          page={selected === STARRED ? 1 : page}
          pageSize={list.pageSize}
          loading={listLoading || Boolean(switching)}
          loadingLabel={switching ? `Opening ${switching}…` : undefined}
          error={listError}
          onRetry={reloadCurrent}
          updatedAt={updatedAt}
          selectedUid={selectedUid}
          cursorUid={cursorUid}
          tab={tab}
          search={search}
          onTab={onTab}
          onSearch={onSearch}
          onSelect={openMessage}
          onToggleStar={toggleStar}
          onPage={onPage}
          onMenu={() => setRailOpen(true)}
          checked={checked}
          onToggleChecked={toggleChecked}
          onCheckAll={(all) => setChecked(all ? new Set(visibleMessages.map((m) => m.uid)) : new Set())}
          onBulk={runBulk}
          bulkFolders={folders.filter((f) => f.path !== resolvePath(selected))}
          inJunk={Boolean(junkPath && selected === junkPath)}
        />
      </section>

      {/* Reading pane — grows to absorb all remaining width. */}
      <section className={`min-h-0 min-w-0 flex-1 ${mobilePane === "list" ? "hidden md:flex md:flex-col" : "flex flex-col"}`}>
        <ReadingPane
          message={message}
          loading={msgLoading}
          error={msgError?.error ?? null}
          onRetry={msgError ? () => openMessage(msgError.summary) : undefined}
          folders={folders}
          currentFolder={message?.folder ?? ""}
          // The mailbox the open message belongs to. Attachment downloads are a
          // separate HTTP request that re-resolves the mailbox server-side, so
          // it has to be told which one — see `mailAttachmentUrl`.
          mailboxAddress={message?.mailbox ?? activeAddress}
          inJunk={Boolean(message && junkPath && message.folder === junkPath)}
          onReply={() => openReply(false)}
          onReplyAll={() => openReply(true)}
          onForward={openForward}
          onArchive={doArchive}
          onDelete={doDelete}
          onMove={doMove}
          onMarkSpam={doMarkSpam}
          onMarkNotSpam={doMarkNotSpam}
          onBlockSender={() => doBlock(false)}
          onBlockDomain={isCompany ? () => doBlock(true) : undefined}
          onCreateFilter={filtersHref ? createFilterFrom : undefined}
          onMarkUnread={() => message && markUnread(message)}
          onToggleStar={() => message && toggleStar(message)}
          onQuickReply={quickReply}
          onBack={clearReading}
        />
      </section>

      {/* Contact panel — collapsible to reclaim reading width. ONE element
          whose width animates (see the history in git blame for why). */}
      <aside
        className={
          "hidden min-h-0 flex-none flex-col overflow-hidden border-l border-white/[0.06] bg-navy-950/30 " +
          "transition-[width] duration-300 ease-[cubic-bezier(.22,1,.36,1)] motion-reduce:transition-none xl:flex " +
          (contactCollapsed ? "w-11 items-center py-3" : "w-72")
        }
      >
        {contactCollapsed ? (
          <button
            onClick={toggleContact}
            title="Show contact panel"
            aria-label="Show contact panel"
            className="btn-ghost rounded-lg p-2 text-slate-400 transition-colors hover:text-white"
          >
            <Icon.user size={17} />
          </button>
        ) : (
          <div className="w-72 min-h-0 flex-1">
            <ContactPanel
              message={message}
              folderLabel={labelFor(selected)}
              currentFolder={message?.folder ?? ""}
              mailboxAddress={message?.mailbox ?? activeAddress}
              onCompose={openCompose}
              onOpenMessage={openMessage}
              onCollapse={toggleContact}
            />
          </div>
        )}
      </aside>

      {/* Keyboard shortcut hint */}
      <button
        onClick={() => setShowHelp(true)}
        title="Keyboard shortcuts (?)"
        aria-label="Keyboard shortcuts"
        className="absolute bottom-3 right-3 z-30 hidden h-8 w-8 items-center justify-center rounded-full border border-white/10 bg-navy-900/80 text-sm font-semibold text-slate-400 shadow-lg backdrop-blur transition-colors hover:border-brand-400/40 hover:text-white md:flex"
      >
        ?
      </button>

      {showHelp && <ShortcutHelp onClose={() => setShowHelp(false)} />}

      {folderDialog && (
        <FolderDialog state={folderDialog} onCancel={() => setFolderDialog(null)} onSubmit={submitFolderDialog} />
      )}

      {/* Mailbox settings modal */}
      {showSettings && (
        <MailSettings
          mailboxAddress={activeAddress}
          storageUsedBytes={mailbox?.usedBytes}
          storageQuotaBytes={mailbox?.quotaBytes}
          onClose={() => setShowSettings(false)}
          onSettingsChanged={() => loadSig(activeAddress)}
        />
      )}

      {/* Toast */}
      {toast && (
        <div className="absolute bottom-4 left-1/2 z-50 w-[min(92%,34rem)] -translate-x-1/2" role={toast.tone === "error" ? "alert" : "status"}>
          <div
            className={`glass flex items-center gap-2 px-4 py-2.5 text-sm shadow-2xl animate-fade-up ${
              toast.tone === "error" ? "border-red-400/30 text-red-100" : "text-slate-100"
            }`}
          >
            <span className={toast.tone === "error" ? "flex-none text-red-300" : "flex-none text-brand-300"}>
              {toast.tone === "error" ? <Icon.alert size={15} /> : <Icon.mail size={15} />}
            </span>
            <span className="min-w-0 flex-1">{toast.text}</span>
            {toast.action && (
              <button
                onClick={() => {
                  const run = toast.action!.run;
                  setToastState(null);
                  run();
                }}
                className="flex-none rounded-md px-2 py-0.5 text-xs font-semibold text-brand-200 hover:bg-white/10"
              >
                {toast.action.label}
              </button>
            )}
            <button onClick={() => setToastState(null)} className="flex-none text-slate-500 hover:text-white" aria-label="Dismiss">
              <Icon.close size={13} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

