function UpdatedAgo({ at }: { at: number }) {
  // Re-render roughly every 30s so "just now" ages honestly.
  const [, setTick] = useState(0);
  useTick(() => setTick((t) => t + 1), 30_000);
  const sec = Math.max(0, Math.round((Date.now() - at) / 1000));
  const text = sec < 45 ? "updated just now" : sec < 3600 ? `updated ${Math.round(sec / 60)}m ago` : `updated ${new Date(at).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}`;
  return <span title={new Date(at).toLocaleString()}>{text}</span>;
}

function useTick(fn: () => void, ms: number) {
  const [id] = useState(() => ({ fn }));
  id.fn = fn;
  useEffectOnce(() => {
    const t = setInterval(() => id.fn(), ms);
    return () => clearInterval(t);
  });
}

function useEffectOnce(effect: () => void | (() => void)) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(effect, []);
}

