"use client";

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Icon } from "./util";

export type FolderDialogState = {
  mode: "create" | "rename" | "delete";
  path?: string;
  name?: string;
  /** Set after the server reports the folder still holds mail (delete → confirm again). */
  messages?: number;
  error?: string;
};

/** Small modal for creating / renaming / deleting a custom folder. Portalled to
 *  <body> so a backdrop-filter ancestor can't trap its `fixed` positioning. */
export function FolderDialog({
  state,
  onCancel,
  onSubmit,
}: {
  state: FolderDialogState;
  onCancel: () => void;
  onSubmit: (value: string) => Promise<void>;
}) {
  const [value, setValue] = useState(state.mode === "rename" ? state.name ?? "" : "");
  const [busy, setBusy] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  useEffect(() => input.current?.focus(), []);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onCancel();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onCancel]);

  const title = state.mode === "create" ? "New folder" : state.mode === "rename" ? "Rename folder" : "Delete folder";
  const submit = async () => {
    if (busy) return;
    if (state.mode !== "delete" && !value.trim()) return;
    setBusy(true);
    try {
      await onSubmit(value.trim());
    } finally {
      setBusy(false);
    }
  };

  const body = (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-navy-950/70 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label={title} onClick={onCancel}>
      <div className="w-full max-w-sm rounded-2xl border border-white/15 bg-navy-900 p-5 shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="mb-3 flex items-center justify-between">
          <h3 className="text-sm font-semibold text-white">{title}</h3>
          <button onClick={onCancel} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
            <Icon.close size={15} />
          </button>
        </div>
        {state.mode === "delete" ? (
          <p className="text-sm text-slate-300">
            {state.messages
              ? <>“{state.name}” still holds <b>{state.messages}</b> message{state.messages === 1 ? "" : "s"}. Deleting the folder deletes {state.messages === 1 ? "it" : "them"} too — this can&apos;t be undone.</>
              : <>Delete the folder “{state.name}”?</>}
          </p>
        ) : (
          <input
            ref={input}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") void submit();
            }}
            maxLength={60}
            placeholder="Folder name"
            className="input w-full"
            aria-label="Folder name"
          />
        )}
        {state.error && <p className="mt-2 text-xs text-red-300" role="alert">{state.error}</p>}
        <div className="mt-4 flex justify-end gap-2">
          <button onClick={onCancel} className="btn-secondary">Cancel</button>
          <button
            onClick={() => void submit()}
            disabled={busy || (state.mode !== "delete" && !value.trim())}
            className={state.mode === "delete" ? "btn-primary bg-none !bg-red-600 hover:!bg-red-500" : "btn-primary"}
          >
            {busy ? "Working…" : state.mode === "create" ? "Create" : state.mode === "rename" ? "Rename" : state.messages ? "Delete folder and mail" : "Delete"}
          </button>
        </div>
      </div>
    </div>
  );
  return typeof document === "undefined" ? null : createPortal(body, document.body);
}

