export async function GET() {
  const user = await realUser();
  if (!user || !(canAccess(user.role, "platform") || (await hasAreaAccess(user, "companyInbox")))) {
    return NextResponse.json({ unread: 0 }, { status: 401, headers: NO_STORE_HEADERS });
  }

  try {
    const boxes = await listCompanyMailboxes();
    // One cheap INBOX STATUS per mailbox, shared through lib/mail/unread.ts's
    // 20s cache with the inbox's own switcher badges (it used to be a full
    // LIST+STATUS of every folder per mailbox, per poll). Capped fan-out.
    const counts = await listMailboxUnread(boxes.slice(0, 12).map((b) => b.address));
    const unread = counts.reduce((sum, c) => sum + (c.error && c.error !== "stale" ? 0 : c.unread), 0);
    // Additive: per-mailbox breakdown for the Mail section's sidebar badges.
    const mailboxes = counts.map((c) => ({ address: c.address, unread: c.error && c.error !== "stale" ? 0 : c.unread }));
    return NextResponse.json({ unread, mailboxes }, { headers: NO_STORE_HEADERS });
  } catch {
    return NextResponse.json({ unread: 0 }, { headers: NO_STORE_HEADERS });
  }
}

