import Link from "next/link";
import { requireAreaOrGrant } from "@/lib/staff-grants";
import { PageHeader } from "@/components/ui/primitives";
import { listCompanyMailboxes } from "@/lib/actions-company-mail";
import { getFilterState, getMailPrefs } from "@/lib/actions-mail-filters";
import { FiltersClient } from "./FiltersClient";

export const dynamic = "force-dynamic";
export const metadata = { title: "Filters & spam" };

/**
 * /admin/mail/filters — rules engine, block/allow lists, presets and the spam
 * review queue for the company mailboxes. Rules are enforced on the mail
 * server (compiled to each mailbox's managed Sieve postfilter, see
 * lib/mail/filters/compile.ts); the page says plainly when that push failed.
 *
 * `?mailbox=` picks the mailbox; `?new=1&from=&subject=` opens the editor
 * pre-filled ("Filter messages like this" from the inbox).
 */
export default async function AdminMailFiltersPage({
  searchParams,
}: {
  searchParams: Promise<{ mailbox?: string; new?: string; from?: string; subject?: string }>;
}) {
  await requireAreaOrGrant("companyInbox");
  const sp = await searchParams;
  const boxes = await listCompanyMailboxes();
  if (boxes.length === 0) {
    return (
      <div className="space-y-6">
        <PageHeader title="Filters & spam" sub="Rules, blocked senders and the spam review queue for each company mailbox." />
        <div className="card p-8 text-center text-sm text-slate-400">
          No company mailboxes yet.{" "}
          <Link href="/admin/mail/mailboxes" className="text-brand-300 hover:underline">
            Create one
          </Link>{" "}
          first.
        </div>
      </div>
    );
  }
  const prefs = await getMailPrefs().catch(() => ({ lastMailbox: null, notifyNewMail: false }));
  const has = (a?: string | null) => Boolean(a && boxes.some((b) => b.address.toLowerCase() === a.toLowerCase()));
  const address = (has(sp.mailbox) ? sp.mailbox! : has(prefs.lastMailbox) ? prefs.lastMailbox! : boxes[0].address).toLowerCase();
  const initial = await getFilterState(address);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Filters & spam"
        sub="Rules run on the mail server as mail arrives — they keep working with this page closed."
      />
      <FiltersClient
        mailboxes={boxes.map((b) => ({ address: b.address, label: b.label }))}
        address={address}
        initial={initial.ok ? initial.state : null}
        initialError={initial.ok ? null : initial.error}
        prefill={sp.new ? { from: sp.from?.slice(0, 254) ?? "", subject: sp.subject?.slice(0, 200) ?? "" } : null}
      />
    </div>
  );
}

