"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import type { FilterState, ReviewItem, RuleRow } from "@/lib/actions-mail-filters";
import type { SyncStatus } from "@/lib/mail/filters/sync";
import type { MessageSummary } from "@/lib/mail/types";
import {
  ACTION_LABEL,
  ACTION_TYPES,
  CONDITION_FIELDS,
  CONDITION_OPS,
  FIELD_LABEL,
  OP_LABEL,
  type ActionType,
  type ConditionField,
  type ConditionOp,
  type FilterAction,
  type FilterCondition,
  type FilterRuleInput,
} from "@/lib/mail/filters/types";
import { FILTER_PRESETS } from "@/lib/mail/filters/presets";
import * as api from "@/components/customer/mail/mail-api";
import { MailboxAvatar } from "@/components/customer/mail/FolderRail";
import { Icon, shortDate, displayName } from "@/components/customer/mail/util";

type Tab = "rules" | "senders" | "review" | "presets";

const errText = (e: unknown) => (e instanceof Error ? e.message : "Something went wrong.");

function emptyRule(prefill?: { from: string; subject: string } | null): FilterRuleInput {
  const conditions: FilterCondition[] = [];
  if (prefill?.from) conditions.push({ field: "from", op: "is", value: prefill.from });
  if (prefill?.subject) conditions.push({ field: "subject", op: "contains", value: prefill.subject.replace(/^\s*(re|fwd?):\s*/i, "").slice(0, 80) });
  if (conditions.length === 0) conditions.push({ field: "subject", op: "contains", value: "" });
  return {
    name: prefill?.from ? `From ${prefill.from}` : "",
    enabled: true,
    matchMode: "all",
    conditions,
    actions: [{ type: "move", folder: "" }],
    stopProcessing: true,
    presetKey: null,
  };
}

function describeRule(r: Pick<FilterRuleInput, "conditions" | "actions" | "matchMode">): string {
  const cond = r.conditions
    .map((c) => `${c.field === "header" ? c.header : FIELD_LABEL[c.field].toLowerCase()} ${OP_LABEL[c.op]}${c.op === "exists" ? "" : ` “${c.value}”`}`)
    .join(r.matchMode === "any" ? " or " : " and ");
  const acts = r.actions
    .map((a) =>
      a.type === "move" ? `move to ${a.folder}` : a.type === "forward" ? `forward to ${a.to}` : a.type === "label" ? `label “${a.label}”` : ACTION_LABEL[a.type].toLowerCase(),
    )
    .join(", ");
  return `If ${cond} → ${acts}`;
}

export function FiltersClient({
  mailboxes,
  address,
  initial,
  initialError,
  prefill,
}: {
  mailboxes: { address: string; label: string | null }[];
  address: string;
  initial: FilterState | null;
  initialError: string | null;
  prefill: { from: string; subject: string } | null;
}) {
  const router = useRouter();
  const [state, setState] = useState<FilterState | null>(initial);
  const [loadError, setLoadError] = useState<string | null>(initialError);
  const [tab, setTab] = useState<Tab>("rules");
  const [editing, setEditing] = useState<{ id: string | null; rule: FilterRuleInput } | null>(
    prefill ? { id: null, rule: emptyRule(prefill) } : null,
  );
  const [toast, setToast] = useState<{ text: string; tone: "info" | "error" } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  const flash = useCallback((text: string, tone: "info" | "error" = "info") => setToast({ text, tone }), []);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), toast.tone === "error" ? 8000 : 3000);
    return () => clearTimeout(t);
  }, [toast]);

  // Persist the mailbox choice like the inbox does.
  useEffect(() => {
    void api.rememberMailbox(address).catch(() => {});
  }, [address]);

  const reload = useCallback(async () => {
    try {
      const r = await api.getFilterState(address);
      if (r.ok) {
        setState(r.state);
        setLoadError(null);
      } else setLoadError(r.error);
    } catch (e) {
      setLoadError(errText(e));
    }
  }, [address]);

  const afterSync = (sync: SyncStatus | undefined, okText: string) => {
    if (!sync) return flash(okText);
    if (sync.state === "error") flash(`Saved, but NOT active on the mail server: ${sync.error}`, "error");
    else if (sync.state === "unconfigured") flash(`Saved. ${sync.error}`, "error");
    else flash(okText);
  };

  const run = async <T,>(key: string, fn: () => Promise<T>): Promise<T | undefined> => {
    setBusy(key);
    try {
      return await fn();
    } catch (e) {
      flash(errText(e), "error");
      return undefined;
    } finally {
      setBusy(null);
    }
  };

  const switchMailbox = (a: string) => router.push(`/admin/mail/filters?mailbox=${encodeURIComponent(a)}`);

  if (!state) {
    return (
      <div className="card p-6 text-sm text-red-300" role="alert">
        Couldn&apos;t load filters for {address}: {loadError}{" "}
        <button onClick={() => void reload()} className="ml-2 font-semibold text-brand-300 hover:underline">
          Retry
        </button>
      </div>
    );
  }

  const sync = state.sync;
  return (
    <div className="space-y-5" data-testid="filters-page">
      {/* Mailbox + enforcement status */}
      <div className="card flex flex-wrap items-center gap-3 p-4">
        <label className="flex items-center gap-2 text-sm text-slate-300">
          <MailboxAvatar address={address} size={26} />
          <select
            value={address}
            onChange={(e) => switchMailbox(e.target.value)}
            className="input py-1.5"
            aria-label="Mailbox"
            data-testid="filters-mailbox"
          >
            {mailboxes.map((m) => (
              <option key={m.address} value={m.address.toLowerCase()}>
                {m.address}
                {m.label ? ` — ${m.label}` : ""}
              </option>
            ))}
          </select>
        </label>
        <SyncBadge sync={sync} />
        {(sync.state === "error" || sync.state === "unconfigured") && (
          <button
            className="btn-secondary py-1.5 text-xs"
            disabled={busy === "sync"}
            onClick={() =>
              void run("sync", async () => {
                const r = await api.retryFilterSync(address);
                if (!r.ok) return flash(r.error, "error");
                await reload();
                afterSync(r.sync, "Filters are active on the mail server.");
              })
            }
          >
            {busy === "sync" ? "Retrying…" : "Retry sync"}
          </button>
        )}
        <Link href={`/admin/mail?mailbox=${encodeURIComponent(address)}`} className="ml-auto text-xs text-brand-300 hover:underline">
          Open this inbox →
        </Link>
      </div>

      {/* Tabs */}
      <div className="flex flex-wrap gap-1.5 border-b border-white/[0.06] pb-3" role="tablist">
        {(
          [
            ["rules", `Rules (${state.rules.length})`],
            ["senders", `Blocked & allowed (${state.senders.length})`],
            ["review", "Review filtered mail"],
            ["presets", "Presets"],
          ] as [Tab, string][]
        ).map(([k, label]) => (
          <button
            key={k}
            role="tab"
            aria-selected={tab === k}
            onClick={() => setTab(k)}
            className={`rounded-full px-3.5 py-1.5 text-[13px] font-medium transition-colors ${
              tab === k ? "bg-brand-500/15 text-brand-200 ring-1 ring-inset ring-brand-500/40" : "text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      {tab === "rules" && (
        <RulesTab
          address={address}
          state={state}
          editing={editing}
          setEditing={setEditing}
          busy={busy}
          run={run}
          reload={reload}
          flash={flash}
          afterSync={afterSync}
        />
      )}
      {tab === "senders" && <SendersTab address={address} state={state} busy={busy} run={run} reload={reload} flash={flash} afterSync={afterSync} />}
      {tab === "review" && <ReviewTab address={address} flash={flash} afterSync={afterSync} reload={reload} />}
      {tab === "presets" && (
        <PresetsTab
          address={address}
          state={state}
          busy={busy}
          run={run}
          reload={reload}
          flash={flash}
          afterSync={afterSync}
          onEdit={(rule) => {
            setTab("rules");
            setEditing({ id: null, rule });
          }}
        />
      )}

      {toast && (
        <div className="fixed bottom-5 left-1/2 z-50 w-[min(92%,36rem)] -translate-x-1/2" role={toast.tone === "error" ? "alert" : "status"}>
          <div className={`glass flex items-start gap-2 px-4 py-3 text-sm shadow-2xl ${toast.tone === "error" ? "text-red-100" : "text-slate-100"}`}>
            <span className={toast.tone === "error" ? "text-red-300" : "text-brand-300"}>{toast.tone === "error" ? <Icon.alert size={15} /> : <Icon.check size={15} />}</span>
            <span className="min-w-0 flex-1">{toast.text}</span>
            <button onClick={() => setToast(null)} className="text-slate-500 hover:text-white" aria-label="Dismiss">
              <Icon.close size={13} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function SyncBadge({ sync }: { sync: SyncStatus }) {
  const map = {
    synced: { cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300", text: "Active on the mail server" },
    empty: { cls: "border-white/10 bg-white/[0.05] text-slate-400", text: "No rules on the mail server yet" },
    error: { cls: "border-red-500/40 bg-red-500/10 text-red-300", text: "NOT active on the mail server" },
    unconfigured: { cls: "border-amber-500/40 bg-amber-500/10 text-amber-300", text: "Mail-server API not configured" },
  }[sync.state];
  return (
    <span className="flex min-w-0 flex-col">
      <span className={`inline-flex w-fit items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold ${map.cls}`} data-testid="sync-badge">
        {map.text}
      </span>
      {sync.error && <span className="mt-1 max-w-xl text-[11px] text-slate-500">{sync.error}</span>}
      {sync.syncedAt && !sync.error && <span className="mt-1 text-[11px] text-slate-500">Last pushed {new Date(sync.syncedAt).toLocaleString()}</span>}
    </span>
  );
}

type TabProps = {
  address: string;
  state: FilterState;
  busy: string | null;
  run: <T>(key: string, fn: () => Promise<T>) => Promise<T | undefined>;
  reload: () => Promise<void>;
  flash: (t: string, tone?: "info" | "error") => void;
  afterSync: (s: SyncStatus | undefined, ok: string) => void;
};

/* ------------------------------------------------------------------------ */
/* Rules                                                                     */
/* ------------------------------------------------------------------------ */

function RulesTab({
  address,
  state,
  editing,
  setEditing,
  busy,
  run,
  reload,
  flash,
  afterSync,
}: TabProps & {
  editing: { id: string | null; rule: FilterRuleInput } | null;
  setEditing: (e: { id: string | null; rule: FilterRuleInput } | null) => void;
}) {
  const move = (idx: number, dir: -1 | 1) => {
    const ids = state.rules.map((r) => r.id);
    const j = idx + dir;
    if (j < 0 || j >= ids.length) return;
    [ids[idx], ids[j]] = [ids[j], ids[idx]];
    void run(`reorder`, async () => {
      const r = await api.reorderFilterRules(address, ids);
      if (!r.ok) return flash(r.error, "error");
      await reload();
      afterSync(r.sync, "Order saved — rules run top to bottom.");
    });
  };
  return (
    <div className="space-y-4">
      {editing ? (
        <RuleEditor
          address={address}
          folders={state.folders}
          initial={editing.rule}
          isNew={!editing.id}
          onCancel={() => setEditing(null)}
          onSave={async (rule) => {
            const r = await api.saveFilterRule(address, editing.id, rule);
            if (!r.ok) {
              flash(r.error, "error");
              return false;
            }
            setEditing(null);
            await reload();
            afterSync(r.sync, editing.id ? "Rule updated." : "Rule created — new mail is filtered from now on.");
            return true;
          }}
          flash={flash}
        />
      ) : (
        <div className="flex flex-wrap items-center gap-2">
          <button className="btn-primary" onClick={() => setEditing({ id: null, rule: emptyRule() })} data-testid="new-rule">
            <Icon.plus size={15} /> New rule
          </button>
          <p className="text-xs text-slate-500">Rules run top to bottom; a rule that files mail away stops the rest.</p>
        </div>
      )}

      {state.rules.length === 0 && !editing ? (
        <div className="card p-8 text-center text-sm text-slate-400">
          No rules yet. Start from a <b>preset</b> (DMARC reports, review sellers, cold pitches…) or create your own.
        </div>
      ) : (
        <ul className="space-y-2" data-testid="rule-list">
          {state.rules.map((r, i) => (
            <RuleRowView
              key={r.id}
              rule={r}
              first={i === 0}
              last={i === state.rules.length - 1}
              busy={busy}
              onMove={(d) => move(i, d)}
              onEdit={() => setEditing({ id: r.id, rule: { ...r } })}
              onToggle={() =>
                void run(`toggle:${r.id}`, async () => {
                  const res = await api.setFilterRuleEnabled(address, r.id, !r.enabled);
                  if (!res.ok) return flash(res.error, "error");
                  await reload();
                  afterSync(res.sync, r.enabled ? "Rule paused." : "Rule enabled.");
                })
              }
              onApply={() =>
                void run(`apply:${r.id}`, async () => {
                  const res = await api.applyFilterRuleNow(address, r.id);
                  if (!res.ok) return flash(res.error, "error");
                  await reload();
                  flash(
                    `Checked the newest ${res.scanned} inbox messages: ${res.matched} matched, ${res.moved} moved${res.flagged ? `, ${res.flagged} flagged` : ""}.${res.skippedForwards ? " Forwarding isn't replayed for old mail." : ""}`,
                  );
                })
              }
              onDelete={() => {
                if (!window.confirm(`Delete the rule “${r.name}”? Mail it already filed stays where it is.`)) return;
                void run(`delete:${r.id}`, async () => {
                  const res = await api.deleteFilterRule(address, r.id);
                  if (!res.ok) return flash(res.error, "error");
                  await reload();
                  afterSync(res.sync, "Rule deleted.");
                });
              }}
            />
          ))}
        </ul>
      )}
    </div>
  );
}

function RuleRowView({
  rule,
  first,
  last,
  busy,
  onMove,
  onEdit,
  onToggle,
  onApply,
  onDelete,
}: {
  rule: RuleRow;
  first: boolean;
  last: boolean;
  busy: string | null;
  onMove: (d: -1 | 1) => void;
  onEdit: () => void;
  onToggle: () => void;
  onApply: () => void;
  onDelete: () => void;
}) {
  return (
    <li className={`card flex flex-wrap items-center gap-3 p-3.5 ${rule.enabled ? "" : "opacity-60"}`} data-rule-id={rule.id}>
      <div className="flex flex-col">
        <button disabled={first || busy !== null} onClick={() => onMove(-1)} className="rounded p-0.5 text-slate-500 hover:text-white disabled:opacity-30" aria-label="Move up">
          <Icon.chevronLeft size={13} className="rotate-90" />
        </button>
        <button disabled={last || busy !== null} onClick={() => onMove(1)} className="rounded p-0.5 text-slate-500 hover:text-white disabled:opacity-30" aria-label="Move down">
          <Icon.chevronRight size={13} className="rotate-90" />
        </button>
      </div>
      <label className="flex cursor-pointer items-center" title={rule.enabled ? "Enabled" : "Paused"}>
        <input type="checkbox" checked={rule.enabled} onChange={onToggle} disabled={busy === `toggle:${rule.id}`} className="h-4 w-4 accent-brand-500" aria-label={`Enable ${rule.name}`} />
      </label>
      <div className="min-w-0 flex-1">
        <p className="flex items-center gap-2 text-sm font-semibold text-white">
          {rule.name}
          {rule.presetKey && <span className="rounded-full border border-white/10 px-1.5 text-[10px] font-medium text-slate-400">preset</span>}
        </p>
        <p className="mt-0.5 truncate text-xs text-slate-400" title={describeRule(rule)}>
          {describeRule(rule)}
        </p>
        {rule.appliedCount > 0 && <p className="mt-0.5 text-[11px] text-slate-500">Filed {rule.appliedCount} existing message{rule.appliedCount === 1 ? "" : "s"} via “Apply now”.</p>}
      </div>
      <div className="flex flex-wrap gap-1.5">
        <button className="btn-secondary py-1.5 text-xs" onClick={onApply} disabled={busy !== null} title="Run this rule over the newest 500 inbox messages now">
          {busy === `apply:${rule.id}` ? "Applying…" : "Apply to existing mail"}
        </button>
        <button className="btn-secondary py-1.5 text-xs" onClick={onEdit} disabled={busy !== null}>
          Edit
        </button>
        <button className="btn-ghost rounded-lg px-2 py-1.5 text-xs text-red-300 hover:bg-red-500/10" onClick={onDelete} disabled={busy !== null} aria-label={`Delete ${rule.name}`}>
          <Icon.trash size={14} />
        </button>
      </div>
    </li>
  );
}

function RuleEditor({
  address,
  folders,
  initial,
  isNew,
  onCancel,
  onSave,
  flash,
}: {
  address: string;
  folders: string[];
  initial: FilterRuleInput;
  isNew: boolean;
  onCancel: () => void;
  onSave: (rule: FilterRuleInput) => Promise<boolean>;
  flash: (t: string, tone?: "info" | "error") => void;
}) {
  const [rule, setRule] = useState<FilterRuleInput>(initial);
  const [saving, setSaving] = useState(false);
  const [preview, setPreview] = useState<{ scanned: number; count: number; samples: MessageSummary[] } | null>(null);
  const [previewing, setPreviewing] = useState(false);

  const setCond = (i: number, patch: Partial<FilterCondition>) =>
    setRule((r) => ({ ...r, conditions: r.conditions.map((c, j) => (j === i ? ({ ...c, ...patch } as FilterCondition) : c)) }));
  const setAct = (i: number, patch: Partial<FilterAction>) =>
    setRule((r) => ({ ...r, actions: r.actions.map((a, j) => (j === i ? ({ ...a, ...patch } as FilterAction) : a)) }));

  const folderOptions = useMemo(() => [...new Set([...folders, ...rule.actions.filter((a) => a.type === "move" && a.folder).map((a) => a.folder!)])], [folders, rule.actions]);

  const doPreview = async () => {
    setPreviewing(true);
    try {
      const r = await api.previewFilterRule(address, rule);
      if (!r.ok) flash(r.error, "error");
      else setPreview(r);
    } catch (e) {
      flash(errText(e), "error");
    } finally {
      setPreviewing(false);
    }
  };

  return (
    <div className="card space-y-5 p-5" data-testid="rule-editor">
      <div className="flex flex-wrap items-center gap-3">
        <h3 className="text-sm font-semibold text-white">{isNew ? "New rule" : "Edit rule"}</h3>
        <input
          value={rule.name}
          onChange={(e) => setRule({ ...rule, name: e.target.value })}
          placeholder="Rule name"
          maxLength={80}
          className="input min-w-[14rem] flex-1"
          aria-label="Rule name"
          data-testid="rule-name"
        />
      </div>

      <div>
        <div className="mb-2 flex items-center gap-2 text-sm text-slate-300">
          If
          <select value={rule.matchMode} onChange={(e) => setRule({ ...rule, matchMode: e.target.value as "all" | "any" })} className="input py-1" aria-label="Match mode">
            <option value="all">all</option>
            <option value="any">any</option>
          </select>
          of these match:
        </div>
        <div className="space-y-2">
          {rule.conditions.map((c, i) => (
            <div key={i} className="flex flex-wrap items-center gap-2" data-testid="rule-condition">
              <select
                value={c.field}
                onChange={(e) => {
                  const field = e.target.value as ConditionField;
                  setCond(i, { field, op: field === "body" && !["contains", "notContains"].includes(c.op) ? "contains" : c.op === "exists" && field !== "header" ? "contains" : c.op });
                }}
                className="input py-1.5"
                aria-label="Field"
              >
                {CONDITION_FIELDS.map((f) => (
                  <option key={f} value={f}>
                    {FIELD_LABEL[f]}
                  </option>
                ))}
              </select>
              {c.field === "header" && (
                <input value={c.header ?? ""} onChange={(e) => setCond(i, { header: e.target.value })} placeholder="Header name, e.g. List-Id" className="input w-44 py-1.5" aria-label="Header name" />
              )}
              <select value={c.op} onChange={(e) => setCond(i, { op: e.target.value as ConditionOp })} className="input py-1.5" aria-label="Operator">
                {CONDITION_OPS.filter((o) => (c.field === "header" ? true : o !== "exists"))
                  .filter((o) => (c.field === "body" ? o === "contains" || o === "notContains" : true))
                  .map((o) => (
                    <option key={o} value={o}>
                      {OP_LABEL[o]}
                    </option>
                  ))}
              </select>
              {c.op !== "exists" && (
                <input value={c.value} onChange={(e) => setCond(i, { value: e.target.value })} placeholder="Value" maxLength={200} className="input min-w-[12rem] flex-1 py-1.5" aria-label="Value" data-testid="condition-value" />
              )}
              <button
                onClick={() => setRule((r) => ({ ...r, conditions: r.conditions.filter((_, j) => j !== i) }))}
                disabled={rule.conditions.length <= 1}
                className="rounded-lg p-1.5 text-slate-500 hover:bg-white/[0.06] hover:text-white disabled:opacity-30"
                aria-label="Remove condition"
              >
                <Icon.close size={14} />
              </button>
            </div>
          ))}
        </div>
        <button
          onClick={() => setRule((r) => ({ ...r, conditions: [...r.conditions, { field: "subject", op: "contains", value: "" }] }))}
          disabled={rule.conditions.length >= 10}
          className="mt-2 text-xs font-semibold text-brand-300 hover:underline disabled:opacity-40"
        >
          + Add condition
        </button>
      </div>

      <div>
        <p className="mb-2 text-sm text-slate-300">Then:</p>
        <div className="space-y-2">
          {rule.actions.map((a, i) => (
            <div key={i} className="flex flex-wrap items-center gap-2" data-testid="rule-action">
              <select value={a.type} onChange={(e) => setAct(i, { type: e.target.value as ActionType })} className="input py-1.5" aria-label="Action">
                {ACTION_TYPES.map((t) => (
                  <option key={t} value={t}>
                    {ACTION_LABEL[t]}
                  </option>
                ))}
              </select>
              {a.type === "move" && (
                <>
                  <input
                    list="nx-filter-folders"
                    value={a.folder ?? ""}
                    onChange={(e) => setAct(i, { folder: e.target.value })}
                    placeholder="Folder (created if missing), e.g. Reports/DMARC"
                    className="input min-w-[16rem] flex-1 py-1.5"
                    aria-label="Folder"
                    data-testid="action-folder"
                  />
                  <datalist id="nx-filter-folders">
                    {folderOptions.map((f) => (
                      <option key={f} value={f} />
                    ))}
                  </datalist>
                </>
              )}
              {a.type === "forward" && (
                <input value={a.to ?? ""} onChange={(e) => setAct(i, { to: e.target.value })} placeholder="name@example.com" className="input min-w-[16rem] flex-1 py-1.5" aria-label="Forward to" />
              )}
              {a.type === "label" && (
                <input value={a.label ?? ""} onChange={(e) => setAct(i, { label: e.target.value })} placeholder="Label" maxLength={40} className="input w-48 py-1.5" aria-label="Label" />
              )}
              <button
                onClick={() => setRule((r) => ({ ...r, actions: r.actions.filter((_, j) => j !== i) }))}
                disabled={rule.actions.length <= 1}
                className="rounded-lg p-1.5 text-slate-500 hover:bg-white/[0.06] hover:text-white disabled:opacity-30"
                aria-label="Remove action"
              >
                <Icon.close size={14} />
              </button>
            </div>
          ))}
        </div>
        <button
          onClick={() => setRule((r) => ({ ...r, actions: [...r.actions, { type: "markRead" }] }))}
          disabled={rule.actions.length >= 6}
          className="mt-2 text-xs font-semibold text-brand-300 hover:underline disabled:opacity-40"
        >
          + Add action
        </button>
        <label className="mt-3 flex items-center gap-2 text-xs text-slate-400">
          <input type="checkbox" checked={rule.stopProcessing} onChange={(e) => setRule({ ...rule, stopProcessing: e.target.checked })} className="accent-brand-500" />
          Stop checking later rules when this one matches (always on for rules that file mail away)
        </label>
      </div>

      {preview && (
        <div className="rounded-xl border border-white/10 bg-white/[0.03] p-3" data-testid="rule-preview">
          <p className="text-sm text-slate-200">
            <b>{preview.count}</b> of the newest {preview.scanned} inbox messages match.
          </p>
          {preview.samples.length > 0 && (
            <ul className="mt-2 space-y-1">
              {preview.samples.map((m) => (
                <li key={m.uid} className="flex gap-2 truncate text-xs text-slate-400">
                  <span className="w-40 flex-none truncate text-slate-300">{displayName(m.from)}</span>
                  <span className="min-w-0 flex-1 truncate">{m.subject}</span>
                  <span className="flex-none text-slate-500">{shortDate(m.date)}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}

      <div className="flex flex-wrap items-center justify-end gap-2 border-t border-white/[0.06] pt-4">
        <button className="btn-secondary" onClick={() => void doPreview()} disabled={previewing} data-testid="rule-preview-btn">
          {previewing ? "Checking…" : "Preview matches"}
        </button>
        <button className="btn-ghost rounded-lg px-3 py-2 text-sm" onClick={onCancel}>
          Cancel
        </button>
        <button
          className="btn-primary"
          disabled={saving}
          data-testid="rule-save"
          onClick={async () => {
            setSaving(true);
            try {
              await onSave(rule);
            } catch (e) {
              flash(errText(e), "error");
            } finally {
              setSaving(false);
            }
          }}
        >
          {saving ? "Saving…" : isNew ? "Create rule" : "Save rule"}
        </button>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Blocked & allowed                                                          */
/* ------------------------------------------------------------------------ */

function SendersTab({ address, state, busy, run, reload, flash, afterSync }: TabProps) {
  const [block, setBlock] = useState("");
  const [allow, setAllow] = useState("");
  const add = (kind: "block" | "allow", value: string, clear: () => void) =>
    void run(`add:${kind}`, async () => {
      const r = await api.addSenderEntry(address, kind, value);
      if (!r.ok) return flash(r.error, "error");
      clear();
      await reload();
      afterSync(r.sync, kind === "block" ? `Blocked ${r.pattern} — their mail goes to Spam.` : `${r.pattern} will never be filtered.`);
    });
  const column = (kind: "block" | "allow", title: string, help: string, value: string, setValue: (v: string) => void) => {
    const rows = state.senders.filter((s) => s.kind === kind);
    return (
      <div className="card p-4">
        <h3 className="text-sm font-semibold text-white">{title}</h3>
        <p className="mt-0.5 text-xs text-slate-500">{help}</p>
        <form
          className="mt-3 flex gap-2"
          onSubmit={(e) => {
            e.preventDefault();
            if (value.trim()) add(kind, value, () => setValue(""));
          }}
        >
          <input value={value} onChange={(e) => setValue(e.target.value)} placeholder="name@example.com or example.com" className="input flex-1 py-1.5" aria-label={`${title} entry`} />
          <button className="btn-primary py-1.5" disabled={busy === `add:${kind}` || !value.trim()}>
            Add
          </button>
        </form>
        <ul className="mt-3 divide-y divide-white/[0.05]">
          {rows.length === 0 && <li className="py-2 text-xs text-slate-500">Nothing here yet.</li>}
          {rows.map((s) => (
            <li key={s.id} className="flex items-center gap-2 py-2 text-sm">
              <span className="min-w-0 flex-1 truncate text-slate-200">{s.pattern.startsWith("@") ? <>everyone at <b>{s.pattern}</b></> : s.pattern}</span>
              <span className="text-[11px] text-slate-500">{new Date(s.createdAt).toLocaleDateString()}</span>
              <button
                onClick={() =>
                  void run(`rm:${s.id}`, async () => {
                    const r = await api.removeSenderEntry(address, s.id);
                    if (!r.ok) return flash(r.error, "error");
                    await reload();
                    afterSync(r.sync, "Removed.");
                  })
                }
                className="rounded p-1 text-slate-500 hover:bg-white/[0.06] hover:text-white"
                aria-label={`Remove ${s.pattern}`}
              >
                <Icon.close size={13} />
              </button>
            </li>
          ))}
        </ul>
      </div>
    );
  };
  return (
    <div className="grid gap-4 md:grid-cols-2">
      {column("block", "Blocked senders", "Mail from these addresses or domains goes straight to Spam.", block, setBlock)}
      {column("allow", "Never filter", "These senders skip every rule and the blocklist (the server's own spam scoring still applies).", allow, setAllow)}
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Review queue                                                               */
/* ------------------------------------------------------------------------ */

function ReviewTab({
  address,
  flash,
  afterSync,
  reload,
}: {
  address: string;
  flash: (t: string, tone?: "info" | "error") => void;
  afterSync: (s: SyncStatus | undefined, ok: string) => void;
  reload: () => Promise<void>;
}) {
  const [items, setItems] = useState<ReviewItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [working, setWorking] = useState<string | null>(null);
  const load = useCallback(async () => {
    setError(null);
    try {
      const r = await api.listFilteredMail(address);
      if (!r.ok) setError(r.error);
      else setItems(r.items);
    } catch (e) {
      setError(errText(e));
    }
  }, [address]);
  useEffect(() => {
    void load();
  }, [load]);

  const restore = async (it: ReviewItem, neverFilter: boolean) => {
    const key = `${it.folder}:${it.uid}`;
    setWorking(key);
    try {
      const r = await api.restoreFilteredMail(address, it.folder, it.uid, { neverFilter, sender: it.from.address });
      if (!r.ok) return flash(r.error, "error");
      setItems((cur) => (cur ? cur.filter((x) => !(x.folder === it.folder && x.uid === it.uid)) : cur));
      if (neverFilter) {
        await reload();
        afterSync(r.sync, `Moved back to the inbox, and ${it.from.address} will never be filtered.`);
      } else flash("Moved back to the inbox.");
    } catch (e) {
      flash(errText(e), "error");
    } finally {
      setWorking(null);
    }
  };

  if (error)
    return (
      <div className="card p-5 text-sm text-red-300" role="alert">
        {error}{" "}
        <button onClick={() => void load()} className="ml-2 font-semibold text-brand-300 hover:underline">
          Retry
        </button>
      </div>
    );
  if (!items)
    return (
      <div className="card space-y-2 p-5" aria-busy="true">
        {Array.from({ length: 5 }).map((_, i) => (
          <div key={i} className="skeleton h-4 w-full" />
        ))}
      </div>
    );
  return (
    <div className="card overflow-hidden" data-testid="review-queue">
      <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-3">
        <p className="text-sm text-slate-300">
          Last 30 days: mail your rules or blocklist filed away, plus everything in Spam. <b>{items.length}</b> item{items.length === 1 ? "" : "s"}.
        </p>
        <button onClick={() => void load()} className="btn-ghost rounded-lg p-1.5" aria-label="Reload">
          <Icon.refresh size={15} />
        </button>
      </div>
      {items.length === 0 ? (
        <p className="px-4 py-8 text-center text-sm text-slate-500">Nothing was filtered in the last 30 days.</p>
      ) : (
        <ul className="divide-y divide-white/[0.05]">
          {items.map((it) => {
            const key = `${it.folder}:${it.uid}`;
            return (
              <li key={key} className="flex flex-wrap items-center gap-3 px-4 py-2.5" data-review-item={key}>
                <span className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold ${it.reason === "filtered" ? "border-brand-500/40 text-brand-200" : "border-amber-500/40 text-amber-200"}`}>
                  {it.reason === "filtered" ? "Filtered" : "Spam"}
                </span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm text-slate-200">{it.subject}</p>
                  <p className="truncate text-xs text-slate-500">
                    {displayName(it.from)} &lt;{it.from.address}&gt; · in {it.folder} · {shortDate(it.date)}
                  </p>
                </div>
                <button className="btn-secondary py-1.5 text-xs" disabled={working === key} onClick={() => void restore(it, false)}>
                  Restore
                </button>
                <button className="btn-secondary py-1.5 text-xs" disabled={working === key} onClick={() => void restore(it, true)} title="Restore and add the sender to “Never filter”">
                  Restore + never filter
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Presets                                                                    */
/* ------------------------------------------------------------------------ */

function PresetsTab({ address, state, busy, run, reload, flash, afterSync, onEdit }: TabProps & { onEdit: (r: FilterRuleInput) => void }) {
  const [previews, setPreviews] = useState<Record<string, { count: number; scanned: number }>>({});
  return (
    <div className="grid gap-3 md:grid-cols-2" data-testid="presets">
      {FILTER_PRESETS.map((p) => {
        const enabled = state.presets.find((x) => x.key === p.key)?.enabled;
        const pv = previews[p.key];
        return (
          <div key={p.key} className="card flex flex-col p-4" data-preset={p.key}>
            <div className="flex items-start justify-between gap-2">
              <h3 className="text-sm font-semibold text-white">{p.title}</h3>
              {enabled && <span className="rounded-full border border-emerald-500/40 bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold text-emerald-300">Enabled</span>}
            </div>
            <p className="mt-1 flex-1 text-xs text-slate-400">{p.description}</p>
            <p className="mt-2 text-[11px] text-slate-500">{describeRule(p.rule)}</p>
            {pv && (
              <p className="mt-2 text-xs text-slate-300">
                Would catch <b>{pv.count}</b> of your newest {pv.scanned} inbox messages.
              </p>
            )}
            <div className="mt-3 flex flex-wrap gap-2">
              <button
                className="btn-secondary py-1.5 text-xs"
                disabled={busy !== null}
                onClick={() =>
                  void run(`pv:${p.key}`, async () => {
                    const r = await api.previewFilterRule(address, p.rule);
                    if (!r.ok) return flash(r.error, "error");
                    setPreviews((cur) => ({ ...cur, [p.key]: { count: r.count, scanned: r.scanned } }));
                  })
                }
              >
                {busy === `pv:${p.key}` ? "Checking…" : "Preview"}
              </button>
              <button className="btn-secondary py-1.5 text-xs" onClick={() => onEdit({ ...p.rule })}>
                Customise…
              </button>
              <button
                className="btn-primary py-1.5 text-xs"
                disabled={busy !== null || enabled}
                data-testid={`enable-${p.key}`}
                onClick={() =>
                  void run(`en:${p.key}`, async () => {
                    const r = await api.enableFilterPreset(address, p.key);
                    if (!r.ok) return flash(r.error, "error");
                    await reload();
                    afterSync(r.sync, `“${p.title}” enabled for new mail. Use “Apply to existing mail” on the rule to sort what's already there.`);
                  })
                }
              >
                {enabled ? "Enabled" : busy === `en:${p.key}` ? "Enabling…" : "Enable"}
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

