// Post-fix Playwright verification against the sandbox dev server + fake IMAP fixture.
// Never touches the real mail server (MAIL_IMAP_HOST=127.0.0.1 in .env).
const { chromium } = require("/opt/nxeon/node_modules/playwright");
const fs = require("fs");
const { execFileSync } = require("child_process");
const T = JSON.parse(fs.readFileSync(__dirname + "/tokens.json", "utf8"));
const BASE = "http://localhost:3109";
const CTL = "http://127.0.0.1:39080";
const OUT = process.env.OUT;
fs.mkdirSync(OUT, { recursive: true });
const results = [];
const ok = (name, cond, detail = "") => {
  results.push(`${cond ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`);
  console.log(results[results.length - 1]);
};
const ctl = async (path, body) => {
  const r = await fetch(CTL + path, body ? { method: "POST", body: JSON.stringify(body) } : undefined);
  return r.json();
};
const psql = (sql) =>
  execFileSync("bash", ["-c", `set -a; . /opt/nxeon-wt-adminmail/.env; set +a; psql "$DATABASE_URL" -tAc "${sql.replace(/"/g, '\\"')}"`]).toString().trim();

(async () => {
  const b = await chromium.launch();
  const ctx = await b.newContext({ viewport: { width: 1440, height: 900 } });
  await ctx.addCookies([{ name: "nxeon_session", value: T.admin, domain: "localhost", path: "/" }]);
  const p = await ctx.newPage();
  const errors = [];
