  });
  await p.click("text=Refresh");
  await p.waitForSelector("text=Nxeon was updated while this tab was open.", { timeout: 15000 }).then(() => ok("stale-build reload bar appears", true)).catch(() => ok("stale-build reload bar appears", false));
  await p.unroute("**/api/mail/rpc");

  // 7) unread badges + new-mail detection
  await p.click("[data-testid=mailbox-switcher]");
  const pills = await p.$$eval("[role=option]", (els) => els.map((e) => e.textContent));
  ok("switcher lists every mailbox with unread pills", pills.length >= 4 && pills.some((t) => /\d/.test(t || "")), pills.join(" | ").slice(0, 200));
  await p.screenshot({ path: OUT + "/04-switcher.png" });
  await p.keyboard.press("Escape");
  await p.mouse.click(5, 5);
  const titleBefore = await p.title();
  await ctl("/deliver", { to: "santino@nxeon.cloud", subject: "[santino] Brand new arrival", from: "New Person <new@person.test>" });
  let arrived = false;
  for (let i = 0; i < 80 && !arrived; i++) {
    await p.waitForTimeout(500);
    arrived = (await subjects()).some((s) => s.includes("Brand new arrival"));
  }
  ok("new mail appears without a manual refresh (unread poll → list refresh)", arrived);
  ok("document title carries the unread count", /^\(\d+\)/.test(await p.title()), `${titleBefore} → ${await p.title()}`);

  // 8) Sent view newest first + quick reply appends to Sent
  await p.click("[data-mail-uid] >> text=[santino] Partnership follow-up");
  await p.waitForSelector("textarea[placeholder^='Quick reply']");
  await p.fill("textarea[placeholder^='Quick reply']", "Thanks — verified from the sandbox.");
  await p.click("button:has-text('Send')");
  await p.waitForSelector("text=Message sent.", { timeout: 30000 }).then(() => ok("quick reply sends (rpc sendMessage)", true)).catch(() => ok("quick reply sends (rpc sendMessage)", false));
  await p.click("nav >> text=Sent");
  await p.waitForTimeout(2500);
  const sent = await subjects();
  ok("Sent shows the just-sent reply first", (sent[0] || "").startsWith("Re: [santino] Partnership follow-up"), sent.slice(0, 2).join(" | "));
  await p.click("nav >> text=Inbox");
  await p.waitForTimeout(2000);

  // 9) bulk select → mark read
  const unreadBefore = Number(((await p.textContent("h2 + span").catch(() => "0")) || "0").replace(/\D/g, "")) || 0;
  const rows = await p.$$("[data-mail-uid] [role=checkbox]");
  await rows[0].click();
  await rows[1].click();
  ok("bulk bar appears with 2 selected", (await p.textContent("[data-testid=bulk-bar]"))?.includes("2 selected"));
  await p.screenshot({ path: OUT + "/05-bulk.png" });
  await p.click("[data-testid=bulk-bar] button[title^='Mark read']");
  await p.waitForTimeout(1500);
  const unreadAfter = Number(((await p.textContent("h2 + span").catch(() => "0")) || "0").replace(/\D/g, "")) || 0;
  ok("bulk mark-read lowers the unread count", unreadAfter <= unreadBefore, `${unreadBefore} → ${unreadAfter}`);

  // 10) folder create
  await p.click("button[aria-label='New folder']");
  await p.fill("input[aria-label='Folder name']", "Clients");
  await p.click("button:has-text('Create')");
  await p.waitForTimeout(2000);
  ok("custom folder created on the server", JSON.stringify(await ctl("/folders?user=santino@nxeon.cloud")).includes("Clients"));

  // 11) Filters page: preset preview + enable + apply now
  await p.goto(BASE + "/admin/mail/filters?mailbox=santino%40nxeon.cloud", { waitUntil: "domcontentloaded" });
  await p.waitForSelector("[data-testid=filters-page]");
  ok("filters page shows enforcement status honestly (sandbox: API not configured)", /not configured/i.test((await p.textContent("[data-testid=sync-badge]")) || ""));
  await p.click("role=tab[name=/Presets/]");
  await p.click("[data-preset=review-sellers] >> text=Preview");
  await p.waitForSelector("[data-preset=review-sellers] >> text=Would catch", { timeout: 30000 });
  ok("preset preview counts matches", /Would catch 1 /.test((await p.textContent("[data-preset=review-sellers]")) || ""), ((await p.textContent("[data-preset=review-sellers]")) || "").slice(-80));
  await p.click("[data-testid=enable-review-sellers]");
  await p.waitForTimeout(2500);
  await p.screenshot({ path: OUT + "/06-presets.png", fullPage: true });
  await p.click("role=tab[name=/Rules/]");
  await p.waitForSelector("[data-testid=rule-list] li");
  await p.click("[data-testid=rule-list] li >> text=Apply to existing mail");
  await p.waitForSelector("text=/matched/", { timeout: 60000 });
  const applied = await p.textContent("[role=status]");
  ok("apply-to-existing moved the review-seller pitch", /1 matched, 1 moved/.test(applied || ""), applied);
  const junk = await ctl("/dump?user=santino@nxeon.cloud&folder=Junk");
  ok("message is in Junk tagged $NxFiltered", junk.some((m) => /5-star/.test(m.subject || "") && m.flags.includes("$NxFiltered")));

  // 12) custom rule from the editor: DMARC → Reports/DMARC + read
  await p.click("[data-testid=new-rule]");
  await p.fill("[data-testid=rule-name]", "DMARC to folder");
  await p.fill("[data-testid=condition-value]", "Report Domain:");
  await p.fill("[data-testid=action-folder]", "Reports/DMARC");
  await p.click("[data-testid=rule-preview-btn]");
  await p.waitForSelector("[data-testid=rule-preview]", { timeout: 30000 });
  ok("rule editor preview", /\b1\b/.test((await p.textContent("[data-testid=rule-preview]")) || ""), (await p.textContent("[data-testid=rule-preview]"))?.slice(0, 80));
  await p.screenshot({ path: OUT + "/07-rule-editor.png", fullPage: true });
  await p.click("[data-testid=rule-save]");
  await p.waitForSelector("[data-testid=rule-list] li >> text=DMARC to folder", { timeout: 30000 });
  await p.click("[data-testid=rule-list] li:has-text('DMARC to folder') >> text=Apply to existing mail");
  await p.waitForTimeout(4000);
  const dmarc = await ctl("/dump?user=santino@nxeon.cloud&folder=Reports/DMARC");
  ok("custom rule → folder created + message filed", Array.isArray(dmarc) && dmarc.some((m) => /Report Domain/.test(m.subject || "")), JSON.stringify(dmarc).slice(0, 120));
  ok("rule persisted in DB", Number(psql("select count(*) from \"MailFilterRule\" where \"mailboxAddress\"='santino@nxeon.cloud'")) === 2);

  // 13) review queue + restore
  await p.click("role=tab[name=/Review/]");
  await p.waitForSelector("[data-testid=review-queue]", { timeout: 30000 });
  const rq = (await p.textContent("[data-testid=review-queue]")) || "";
  ok("review queue lists filtered mail", /5-star/.test(rq) && /Report Domain/.test(rq));
  await p.screenshot({ path: OUT + "/08-review.png", fullPage: true });
  await p.click("[data-review-item]:has-text('5-star') >> text='Restore'");
  await p.waitForTimeout(2500);
  const inbox = await ctl("/dump?user=santino@nxeon.cloud&folder=INBOX");
  ok("restore moves it back to the inbox without the tag", inbox.some((m) => /5-star/.test(m.subject || "") && !m.flags.includes("$NxFiltered")));

  // 14) block list
  await p.click("role=tab[name=/Blocked/]");
  await p.fill("input[aria-label='Blocked senders entry']", "seo-guru.test");
  await p.click("form:has(input[aria-label='Blocked senders entry']) button");
  await p.waitForTimeout(2000);
  ok("domain block saved and listed", /@seo-guru\.test/.test((await p.textContent("[data-testid=filters-page]")) || ""));

  // 15) mobile + light screenshots
  await p.setViewportSize({ width: 390, height: 844 });
  await p.goto(BASE + "/admin/mail", { waitUntil: "domcontentloaded" });
  await p.waitForSelector("[data-mail-uid]");
  await p.screenshot({ path: OUT + "/09-mobile-inbox.png" });
  await p.click("[data-mail-uid] >> nth=0");
  await p.waitForTimeout(2500);
  await p.screenshot({ path: OUT + "/10-mobile-read.png" });
  await p.goto(BASE + "/admin/mail/filters", { waitUntil: "domcontentloaded" });
  await p.waitForSelector("[data-testid=filters-page]");
  await p.screenshot({ path: OUT + "/11-mobile-filters.png", fullPage: true });
  await p.setViewportSize({ width: 1440, height: 900 });
  await p.goto(BASE + "/admin/mail", { waitUntil: "domcontentloaded" });
  await p.waitForSelector("[data-mail-uid]");
  await p.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
  await p.waitForTimeout(500);
  await p.screenshot({ path: OUT + "/12-light-inbox.png" });

  // 16) other Mail pages still render
  for (const path of ["/admin/mail/deliverability", "/admin/mail/mailboxes", "/admin/mail/templates"]) {
    const r = await p.goto(BASE + path, { waitUntil: "domcontentloaded" });
    ok(`${path} renders`, r && r.status() < 400 && !(await p.textContent("body")).includes("Application error"), String(r && r.status()));
  }
  await p.screenshot({ path: OUT + "/13-templates.png" });

  // 17) CUSTOMER Business Email — unchanged flows
  const c = await b.newContext({ viewport: { width: 1440, height: 900 } });
  await c.addCookies([{ name: "nxeon_session", value: T.customer, domain: "localhost", path: "/" }]);
  const q = await c.newPage();
  q.on("pageerror", (e) => errors.push("customer pageerror " + String(e).slice(0, 200)));
  await q.goto(BASE + "/dashboard/mail", { waitUntil: "domcontentloaded", timeout: 240000 });
  await q.waitForSelector("[data-mail-uid]", { timeout: 120000 });
  const cs = await q.$$eval("[data-mail-uid]", (els) => els.map((e) => e.querySelector("p")?.textContent || ""));
  ok("customer sees only their own mailbox", cs.some((s) => s.startsWith("[owner]")) && !cs.some((s) => /^\[(santino|support|contact|admin)\]/.test(s)), cs.slice(0, 2).join(" | "));
  ok("customer UI has no admin-only controls", (await q.$("text=Filters & spam")) === null && (await q.$("button[aria-label='New folder']")) === null);
  await q.click("[data-mail-uid] >> text=[owner] Invoice with attachment");
  await q.waitForSelector("a[href^='/api/mail/attachment']", { timeout: 30000 });
  const att = await q.getAttribute("a[href^='/api/mail/attachment']", "href");
  const attRes = await q.request.get(BASE + att);
  ok("customer attachment downloads from the right mailbox", attRes.status() === 200 && (await attRes.text()).includes("INVOICE 42"), String(attRes.status()));
  await q.click("button[aria-label='Star']");
  await q.waitForTimeout(1200);
  const ownerInbox = await ctl("/dump?user=owner@acme-biz.test&folder=INBOX");
  ok("customer star persists on the server", ownerInbox.some((m) => /Invoice with attachment/.test(m.subject || "") && m.flags.includes("\\Flagged")));
  await q.click("button[aria-label='Spam']");
  await q.waitForTimeout(1500);
  const ownerJunk = await ctl("/dump?user=owner@acme-biz.test&folder=Junk");
  ok("customer mark-spam moves to Junk", ownerJunk.some((m) => /Invoice with attachment/.test(m.subject || "")));
  await q.screenshot({ path: OUT + "/14-customer.png" });

  ok("no uncaught page errors", errors.filter((e) => e.startsWith("pageerror") || e.startsWith("customer pageerror")).length === 0, errors.slice(0, 5).join(" || "));
  console.log("\nconsole errors (first 10):\n" + errors.slice(0, 10).join("\n"));
  fs.writeFileSync(OUT + "/results.txt", results.join("\n") + "\n");
  await b.close();
})().catch((e) => {
  console.error("SCRIPT ERROR", e);
  fs.writeFileSync(OUT + "/results.txt", results.join("\n") + "\nSCRIPT ERROR " + String(e) + "\n");
  process.exit(1);
});

